_LIFECYCLE_TEMPLATE_CACHE: dict[str, dict[str, Any]] | None = None


def _exact_lifecycle_templates() -> dict[str, dict[str, Any]]:
    """Reuse TEST-029's closed schema fixtures as real serialized evidence."""

    global _LIFECYCLE_TEMPLATE_CACHE
    if _LIFECYCLE_TEMPLATE_CACHE is None:
        process = _schema_process_fixtures()
        candidate = _schema_candidate_fixtures(process)
        batch = _schema_batch_fixtures(process, candidate)
        _LIFECYCLE_TEMPLATE_CACHE = _schema_lifecycle_registry(process, candidate, batch)
    return copy.deepcopy(_LIFECYCLE_TEMPLATE_CACHE)


def _materialize_reconcile_fixture(
    root: Path,
    states: Sequence[str],
    *,
    actor: str,
    report_status: str | None,
    intent: dict[str, Any] | None = None,
    terminal_action: str | None = None,
    applied_receipt: bool = False,
    attempt_exists: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    assert len(states) == len(APPLY_PATHS)
    templates = _exact_lifecycle_templates()
    root_value = templates["quant-radar-ui-ux-formal-theme-handoff/v2"]
    root_path = root / "root-contract.json"
    _write_owned(root_path, _canonical(root_value))
    root_contract = _file_record(root_path, "root-contract.json")
    root_ref = {key: root_contract[key] for key in ("path", "sha256", "size")}
    root_sha = root_ref["sha256"]

    def source_from_artifact(logical_path: str, artifact: dict[str, Any]) -> dict[str, Any]:
        return {
            "path": logical_path,
            "sha256": artifact["sha256"],
            "size": artifact["size"],
            "mode": artifact["mode"],
        }

    live_preimage_files = _materialize_apply_tree(root, "pre")
    live_preimages = [
        {"source": source_from_artifact(relative, artifact), "artifact": artifact}
        for relative, artifact in zip(APPLY_PATHS, live_preimage_files)
    ]
    sealed_pre_root = root / ".fixture/sealed/pre"
    sealed_post_root = root / ".fixture/sealed/post"
    _materialize_apply_tree(sealed_pre_root, "pre")
    _materialize_apply_tree(sealed_post_root, "post")
    sealed_preimage_files = [
        _file_record(sealed_pre_root / relative, f".fixture/sealed/pre/{relative}")
        for relative in APPLY_PATHS
    ]
    sealed_postimage_files = [
        _file_record(sealed_post_root / relative, f".fixture/sealed/post/{relative}")
        for relative in APPLY_PATHS
    ]
    sealed_preimages = [
        {"source": source_from_artifact(relative, artifact), "artifact": artifact}
        for relative, artifact in zip(APPLY_PATHS, sealed_preimage_files)
    ]
    sealed_postimages = [
        {"source": source_from_artifact(relative, artifact), "artifact": artifact}
        for relative, artifact in zip(APPLY_PATHS, sealed_postimage_files)
    ]
    unknown_fingerprints: dict[str, Any] = {}
    for relative, state in zip(APPLY_PATHS, states):
        live = root / relative
        if state == "preimage":
            continue
        if state == "postimage":
            live.write_bytes((sealed_post_root / relative).read_bytes())
            os.chmod(live, 0o600)
        elif state == "unknown":
            live.write_bytes(f"unknown-{relative}\n".encode("utf-8"))
            os.chmod(live, 0o600)
            unknown_fingerprints[relative] = _path_fingerprint(live)
        elif state == "absent":
            live.unlink()
            unknown_fingerprints[relative] = _path_fingerprint(live)
        elif state == "directory":
            live.unlink()
            live.mkdir(mode=0o700)
            unknown_fingerprints[relative] = _path_fingerprint(live)
        elif state == "symlink":
            live.unlink()
            os.symlink("foreign-target", live)
            unknown_fingerprints[relative] = _path_fingerprint(live)
        else:
            raise AssertionError(f"unknown test state: {state}")

    evidence_root = root / ".claude/ui_snapshots/ux1b"
    evidence_root.mkdir(parents=True, exist_ok=True, mode=0o700)
    lease_path = evidence_root / f".theme-batch-postapply-{root_sha}.lease"
    _write_owned(lease_path, b"")
    lease_record = _file_record(lease_path, str(lease_path.relative_to(root)))

    attempt_path = evidence_root / f"theme-batch-attempt-{root_sha}.json"
    attempt_record: dict[str, Any] | None = None
    attempt_ref: dict[str, Any] | None = None
    if attempt_exists:
        attempt_value = templates["quant-radar-ui-ux-theme-batch-attempt/v1"]
        attempt_value["rootContract"] = root_ref
        attempt_value["livePreimages"] = live_preimages
        attempt_value["postApplyLease"] = lease_record
        _write_owned(attempt_path, _canonical(attempt_value))
        attempt_record = _file_record(attempt_path, str(attempt_path.relative_to(root)))
        attempt_ref = {key: attempt_record[key] for key in ("path", "sha256", "size")}

    report_record: dict[str, Any] | None = None
    report_ref: dict[str, Any] | None = None
    if report_status is not None:
        assert attempt_ref is not None
        report_value = _post_apply_report(attempt_ref)
        if report_status == "failed":
            report_value = copy.deepcopy(report_value)
            report_value["status"] = "failed"
            report_value["results"][0]["status"] = "failed"
            report_value["results"][0]["outcome"] = "internal"
            report_value["results"][0]["errorCode"] = "assertion_failed"
            report_value["passed"] = 3
            report_value["failed"] = 1
            report_value["resultsSha256"] = _sha256(_canonical(report_value["results"]))
            report_value["sha256"] = _sha256(_canonical({key: value for key, value in report_value.items() if key != "sha256"}))
        report_path = evidence_root / f"theme-batch-postapply-tests-{root_sha}.json"
        _write_owned(report_path, _canonical(report_value))
        report_record = _file_record(report_path, str(report_path.relative_to(root)))
        report_ref = {key: report_record[key] for key in ("path", "sha256", "size")}

    def current_live_images(current_states: Sequence[str]) -> list[dict[str, Any]]:
        images: list[dict[str, Any]] = []
        for relative, state in zip(APPLY_PATHS, current_states):
            path = root / relative
            if state in {"preimage", "postimage", "unknown"}:
                images.append(
                    {
                        "path": relative,
                        "kind": "present_regular",
                        "state": state,
                        "artifact": _file_record(path, relative),
                    }
                )
            elif state == "absent":
                images.append({"path": relative, "kind": "absent", "state": "unknown", "artifact": None})
            else:
                observed = os.lstat(path)
                images.append(
                    {
                        "path": relative,
                        "kind": "nonregular",
                        "state": "unknown",
                        "artifact": {
                            "path": relative,
                            "fileType": state,
                            "size": observed.st_size,
                            "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
                            "uid": observed.st_uid,
                            "gid": observed.st_gid,
                            "device": observed.st_dev,
                            "inode": observed.st_ino,
                            "nlink": observed.st_nlink,
                            "target": os.readlink(path) if state == "symlink" else None,
                        },
                    }
                )
        return images

    observed_current = current_live_images(states)

    intent_record: dict[str, Any] | None = None
    intent_value: dict[str, Any] | None = None
    intent_ref: dict[str, Any] | None = None
    if terminal_action == "rolled_back" and intent is None:
        intent = {"actor": actor, "plannedPaths": list(reversed(APPLY_PATHS))}
    if intent is not None:
        assert attempt_ref is not None
        intent_value = templates["quant-radar-ui-ux-theme-batch-rollback-intent/v1"]
        intent_value["actor"] = intent["actor"]
        intent_value["rootContract"] = root_ref
        intent_value["attempt"] = attempt_ref
        intent_value["postApplyTestReport"] = report_ref
        intent_value["observedStart"] = (
            observed_current
            if intent.get("containsUnknown")
            else [
                {
                    "path": relative,
                    "kind": "present_regular",
                    "state": "postimage",
                    "artifact": _file_record(root / relative, relative)
                    if states[index] == "postimage"
                    else {
                        **sealed_postimage_files[index],
                        "path": relative,
                    },
                }
                for index, relative in enumerate(APPLY_PATHS)
            ]
        )
        intent_value["plannedPaths"] = list(intent["plannedPaths"])
        intent_path = evidence_root / f"theme-batch-rollback-intent-{root_sha}.json"
        _write_owned(intent_path, _canonical(intent_value))
        intent_record = _file_record(intent_path, str(intent_path.relative_to(root)))
        intent_ref = {key: intent_record[key] for key in ("path", "sha256", "size")}

    terminal_record: dict[str, Any] | None = None
    if terminal_action is not None:
        assert attempt_ref is not None
        terminal_value = templates["quant-radar-ui-ux-theme-batch-reconciliation/v1"]
        terminal_value["status"] = terminal_action
        terminal_value["actor"] = actor
        terminal_value["rootContract"] = root_ref
        terminal_value["attempt"] = attempt_ref
        terminal_value["postApplyTestReport"] = report_ref
        terminal_value["rollbackIntent"] = intent_ref
        terminal_value["observedStart"] = observed_current
        terminal_value["action"] = {
            "verified_applied": "verify_only",
            "aborted_before_write": "no_write",
            "rolled_back": "rollback_reverse",
            "blocked_unknown": "no_write",
        }[terminal_action]
        terminal_value["finalState"] = observed_current
        terminal_value["affectedPaths"] = list(intent["plannedPaths"]) if terminal_action == "rolled_back" and intent is not None else []
        terminal_path = evidence_root / f"theme-batch-reconciliation-{root_sha}.json"
        _write_owned(terminal_path, _canonical(terminal_value))
        terminal_record = _file_record(terminal_path, str(terminal_path.relative_to(root)))

    applied_record: dict[str, Any] | None = None
    if applied_receipt:
        assert attempt_ref is not None
        applied_value = templates["quant-radar-ui-ux-theme-batch-applied/v1"]
        applied_value["rootContract"] = root_ref
        applied_value["attempt"] = attempt_ref
        applied_value["postApplyTestReport"] = report_ref
        applied_value["livePostimages"] = [
            {"source": source_from_artifact(relative, _file_record(root / relative, relative)), "artifact": _file_record(root / relative, relative)}
            for relative in APPLY_PATHS
        ]
        applied_path = evidence_root / f"theme-batch-applied-{root_sha}.json"
        _write_owned(applied_path, _canonical(applied_value))
        applied_record = _file_record(applied_path, str(applied_path.relative_to(root)))

    snapshot = {
        "actor": actor,
        "rootContract": {"artifact": root_contract, "value": root_value},
        "batchId": "batch-1",
        "themeRunId": "theme-1",
        "attempt": attempt_record,
        "postApplyTestReport": report_record,
        "rollbackIntent": {"artifact": intent_record, "value": intent_value} if intent_value is not None else None,
        "reconciliation": terminal_record,
        "appliedReceipt": applied_record,
        "livePreimages": live_preimages,
        "sealedPreimages": sealed_preimages,
        "sealedPostimages": sealed_postimages,
        "applyOrder": list(APPLY_PATHS),
    }
    oracle_state = {
        "rootSha": root_sha,
        "sealedPreRoot": sealed_pre_root,
        "sealedPostRoot": sealed_post_root,
        "sealedPreimages": sealed_preimages,
        "sealedPostimages": sealed_postimages,
        "unknownFingerprints": unknown_fingerprints,
    }
    return snapshot, oracle_state


class LifecycleFsRecorder:
    """OS-delegating recorder for evidence publication and rollback tests.

    It gives Task 2 a narrow injectable syscall surface while keeping the
    assertions grounded in files and inode identities in an owned directory.
    """

    def __init__(
        self,
        root: Path,
        *,
        fault: str | None = None,
        fault_occurrence: int = 1,
        post_fault: str | None = None,
        hooks: dict[str, Callable[[], None]] | None = None,
    ) -> None:
        self.root = root.resolve()
        self.fault = fault
        self.fault_occurrence = fault_occurrence
        self.post_fault = post_fault
        self.hooks = dict(hooks or {})
        self.calls: list[tuple[Any, ...]] = []
        self.write_paths: list[str] = []
        self.deleted_inodes: list[int] = []
        self._fd_paths: dict[int, str] = {}
        self._call_counts: dict[str, int] = {}

    def _resolve(self, relative: str) -> Path:
        candidate = (self.root / relative).resolve(strict=False)
        if candidate != self.root and self.root not in candidate.parents:
            raise AssertionError(f"recorder path escaped scratch root: {relative}")
        return candidate

    def record(self, name: str, *args: Any) -> None:
        specific = f"{name}:{args[0]}" if args else name
        hook = self.hooks.pop(specific, None)
        if hook is None and specific != name:
            hook = self.hooks.pop(name, None)
        if hook is not None:
            hook()
        self.calls.append((name, *args))
        self._call_counts[name] = self._call_counts.get(name, 0) + 1
        if self.fault == name and self._call_counts[name] == self.fault_occurrence:
            raise OSError(errno.EIO, f"injected {name}")

    def _raise_post_fault(self, name: str) -> None:
        if self.post_fault == name:
            self.calls.append(("post_fault", name))
            raise OSError(errno.EIO, f"injected post-{name}")

    def open_exclusive(self, relative: str, flags: int, mode: int) -> int:
        self.record("open_exclusive", relative, flags, mode)
        path = self._resolve(relative)
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        fd = os.open(path, flags, mode)
        self._fd_paths[fd] = relative
        return fd

    def write_all(self, fd: int, payload: bytes) -> None:
        relative = self._fd_paths[fd]
        self.record("write_all", relative, len(payload))
        self.write_paths.append(relative)
        view = memoryview(payload)
        while view:
            written = os.write(fd, view)
            assert written > 0
            view = view[written:]

    def set_metadata(self, fd: int, mode: int, uid: int, gid: int) -> None:
        relative = self._fd_paths[fd]
        self.record("set_metadata", relative, mode, uid, gid)
        os.fchmod(fd, mode)
        if (uid, gid) != (os.getuid(), os.getgid()):
            os.fchown(fd, uid, gid)

    def fsync_file(self, fd: int) -> None:
        relative = self._fd_paths[fd]
        self.record("fsync_file", relative)
        os.fsync(fd)

    def rehash(self, fd: int) -> str:
        relative = self._fd_paths[fd]
        self.record("rehash", relative)
        os.lseek(fd, 0, os.SEEK_SET)
        digest = hashlib.sha256()
        while chunk := os.read(fd, 131_072):
            digest.update(chunk)
        return digest.hexdigest()

    def rename_excl(self, source: str, destination: str) -> tuple[int, int]:
        source_path = self._resolve(source)
        destination_path = self._resolve(destination)
        source_inode = os.lstat(source_path).st_ino
        self.record("rename_excl", source, destination, source_inode)
        destination_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        if sys.platform == "darwin":
            assert source_path.parent == destination_path.parent
            rename_excl_flag = 0x00000004
            parent_fd = os.open(source_path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
            try:
                libc = ctypes.CDLL(None, use_errno=True)
                renameatx_np = libc.renameatx_np
                renameatx_np.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint)
                renameatx_np.restype = ctypes.c_int
                self.calls.append(("renameatx_np", source_path.name, destination_path.name, rename_excl_flag))
                if renameatx_np(
                    parent_fd,
                    os.fsencode(source_path.name),
                    parent_fd,
                    os.fsencode(destination_path.name),
                    rename_excl_flag,
                ) != 0:
                    error_number = ctypes.get_errno()
                    raise OSError(error_number, os.strerror(error_number), destination)
            finally:
                os.close(parent_fd)
        elif source_path.is_dir():
            if destination_path.exists() or destination_path.is_symlink():
                raise FileExistsError(errno.EEXIST, os.strerror(errno.EEXIST), destination)
            os.rename(source_path, destination_path)
        else:
            os.link(source_path, destination_path, follow_symlinks=False)
            os.unlink(source_path)
        destination_inode = os.lstat(destination_path).st_ino
        self.calls.append(("rename_excl_same_inode", source_inode, destination_inode))
        self._raise_post_fault("rename_excl")
        return source_inode, destination_inode

    def replace(self, source: str, destination: str) -> tuple[int, int]:
        source_path = self._resolve(source)
        destination_path = self._resolve(destination)
        source_inode = os.lstat(source_path).st_ino
        self.record("replace", source, destination, source_inode)
        os.replace(source_path, destination_path)
        destination_inode = os.lstat(destination_path).st_ino
        self.calls.append(("replace_same_inode", source_inode, destination_inode))
        self._raise_post_fault("replace")
        return source_inode, destination_inode

    def fsync_parent(self, relative: str = ".") -> None:
        self.record("fsync_parent", relative)
        fd = os.open(self._resolve(relative), os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
        self._raise_post_fault("fsync_parent")

    def reopen(self, relative: str, flags: int) -> int:
        path = self._resolve(relative)
        fd = os.open(path, flags)
        self._fd_paths[fd] = relative
        self.record("reopen", relative, flags, os.fstat(fd).st_ino)
        if self.post_fault == "reopen":
            self._fd_paths.pop(fd, None)
            os.close(fd)
            self._raise_post_fault("reopen")
        return fd

    def close(self, fd: int) -> None:
        self.record("close", self._fd_paths.get(fd, "<unknown>"))
        self._fd_paths.pop(fd, None)
        os.close(fd)

    def unlink_same_inode(self, relative: str, expected_inode: int) -> None:
        path = self._resolve(relative)
        observed = os.lstat(path)
        self.record("unlink_same_inode", relative, expected_inode, observed.st_ino)
        if observed.st_ino != expected_inode:
            raise handoff.ContractViolation("refusing to unlink a replaced inode")
        os.unlink(path)
        self.deleted_inodes.append(expected_inode)

    def rmdir_same_inode(self, relative: str, expected_inode: int) -> None:
        path = self._resolve(relative)
        observed = os.lstat(path)
        self.record("rmdir_same_inode", relative, expected_inode, observed.st_ino)
        if observed.st_ino != expected_inode:
            raise handoff.ContractViolation("refusing to remove a replaced directory inode")
        os.rmdir(path)
        self.deleted_inodes.append(expected_inode)

    @property
    def mutation_calls(self) -> tuple[tuple[Any, ...], ...]:
        names = {"open_exclusive", "write_all", "set_metadata", "rename_excl", "replace", "unlink_same_inode", "rmdir_same_inode"}
        return tuple(call for call in self.calls if call[0] in names)


class LiveImageFsRecorder:
    """Descriptor-relative observation surface for live-image classification."""

    def __init__(
        self,
        root: Path,
        parent_fd: int,
        *,
        deny_open: Sequence[str] = (),
        swap_on_second_lstat: dict[str, Callable[[], None]] | None = None,
        stat_overrides: dict[str, dict[str, int]] | None = None,
    ) -> None:
        self.root = root.resolve()
        self.parent_fd = parent_fd
        self.deny_open = set(deny_open)
        self.swap_on_second_lstat = dict(swap_on_second_lstat or {})
        self.stat_overrides = dict(stat_overrides or {})
        self.calls: list[tuple[Any, ...]] = []
        self._lstat_counts: dict[str, int] = {}
        self._fd_paths: dict[int, str] = {}

    @staticmethod
    def _validate_relative(relative: str) -> None:
        value = Path(relative)
        assert not value.is_absolute()
        assert relative not in {"", ".", ".."}
        assert ".." not in value.parts

    def lstat(self, relative: str) -> os.stat_result:
        self._validate_relative(relative)
        count = self._lstat_counts.get(relative, 0) + 1
        self._lstat_counts[relative] = count
        if count == 2 and relative in self.swap_on_second_lstat:
            self.swap_on_second_lstat.pop(relative)()
        self.calls.append(("lstat", relative, count))
        return self._override(relative, os.stat(relative, dir_fd=self.parent_fd, follow_symlinks=False))

    def _override(self, relative: str, observed: os.stat_result) -> os.stat_result:
        overrides = self.stat_overrides.get(relative)
        if not overrides:
            return observed
        fields = list(observed)
        indexes = {"mode": 0, "inode": 1, "device": 2, "nlink": 3, "uid": 4, "gid": 5, "size": 6}
        for key, value in overrides.items():
            fields[indexes[key]] = value
        return os.stat_result(fields)

    def open_read(self, relative: str, flags: int) -> int:
        self._validate_relative(relative)
        self.calls.append(("open_read", relative, flags))
        if relative in self.deny_open:
            raise PermissionError(errno.EACCES, os.strerror(errno.EACCES), relative)
        fd = os.open(relative, flags, dir_fd=self.parent_fd)
        self._fd_paths[fd] = relative
        return fd

    def fstat(self, fd: int) -> os.stat_result:
        relative = self._fd_paths[fd]
        self.calls.append(("fstat", relative))
        return self._override(relative, os.fstat(fd))

    def read(self, fd: int, size: int) -> bytes:
        self.calls.append(("read", self._fd_paths[fd], size))
        return os.read(fd, size)

    def readlink(self, relative: str) -> str:
        self._validate_relative(relative)
        self.calls.append(("readlink", relative))
        return os.readlink(relative, dir_fd=self.parent_fd)

    def close(self, fd: int) -> None:
        self.calls.append(("close", self._fd_paths.pop(fd)))
        os.close(fd)


def _sandbox_template_bytes(capability_id: str) -> bytes:
    head = ["version-1", "allow-default", "deny-process-exec", "allow-resolved-venv-python"]
    network_deny = ["deny-network-outbound", "deny-network-bind", "deny-network-inbound"]
    network_allow = {
        "candidate-basic-v1": [],
        "candidate-tcp-loopback-v1": ["allow-loopback-tcp-bind", "allow-loopback-tcp-inbound", "allow-loopback-tcp-outbound"],
        "candidate-udp-bind-v1": ["allow-loopback-udp-bind", "allow-loopback-udp-inbound"],
        "candidate-write-run-status-v1": [],
        "candidate-tcp-loopback-ux1b-v1": ["allow-loopback-tcp-bind", "allow-loopback-tcp-inbound", "allow-loopback-tcp-outbound"],
        "candidate-browser-tcp-unix-ux1b-v1": ["allow-loopback-tcp-bind", "allow-loopback-tcp-inbound", "allow-loopback-tcp-outbound", "allow-local-unix-bind", "allow-local-unix-inbound"],
    }
    write_base = ["deny-file-write", "allow-private-home", "allow-private-tmp", "allow-private-xdg-cache", "allow-private-xdg-config", "allow-private-xdg-data"]
    workspace_write = {
        "candidate-basic-v1": [],
        "candidate-tcp-loopback-v1": [],
        "candidate-udp-bind-v1": [],
        "candidate-write-run-status-v1": ["allow-candidate-run-status-write"],
        "candidate-tcp-loopback-ux1b-v1": ["allow-candidate-ux1b-write"],
        "candidate-browser-tcp-unix-ux1b-v1": ["allow-candidate-ux1b-write", "allow-candidate-ui-write"],
    }
    read_base = [
        "allow-dev-null-write",
        "deny-global-read-except",
        "deny-live-workspace-data-except-venv",
        "allow-candidate-read",
        "allow-private-environment-read",
        "allow-live-venv-read",
        "allow-base-python-runtime-read",
        "allow-system-runtime-read",
    ]
    browser = capability_id == "candidate-browser-tcp-unix-ux1b-v1"
    rule_ids = (
        head
        + (["allow-playwright-node-exec", "allow-headless-shell-exec"] if browser else [])
        + network_deny
        + network_allow[capability_id]
        + write_base
        + workspace_write[capability_id]
        + read_base
        + (["allow-headless-shell-runtime-read"] if browser else [])
    )
    return _canonical({"id": capability_id, "ruleIds": rule_ids})


def _absolute_path_record(path: Path) -> dict[str, Any]:
    absolute = path.absolute()
    observed = os.lstat(absolute)
    if stat.S_ISDIR(observed.st_mode):
        kind = "directory"
    elif stat.S_ISREG(observed.st_mode):
        kind = "regular"
    elif stat.S_ISLNK(observed.st_mode):
        kind = "symlink"
    else:
        kind = "special"
    return {
        "absolutePath": str(absolute),
        "kind": kind,
        "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
        "uid": observed.st_uid,
        "gid": observed.st_gid,
        "device": observed.st_dev,
        "inode": observed.st_ino,
        "nlink": observed.st_nlink,
    }


def _sandbox_profile_bindings(
    session_root: Path,
    candidate_root: Path,
    capability_id: str,
) -> dict[str, Any]:
    runtime = _runtime_receipt_fixture()
    capability_code = str(tuple(sorted(CAPABILITIES)).index(capability_id))
    private_paths = {
        role: session_root / f".p{capability_code}{role_code}"
        for role, role_code in {
            "home": "h", "tmp": "t", "cache": "a", "config": "g", "data": "d"
        }.items()
    }
    for path in private_paths.values():
        path.mkdir(mode=0o700)
    write_paths = {
        "candidateRunStatus": candidate_root / "reports/run_status",
        "candidateUx1b": candidate_root / ".claude/ui_snapshots/ux1b",
        "candidateUi": candidate_root / "ui",
    }
    for path in write_paths.values():
        path.mkdir(parents=True, exist_ok=True, mode=0o700)
    system_directories = tuple(
        Path(path)
        for path in ("/System", "/usr", "/Library/Apple/System/Library", "/Library/Fonts", "/private/etc", "/private/var/db/timezone")
    )
    system_files = tuple(Path(path) for path in ("/", "/dev/null", "/dev/urandom", "/dev/random", "/dev/dtracehelper"))
    direct_executables = {item["absolutePath"]: item for item in runtime["directExecutables"]}
    playwright_node = next(
        item
        for item in runtime["captureRuntime"]["executables"]
        if item["absolutePath"].endswith("/playwright/driver/node")
    )
    browser = capability_id == "candidate-browser-tcp-unix-ux1b-v1"
    environment = {
        "PATH": "/usr/bin:/bin:/usr/sbin:/sbin",
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "TZ": "UTC",
        "HOME": str(private_paths["home"]),
        "TMPDIR": str(private_paths["tmp"]),
        "TMP": str(private_paths["tmp"]),
        "TEMP": str(private_paths["tmp"]),
        "XDG_CACHE_HOME": str(private_paths["cache"]),
        "XDG_CONFIG_HOME": str(private_paths["config"]),
        "XDG_DATA_HOME": str(private_paths["data"]),
        "PYTHONHASHSEED": "0",
        "PYTHONNOUSERSITE": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONPATH": str(candidate_root),
        "STREAMLIT_BROWSER_GATHER_USAGE_STATS": "false",
        "NO_PROXY": "127.0.0.1,localhost,::1",
        "no_proxy": "127.0.0.1,localhost,::1",
    }
    if browser:
        environment["PLAYWRIGHT_BROWSERS_PATH"] = "/Users/ken/Library/Caches/ms-playwright"
        environment["PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD"] = "1"
    launcher = copy.deepcopy(runtime["python"]["launcher"])
    launcher["absolutePath"] = str(ROOT / launcher.pop("path"))
    value = {
        "schemaVersion": "quant-radar-ui-ux-sandbox-profile-bindings/v1",
        "sessionRoot": _absolute_path_record(session_root),
        "candidateRoot": _absolute_path_record(candidate_root),
        "privateEnvironment": {key: _absolute_path_record(path) for key, path in private_paths.items()},
        "workspaceWriteTargets": {key: _absolute_path_record(path) for key, path in write_paths.items()},
        "liveWorkspace": _absolute_path_record(ROOT),
        "liveVenv": runtime["python"]["sitePackages"],
        "basePythonRuntime": runtime["captureRuntime"]["pythonRuntimeRoots"][1],
        "systemRuntime": {
            "directories": [_absolute_path_record(path) for path in system_directories],
            "files": [_absolute_path_record(path) for path in system_files],
        },
        "headlessShellRuntime": runtime["candidateRuntime"]["headlessShellRuntime"] if browser else None,
        "executables": {
            "venvLauncher": launcher,
            "resolvedVenvPython": runtime["python"]["resolvedExecutable"],
            "playwrightNode": playwright_node if browser else None,
            "headlessShell": runtime["candidateRuntime"]["headlessShellExecutable"] if browser else None,
            "sandboxExec": direct_executables["/usr/bin/sandbox-exec"],
            "processObserver": direct_executables["/bin/ps"],
        },
        "environment": environment,
    }
    return {**value, "sha256": _sha256(_canonical(value))}


def _seatbelt_literal(value: str) -> str:
    assert "\0" not in value and "\n" not in value and "\r" not in value
    return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _sandbox_rendered_profile_fixture(
    capability: dict[str, Any],
    bindings: dict[str, Any],
) -> bytes:
    """Independent, plan-literal valid profile used by validator/regression tests."""

    def subpath(path: str) -> str:
        return f"(subpath {_seatbelt_literal(path)})"

    def literal(path: str) -> str:
        return f"(literal {_seatbelt_literal(path)})"

    capability_id = capability["id"]
    assert capability_id in CAPABILITIES
    private = bindings["privateEnvironment"]
    private_paths = [private[key]["absolutePath"] for key in ("home", "tmp", "cache", "config", "data")]
    system_directories = [row["absolutePath"] for row in bindings["systemRuntime"]["directories"]]
    system_files = [row["absolutePath"] for row in bindings["systemRuntime"]["files"]]
    read_filters = [
        subpath(bindings["candidateRoot"]["absolutePath"]),
        *(subpath(path) for path in private_paths),
        subpath(bindings["liveVenv"]["absolutePath"]),
        subpath(bindings["basePythonRuntime"]["absolutePath"]),
        *(subpath(path) for path in system_directories),
        *(literal(path) for path in system_files),
    ]
    if capability_id == "candidate-browser-tcp-unix-ux1b-v1":
        assert bindings["headlessShellRuntime"] is not None
        read_filters.append(subpath(bindings["headlessShellRuntime"]["absolutePath"]))

    lines = [
        "(version 1)",
        "(allow default)",
        "(deny process-exec)",
        f"(allow process-exec {literal(bindings['executables']['venvLauncher']['absolutePath'])})",
        f"(allow process-exec {literal(bindings['executables']['resolvedVenvPython']['absolutePath'])})",
    ]
    if capability_id == "candidate-browser-tcp-unix-ux1b-v1":
        lines.extend(
            (
                f"(allow process-exec {literal(bindings['executables']['playwrightNode']['absolutePath'])})",
                f"(allow process-exec {literal(bindings['executables']['headlessShell']['absolutePath'])})",
            )
        )
    lines.extend(
        (
            "(deny network-outbound)",
            "(deny network-bind)",
            "(deny network-inbound)",
        )
    )
    network_rules = {
        "none": (),
        "tcp-loopback": (
            '(allow network-bind (local tcp "localhost:*"))',
            '(allow network-inbound (local tcp "localhost:*"))',
            '(allow network-outbound (remote tcp "localhost:*"))',
        ),
        "udp-bind-inbound": (
            '(allow network-bind (local udp "localhost:*"))',
            '(allow network-inbound (local udp "localhost:*"))',
        ),
        "tcp-unix-loopback": (
            '(allow network-bind (local tcp "localhost:*"))',
            '(allow network-inbound (local tcp "localhost:*"))',
            '(allow network-outbound (remote tcp "localhost:*"))',
            "(allow network-bind (local unix))",
            "(allow network-inbound (local unix))",
        ),
    }
    lines.extend(network_rules[capability["network"]])
    lines.append("(deny file-write*)")
    lines.extend(f"(allow file-write* {subpath(path)})" for path in private_paths)
    workspace_bindings = {
        "candidate-run-status": "candidateRunStatus",
        "candidate-ux1b": "candidateUx1b",
        "candidate-ui": "candidateUi",
    }
    lines.extend(
        f"(allow file-write* {subpath(bindings['workspaceWriteTargets'][workspace_bindings[role]]['absolutePath'])})"
        for role in ("candidate-run-status", "candidate-ux1b", "candidate-ui")
        if role in capability["writeRoles"]
    )
    lines.extend(
        (
            '(allow file-write-data (literal "/dev/null"))',
            f"(deny file-read-data (require-not (require-any {' '.join(read_filters)})))",
            "(deny file-read-data (require-all "
            f"{subpath(bindings['liveWorkspace']['absolutePath'])} "
            f"(require-not {subpath(bindings['liveVenv']['absolutePath'])})))",
        )
    )
    lines.extend(f"(allow file-read* {read_filter})" for read_filter in read_filters)
    rendered = "\n".join(lines).encode("utf-8")
    assert rendered and not rendered.endswith(b"\n")
    return rendered


_PROBE_AUDIT_SITECUSTOMIZE_TEMPLATE = rb'''import atexit
import hashlib
import hmac
import json
import os
import stat
import sys


class _QuantRadarAuditHook:
    _EVENTS = frozenset({
        "import",
        "open",
        "os.exec",
        "os.listdir",
        "os.posix_spawn",
        "os.remove",
        "os.rename",
        "os.rmdir",
        "os.scandir",
        "socket.__new__",
        "socket.bind",
        "socket.connect",
        "socket.getaddrinfo",
        "socket.sendto",
        "subprocess.Popen",
    })

    def __init__(self, fd, secret):
        self._fd = fd
        self._secret = secret
        self._pipe_buf = os.fpathconf(fd, "PC_PIPE_BUF")
        self._previous = "0" * 64
        self._sequence = 0
        self._busy = False

    def _safe(self, value):
        if value is None or isinstance(value, (bool, int, float)):
            return value
        if isinstance(value, str):
            if len(value) <= 512:
                return value
            return {
                "kind": "string",
                "size": len(value),
                "prefix": value[:256],
                "sha256": hashlib.sha256(value.encode("utf-8")).hexdigest(),
            }
        if isinstance(value, bytes):
            return {
                "kind": "bytes",
                "size": len(value),
                "sha256": hashlib.sha256(value).hexdigest(),
            }
        if isinstance(value, (tuple, list)):
            return [self._safe(item) for item in value[:32]]
        if isinstance(value, dict):
            return {"mappingKeys": sorted(str(key) for key in value)[:32]}
        try:
            return self._safe(os.fspath(value))
        except TypeError:
            return {"type": type(value).__name__}

    def emit(self, event, arguments):
        if self._sequence >= __MAX_EVENTS__:
            os._exit(125)
        body = {
            "sequence": self._sequence,
            "previousSha256": self._previous,
            "pid": os.getpid(),
            "ppid": os.getppid(),
            "pgid": os.getpgrp(),
            "event": event,
            "arguments": self._safe(arguments),
        }
        encoded = json.dumps(
            body,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
        digest = hmac.new(
            self._secret,
            self._previous.encode("ascii") + encoded,
            hashlib.sha256,
        ).hexdigest()
        envelope = dict(body)
        envelope["sha256"] = digest
        line = json.dumps(
            envelope,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8") + b"\n"
        if len(line) > self._pipe_buf or os.write(self._fd, line) != len(line):
            os._exit(125)
        self._previous = digest
        self._sequence += 1

    @staticmethod
    def _project(event, arguments):
        if event == "import":
            return arguments[:1]
        if event == "open":
            return arguments[:3]
        if event in {
            "os.exec",
            "os.listdir",
            "os.posix_spawn",
            "os.remove",
            "os.rename",
            "os.rmdir",
            "os.scandir",
            "subprocess.Popen",
        }:
            return arguments[:1]
        if event.startswith("socket."):
            return arguments[:4]
        return ()

    def __call__(self, event, arguments):
        if self._busy or event not in self._EVENTS:
            return
        self._busy = True
        try:
            self.emit(event, self._project(event, arguments))
        finally:
            self._busy = False


_audit_fd = __AUDIT_FD__
_audit_stat = os.fstat(_audit_fd)
if not stat.S_ISFIFO(_audit_stat.st_mode):
    os._exit(125)
os.set_inheritable(_audit_fd, False)
atexit.register(os.close, _audit_fd)
_audit_hook = _QuantRadarAuditHook(
    _audit_fd,
    bytes.fromhex("__CHALLENGE_HEX__"),
)
_token = os.environ.get("QUANT_RADAR_UX1B_PROCESS_TOKEN", "")
_audit_hook.emit(
    "audit.header",
    ("__SCHEMA__", "__CHALLENGE_SHA256__"),
)
_audit_hook.emit(
    "audit.identity",
    (sys.executable, sys.prefix),
)
_audit_hook.emit(
    "audit.argv",
    (
        hashlib.sha256(
            json.dumps(
                list(sys.argv),
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False,
            ).encode("utf-8")
        ).hexdigest(),
    ),
)
_audit_hook.emit(
    "audit.token",
    (hashlib.sha256(_token.encode("ascii")).hexdigest() if _token else None,),
)
sys.addaudithook(_audit_hook)
del _audit_fd, _audit_stat, _audit_hook, _QuantRadarAuditHook, _token
'''


def _probe_audit_sitecustomize_bytes(challenge: bytes, audit_write_fd: int) -> bytes:
    assert len(challenge) == 32
    assert audit_write_fd > 2
    source = _PROBE_AUDIT_SITECUSTOMIZE_TEMPLATE
    source = source.replace(b"__SCHEMA__", PROBE_AUDIT_SCHEMA.encode("ascii"))
    source = source.replace(
        b"__CHALLENGE_SHA256__",
        _sha256(challenge).encode("ascii"),
    )
    source = source.replace(b"__CHALLENGE_HEX__", challenge.hex().encode("ascii"))
    source = source.replace(b"__MAX_EVENTS__", str(PROBE_AUDIT_MAX_EVENTS).encode("ascii"))
    source = source.replace(
        b"__AUDIT_FD__",
        str(audit_write_fd).encode("ascii"),
    )
    compile(source, "sitecustomize.py", "exec")
    return source


def _open_probe_audit_pipe(
) -> tuple[int, int, os.stat_result, os.stat_result]:
    """Create a pathless, parent-retained audit channel for one real child."""

    read_fd, write_fd = os.pipe()
    try:
        assert read_fd > 2 and write_fd > 2 and read_fd != write_fd
        os.set_inheritable(read_fd, False)
        os.set_inheritable(write_fd, False)
        os.set_blocking(read_fd, False)
        read_stat = os.fstat(read_fd)
        write_stat = os.fstat(write_fd)
        assert stat.S_ISFIFO(read_stat.st_mode) and read_stat.st_nlink == 0
        assert stat.S_ISFIFO(write_stat.st_mode) and write_stat.st_nlink == 0
        return read_fd, write_fd, read_stat, write_stat
    except BaseException:
        os.close(read_fd)
        os.close(write_fd)
        raise


def _close_probe_audit_pipe(
    read_fd: int,
    opened_read: os.stat_result,
    opened_write: os.stat_result,
    stream: bytes,
) -> list[dict[str, Any]]:
    try:
        final_fd_stat = os.fstat(read_fd)
        assert stat.S_ISFIFO(final_fd_stat.st_mode)
        assert (final_fd_stat.st_dev, final_fd_stat.st_ino) == (
            opened_read.st_dev,
            opened_read.st_ino,
        )
    finally:
        os.close(read_fd)
    assert 0 < len(stream) <= PROBE_AUDIT_MAX_STREAM_BYTES
    return [
        {
            "absolutePath": None,
            "fileType": "anonymous-pipe",
            "sha256": _sha256(stream),
            "size": len(stream),
            "readDevice": opened_read.st_dev,
            "readInode": opened_read.st_ino,
            "readNlink": opened_read.st_nlink,
            "writeDevice": opened_write.st_dev,
            "writeInode": opened_write.st_ino,
            "writeNlink": opened_write.st_nlink,
            "bytes": stream,
        }
    ]


def _sample_outer_process_table() -> list[dict[str, Any]]:
    completed = subprocess.run(
        ["/bin/ps", "-axo", "pid=,ppid=,pgid=,state=,command="],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
        timeout=2,
        env={"PATH": "/usr/bin:/bin:/usr/sbin:/sbin", "LANG": "C", "LC_ALL": "C"},
    )
    assert completed.returncode == 0 and completed.stderr == b""
    rows: list[dict[str, Any]] = []
    for raw_line in completed.stdout.decode("utf-8", errors="replace").splitlines():
        fields = raw_line.split(maxsplit=4)
        assert len(fields) == 5
        rows.append(
            {
                "pid": int(fields[0]),
                "ppid": int(fields[1]),
                "pgid": int(fields[2]),
                "state": fields[3],
                "command": fields[4],
            }
        )
    assert rows
    return rows


def _read_probe_regular_nofollow(path: Path) -> tuple[bytes, os.stat_result]:
    """Read one bounded regular probe input without following a replaced leaf."""

    before = os.lstat(path)
    assert stat.S_ISREG(before.st_mode) and before.st_nlink == 1
    assert before.st_size <= handoff.LIVE_IMAGE_HASH_LIMIT_BYTES
    flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    fd = os.open(path, flags)
    try:
        opened = os.fstat(fd)
        assert stat.S_ISREG(opened.st_mode) and opened.st_nlink == 1
        assert (opened.st_dev, opened.st_ino) == (before.st_dev, before.st_ino)
        chunks: list[bytes] = []
        remaining = opened.st_size
        while remaining:
            chunk = os.read(fd, min(65_536, remaining))
            assert chunk, "regular probe input ended before its authenticated size"
            chunks.append(chunk)
            remaining -= len(chunk)
        assert os.read(fd, 1) == b"", "regular probe input exceeded its authenticated size"
        after = os.fstat(fd)
        assert (
            after.st_dev,
            after.st_ino,
            after.st_size,
            after.st_mtime_ns,
        ) == (
            opened.st_dev,
            opened.st_ino,
            opened.st_size,
            opened.st_mtime_ns,
        )
    finally:
        os.close(fd)
    reopened = os.lstat(path)
    assert (reopened.st_dev, reopened.st_ino) == (opened.st_dev, opened.st_ino)
    return b"".join(chunks), opened


def _run_real_capability_probe_process(
    sandbox_argv: Sequence[str],
    *,
    cwd: str,
    environment: dict[str, str],
    timeout_seconds: int,
    stdout_limit_bytes: int,
    stderr_limit_bytes: int,
    audit_read_fd: int,
    audit_write_fd: int,
) -> dict[str, Any]:
    """Execute one real Seatbelt child and capture bounded raw process evidence."""

    try:
        process = subprocess.Popen(
            list(sandbox_argv),
            cwd=cwd,
            env=dict(environment),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            pass_fds=(audit_write_fd,),
            close_fds=True,
            start_new_session=True,
        )
    finally:
        # Only the primary child keeps the writer.  The audit hook marks it
        # close-on-exec before candidate code can create descendants.
        os.close(audit_write_fd)
    try:
        outer_process_samples = [_sample_outer_process_table()]
    except BaseException:
        _kill_fixture_group(process.pid)
        process.wait(timeout=5)
        _close_process_streams(process)
        raise
    assert process.stdout is not None and process.stderr is not None
    buffers = {"stdout": bytearray(), "stderr": bytearray()}
    audit_buffer = bytearray()
    streams = {
        process.stdout.fileno(): ("stdout", process.stdout),
        process.stderr.fileno(): ("stderr", process.stderr),
    }
    selector = selectors.DefaultSelector()
    timed_out = False
    overflow_stream: str | None = None
    deadline = time.monotonic() + timeout_seconds
    cleanup_deadline: float | None = None
    next_process_sample = time.monotonic() + 0.05
    try:
        for fd in streams:
            os.set_blocking(fd, False)
            selector.register(fd, selectors.EVENT_READ)
        os.set_blocking(audit_read_fd, False)
        selector.register(audit_read_fd, selectors.EVENT_READ)
        while streams:
            now = time.monotonic()
            if now >= next_process_sample:
                outer_process_samples.append(_sample_outer_process_table())
                next_process_sample = now + 0.05
            if cleanup_deadline is None and now >= deadline:
                timed_out = True
                cleanup_deadline = now + 5
                _kill_fixture_group(process.pid)
            if cleanup_deadline is not None and now >= cleanup_deadline:
                break
            active_deadline = cleanup_deadline if cleanup_deadline is not None else deadline
            ready = selector.select(timeout=min(0.05, max(0.0, active_deadline - now)))
            for key, _ in ready:
                fd = key.fd
                if fd == audit_read_fd:
                    try:
                        chunk = os.read(fd, 65_536)
                    except BlockingIOError:
                        continue
                    audit_buffer.extend(chunk)
                    assert len(audit_buffer) <= PROBE_AUDIT_MAX_STREAM_BYTES
                    continue
                role, stream = streams[fd]
                try:
                    chunk = os.read(fd, 65_536)
                except BlockingIOError:
                    continue
                if not chunk:
                    selector.unregister(fd)
                    stream.close()
                    del streams[fd]
                    continue
                limit = stdout_limit_bytes if role == "stdout" else stderr_limit_bytes
                payload = buffers[role]
                retained = max(0, (limit + 1) - len(payload))
                payload.extend(chunk[:retained])
                if len(payload) > limit and overflow_stream is None:
                    overflow_stream = role
                    cleanup_deadline = time.monotonic() + 5
                    _kill_fixture_group(process.pid)
        if process.poll() is None:
            if cleanup_deadline is None:
                try:
                    process.wait(timeout=max(0.1, deadline - time.monotonic()))
                except subprocess.TimeoutExpired:
                    timed_out = True
                    cleanup_deadline = time.monotonic() + 5
                    _kill_fixture_group(process.pid)
            if process.poll() is None:
                assert cleanup_deadline is not None
                process.wait(timeout=max(0.1, cleanup_deadline - time.monotonic()))
        else:
            process.wait(timeout=0)
        while True:
            try:
                chunk = os.read(audit_read_fd, 65_536)
            except BlockingIOError:
                break
            if not chunk:
                break
            audit_buffer.extend(chunk)
            assert len(audit_buffer) <= PROBE_AUDIT_MAX_STREAM_BYTES
    finally:
        selector.close()
        for _role, stream in streams.values():
            if not stream.closed:
                stream.close()
        if process.poll() is None:
            _kill_fixture_group(process.pid)
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired as exc:
                raise AssertionError("real capability probe could not be reaped") from exc

    raw_return_code = process.returncode
    assert isinstance(raw_return_code, int)
    outer_final_process_table = _sample_outer_process_table()
    return {
        "process": process,
        "processGroupId": process.pid,
        "returnCode": raw_return_code if raw_return_code >= 0 else None,
        "signal": -raw_return_code if raw_return_code < 0 else None,
        "stdout": bytes(buffers["stdout"]),
        "stderr": bytes(buffers["stderr"]),
        "timedOut": timed_out,
        "overflowStream": overflow_stream,
        "auditStream": bytes(audit_buffer),
        "outerProcessTable": [
            row
            for sample in outer_process_samples
            for row in sample
        ],
        "outerFinalProcessTable": outer_final_process_table,
    }


def _probe_outcome_fixture(assertion_id: str, expected_outcome: str) -> dict[str, Any]:
    """Independent schema oracle; the real probe driver must never call this helper."""

    if expected_outcome == "succeeded":
        return {
            "id": assertion_id,
            "expectedOutcome": "succeeded",
            "actualOutcome": "succeeded",
            "errorClass": None,
            "errorCode": None,
            "returnCode": 0 if assertion_id in CHILD_PROBE_IDS else None,
            "signal": None,
            "passed": True,
        }
    assert expected_outcome == "denied"
    is_dns = assertion_id == "dns-resolution-denied"
    return {
        "id": assertion_id,
        "expectedOutcome": "denied",
        "actualOutcome": "denied",
        "errorClass": "gaierror" if is_dns else "PermissionError",
        "errorCode": "EAI_NONAME" if is_dns else "EPERM",
        "returnCode": 0 if assertion_id in CHILD_PROBE_IDS else None,
        "signal": None,
        "passed": True,
    }


def _probe_browser_fixture() -> dict[str, Any]:
    """Independent schema oracle; the real probe driver must never call this helper."""

    runtime = _runtime_receipt_fixture()
    node = next(
        row
        for row in runtime["captureRuntime"]["executables"]
        if row["absolutePath"].endswith("/playwright/driver/node")
    )
    return {
        "apiExecutablePath": runtime["chromium"]["executablePath"],
        "defaultExecutablePath": runtime["candidateRuntime"]["headlessShellExecutable"]["absolutePath"],
        "expectedVersion": runtime["chromium"]["version"],
        "observedVersion": runtime["chromium"]["version"],
        "defaultExecutableMatchesCandidateLeaf": True,
        "defaultExecutableSha256": runtime["candidateRuntime"]["headlessShellExecutable"]["sha256"],
        "nodeSha256": node["sha256"],
        "launched": True,
        "pageCreated": True,
        "closed": True,
        "childrenQuiescent": True,
    }


_REAL_CANDIDATE_REGRESSION_PROCESS_DRIVER = (
    handoff._CandidateRegressionProcessDriver
)


class CapabilityProbeDriverRecorder:
    """Run each exact Seatbelt child and retain only raw process evidence."""

    def __init__(
        self,
        plans: Sequence[dict[str, Any]],
        *,
        session_root: Path,
        candidate_root: Path,
        probe_module_sha256: str,
        audit_challenge: bytes,
    ) -> None:
        self._plans = {plan["id"]: plan for plan in plans}
        self._session_root = session_root
        self._candidate_root = candidate_root
        assert len(probe_module_sha256) == 64
        assert all(character in "0123456789abcdef" for character in probe_module_sha256)
        self._probe_module_path = candidate_root / "scripts/ui_ux_theme_handoff.py"
        module_bytes, _ = _read_probe_regular_nofollow(self._probe_module_path)
        assert _sha256(module_bytes) == probe_module_sha256
        for forbidden in (
            b"sitecustomize",
            b"quant-radar-probe-audit",
            b"sys.addaudithook",
            b"gc.get_objects",
        ):
            assert forbidden not in module_bytes, (
                "candidate probe source attempted to inspect test-owned audit internals"
            )
        self._probe_module_sha256 = probe_module_sha256
        assert len(audit_challenge) == 32
        self._audit_challenge = audit_challenge
        self._audit_sitecustomize_path = candidate_root / "sitecustomize.py"
        assert not self._audit_sitecustomize_path.exists()
        self.observations: dict[str, dict[str, Any]] = {}
        self._private_roots: set[str] = set()
        self._raw_tokens: set[str] = set()
        self.canary_artifact: dict[str, Any] | None = None
        self.snapshot_observation: dict[str, Any] | None = None
        self.command_observations: dict[str, dict[str, Any]] = {}

    @staticmethod
    def _raw_process_result(
        execution: dict[str, Any],
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        process_group_id = execution["processGroupId"]
        return_code = execution["returnCode"]
        signal_number = execution["signal"]
        wait_status = (
            return_code << 8
            if return_code is not None
            else signal_number
        )
        assert type(wait_status) is int

        def sample(
            phase: str,
            rows: list[dict[str, Any]],
            process_table: Sequence[dict[str, Any]],
        ) -> dict[str, Any]:
            raw = _canonical(process_table)
            return {
                "phase": phase,
                "observerPid": process_group_id + 1,
                "observerProcessGroupId": process_group_id + 1,
                "rows": rows,
                "observerReturnCode": 0,
                "observerSignal": None,
                "stdoutSha256": _sha256(raw),
                "stderrSha256": EMPTY_SHA256,
                "stdoutBytes": len(raw),
                "stderrBytes": 0,
                "runnerStdoutEof": True,
                "runnerStderrEof": True,
            }

        family = _REAL_CANDIDATE_REGRESSION_PROCESS_DRIVER._family_receipt(
            process_family_plan=process_family_plan,
            process_group_id=process_group_id,
            exit_watch_result={
                "registration": "registered",
                "outcome": "note_exit",
                "eventCount": 1,
            },
            samples=(
                sample(
                    "pre_reap",
                    [
                        {
                            "pid": process_group_id,
                            "uid": os.getuid(),
                            "processGroupId": process_group_id,
                            "state": "Z",
                            "waitStatus": wait_status,
                            "markerMatch": False,
                        }
                    ],
                    execution["outerProcessTable"],
                ),
                sample(
                    "post_reap",
                    [],
                    execution["outerFinalProcessTable"],
                ),
            ),
            return_code=return_code,
            signal_number=signal_number,
            wait_status=wait_status,
        )
        now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        return {
            "returnCode": return_code,
            "signal": signal_number,
            "stdout": execution["stdout"],
            "stderr": execution["stderr"],
            "processGroupId": process_group_id,
            "timedOut": execution["timedOut"],
            "overflowStream": execution["overflowStream"],
            "startedAt": now,
            "finishedAt": now,
            "processFamily": family,
        }

    def run_probe(
        self,
        *,
        capability_id: str,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        denied_read_canary: str,
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        assert capability_id in self._plans
        assert capability_id not in self.observations, "a capability probe was spawned more than once"
        assert list(self.observations) == sorted(CAPABILITIES)[: len(self.observations)]
        plan = self._plans[capability_id]
        bindings = plan["bindings"]
        runtime = _runtime_receipt_fixture()

        private_paths = [
            bindings["privateEnvironment"][key]["absolutePath"]
            for key in ("home", "tmp", "cache", "config", "data")
        ]
        assert len(private_paths) == len(set(private_paths)) == 5
        assert not (self._private_roots & set(private_paths)), "private roots were reused across probes"
        for key, path in zip(("home", "tmp", "cache", "config", "data"), private_paths):
            assert _absolute_path_record(Path(path)) == bindings["privateEnvironment"][key]
            assert Path(path).parent == self._session_root
        self._private_roots.update(private_paths)

        canary_path = Path(denied_read_canary)
        assert canary_path.is_absolute() and canary_path.parent == self._session_root
        assert canary_path != self._candidate_root and str(canary_path) not in self._private_roots
        observed = os.lstat(canary_path)
        assert stat.S_ISREG(observed.st_mode)
        assert stat.S_IMODE(observed.st_mode) == 0o600
        assert observed.st_uid == os.getuid() and observed.st_nlink == 1
        assert canary_path.read_bytes() == PROBE_CANARY_BYTES
        artifact = _external_file(
            str(canary_path),
            PROBE_CANARY_SHA256,
            len(PROBE_CANARY_BYTES),
            "0600",
            observed.st_uid,
            observed.st_gid,
            observed.st_dev,
            observed.st_ino,
        )
        if self.canary_artifact is None:
            self.canary_artifact = artifact
        else:
            assert artifact == self.canary_artifact, "probe canary identity or bytes changed"

        expected_argv = [
            bindings["executables"]["venvLauncher"]["absolutePath"],
            "-B",
            "-c",
            handoff.PROBE_BOOTSTRAP,
            "--",
            "--capability-id",
            capability_id,
            "--process-token-sha",
            process_family_plan["tokenSha256"],
            "--candidate-root",
            str(self._candidate_root),
            "--live-source",
            str(ROOT / "Makefile"),
            "--denied-read-canary",
            str(canary_path),
            "--real-ssh-dir",
            "/Users/ken/.ssh",
            "--playwright-cache-root",
            "/Users/ken/Library/Caches/ms-playwright",
            "--api-browser-executable",
            runtime["chromium"]["executablePath"],
            "--headless-shell-executable",
            runtime["candidateRuntime"]["headlessShellExecutable"]["absolutePath"],
        ]
        assert list(argv) == expected_argv
        assert cwd == str(self._candidate_root)
        assert rendered_profile == plan["profile"]

        expected_family = copy.deepcopy(_schema_process_fixtures()["tokenPlan"])
        raw_token = environment[PROCESS_TOKEN_ENVIRONMENT_KEY]
        assert len(raw_token) == 69 and raw_token.startswith("ux1b_")
        assert all(character in "0123456789abcdef" for character in raw_token[5:])
        assert raw_token not in self._raw_tokens, "a raw process-family token was reused"
        self._raw_tokens.add(raw_token)
        expected_family["tokenSha256"] = _sha256(raw_token.encode("ascii"))
        assert process_family_plan == expected_family
        expected_environment = {
            **bindings["environment"],
            PROCESS_TOKEN_ENVIRONMENT_KEY: raw_token,
        }
        assert environment == expected_environment

        module_before, _ = _read_probe_regular_nofollow(self._probe_module_path)
        module_sha256_before = _sha256(module_before)
        assert module_sha256_before == self._probe_module_sha256
        sandbox_record = bindings["executables"]["sandboxExec"]
        sandbox_path = Path(sandbox_record["absolutePath"])
        assert sandbox_path == Path("/usr/bin/sandbox-exec")
        sandbox_bytes, sandbox_stat = _read_probe_regular_nofollow(sandbox_path)
        assert sandbox_record == {
            "absolutePath": str(sandbox_path),
            "sha256": _sha256(sandbox_bytes),
            "size": len(sandbox_bytes),
            "mode": f"{stat.S_IMODE(sandbox_stat.st_mode):04o}",
            "uid": sandbox_stat.st_uid,
            "gid": sandbox_stat.st_gid,
            "device": sandbox_stat.st_dev,
            "inode": sandbox_stat.st_ino,
            "nlink": sandbox_stat.st_nlink,
        }
        profile_text = rendered_profile.decode("utf-8", errors="strict")
        sandbox_argv = [str(sandbox_path), "-p", profile_text, *expected_argv]
        timeout_seconds = 180 if capability_id == "candidate-browser-tcp-unix-ux1b-v1" else 120
        (
            audit_read_fd,
            audit_write_fd,
            audit_read_stat,
            audit_write_stat,
        ) = _open_probe_audit_pipe()
        audit_pipe_closed = False
        audit_sitecustomize_source = _probe_audit_sitecustomize_bytes(
            self._audit_challenge,
            audit_write_fd,
        )
        audit_sitecustomize_sha256 = _sha256(audit_sitecustomize_source)
        assert not self._audit_sitecustomize_path.exists()
        _write_owned(
            self._audit_sitecustomize_path,
            audit_sitecustomize_source,
            0o400,
        )
        audit_source_before, _ = _read_probe_regular_nofollow(self._audit_sitecustomize_path)
        audit_source_sha256_before = _sha256(audit_source_before)
        assert audit_source_sha256_before == audit_sitecustomize_sha256
        try:
            execution = _run_real_capability_probe_process(
                sandbox_argv,
                cwd=cwd,
                environment=environment,
                timeout_seconds=timeout_seconds,
                stdout_limit_bytes=1_048_576,
                stderr_limit_bytes=1_048_576,
                audit_read_fd=audit_read_fd,
                audit_write_fd=audit_write_fd,
            )
            assert execution["auditStream"], (
                "probe produced no parent-owned anonymous-pipe audit bytes: "
                + repr(
                    {
                        "returnCode": execution["returnCode"],
                        "signal": execution["signal"],
                        "stderr": execution["stderr"][:512],
                    }
                )
            )
            raw_audit_files = _close_probe_audit_pipe(
                audit_read_fd,
                audit_read_stat,
                audit_write_stat,
                execution["auditStream"],
            )
            audit_pipe_closed = True
        finally:
            if not audit_pipe_closed:
                for fd in (audit_read_fd, audit_write_fd):
                    try:
                        os.close(fd)
                    except OSError:
                        pass
            audit_source_after, audit_stat_after = _read_probe_regular_nofollow(
                self._audit_sitecustomize_path
            )
            audit_source_sha256_after = _sha256(audit_source_after)
            assert audit_source_sha256_after == audit_source_sha256_before
            current_audit_stat = os.lstat(self._audit_sitecustomize_path)
            assert (current_audit_stat.st_dev, current_audit_stat.st_ino) == (
                audit_stat_after.st_dev,
                audit_stat_after.st_ino,
            )
            os.unlink(self._audit_sitecustomize_path)
            candidate_parent_fd = os.open(
                self._candidate_root,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                os.fsync(candidate_parent_fd)
            finally:
                os.close(candidate_parent_fd)
            assert not self._audit_sitecustomize_path.exists()
        module_after, _ = _read_probe_regular_nofollow(self._probe_module_path)
        module_sha256_after = _sha256(module_after)
        assert module_sha256_after == module_sha256_before
        canary_after_bytes, canary_after = _read_probe_regular_nofollow(canary_path)
        assert (
            canary_after.st_dev,
            canary_after.st_ino,
            canary_after.st_size,
            stat.S_IMODE(canary_after.st_mode),
            canary_after.st_uid,
            canary_after.st_gid,
            canary_after.st_nlink,
        ) == (
            observed.st_dev,
            observed.st_ino,
            observed.st_size,
            0o600,
            observed.st_uid,
            observed.st_gid,
            1,
        )
        assert canary_after_bytes == PROBE_CANARY_BYTES
        self.observations[capability_id] = {
            "argv": expected_argv,
            "sandboxArgv": sandbox_argv,
            "cwd": cwd,
            "publicEnvironment": copy.deepcopy(bindings["environment"]),
            "rawToken": raw_token,
            "processFamilyPlan": copy.deepcopy(process_family_plan),
            "renderedProfileSha256": _sha256(rendered_profile),
            "canaryArtifact": copy.deepcopy(artifact),
            "candidateProbeModulePath": str(self._probe_module_path),
            "candidateProbeModuleSha256Before": module_sha256_before,
            "candidateProbeModuleSha256After": module_sha256_after,
            "probeAuditSitecustomizePath": str(self._audit_sitecustomize_path),
            "probeAuditSitecustomizeSha256Before": audit_source_sha256_before,
            "probeAuditSitecustomizeSha256After": audit_source_sha256_after,
            "rawAuditChallenge": self._audit_challenge,
            "rawAuditFiles": raw_audit_files,
            "testInstrumentationPassFds": [audit_write_fd],
            "sandboxExecSha256": _sha256(sandbox_bytes),
            "timeoutSeconds": timeout_seconds,
            "stdoutLimitBytes": 1_048_576,
            "stderrLimitBytes": 1_048_576,
            "stdin": "devnull",
            "passFds": [],
            "processGroup": "new",
            "process": execution["process"],
            "spawnedPid": execution["process"].pid,
            "processGroupId": execution["processGroupId"],
            "returnCode": execution["returnCode"],
            "signal": execution["signal"],
            "rawStdout": execution["stdout"],
            "rawStderr": execution["stderr"],
            "timedOut": execution["timedOut"],
            "overflowStream": execution["overflowStream"],
            "outerProcessTable": execution["outerProcessTable"],
            "outerFinalProcessTable": execution["outerFinalProcessTable"],
        }
        return self._raw_process_result(execution, process_family_plan)

    def run_snapshot_subset(
        self,
        *,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        assert self.snapshot_observation is None
        plan = self._plans["candidate-browser-tcp-unix-ux1b-v1"]
        bindings = plan["bindings"]
        expected_argv = [
            bindings["executables"]["venvLauncher"]["absolutePath"],
            "-B",
            "-c",
            handoff.SNAPSHOT_SUBSET_BOOTSTRAP,
        ]
        assert list(argv) == expected_argv
        assert cwd == str(self._candidate_root)
        assert rendered_profile != plan["profile"]
        assert _sha256(rendered_profile) != plan["renderedProfileSha256"]
        raw_token = environment[PROCESS_TOKEN_ENVIRONMENT_KEY]
        assert len(raw_token) == 69 and raw_token.startswith("ux1b_")
        assert raw_token not in self._raw_tokens
        self._raw_tokens.add(raw_token)
        expected_family = copy.deepcopy(_schema_process_fixtures()["tokenPlan"])
        expected_family["tokenSha256"] = _sha256(raw_token.encode("ascii"))
        assert process_family_plan == expected_family
        expected_environment = copy.deepcopy(bindings["environment"])
        for key, suffix in (
            ("HOME", "h"),
            ("TMPDIR", "t"),
            ("TMP", "t"),
            ("TEMP", "t"),
            ("XDG_CACHE_HOME", "a"),
            ("XDG_CONFIG_HOME", "g"),
            ("XDG_DATA_HOME", "d"),
        ):
            expected_environment[key] = str(self._session_root / f".c018{suffix}")
        assert environment == {
            **expected_environment,
            PROCESS_TOKEN_ENVIRONMENT_KEY: raw_token,
        }
        assert all(
            path.encode("utf-8") in rendered_profile
            for path in {
                expected_environment["HOME"],
                expected_environment["TMPDIR"],
                expected_environment["XDG_CACHE_HOME"],
                expected_environment["XDG_CONFIG_HOME"],
                expected_environment["XDG_DATA_HOME"],
            }
        )
        sandbox_record = bindings["executables"]["sandboxExec"]
        sandbox_path = Path(sandbox_record["absolutePath"])
        sandbox_bytes, sandbox_stat = _read_probe_regular_nofollow(sandbox_path)
        assert sandbox_record == {
            "absolutePath": str(sandbox_path),
            "sha256": _sha256(sandbox_bytes),
            "size": len(sandbox_bytes),
            "mode": f"{stat.S_IMODE(sandbox_stat.st_mode):04o}",
            "uid": sandbox_stat.st_uid,
            "gid": sandbox_stat.st_gid,
            "device": sandbox_stat.st_dev,
            "inode": sandbox_stat.st_ino,
            "nlink": sandbox_stat.st_nlink,
        }
        sandbox_argv = [
            str(sandbox_path),
            "-p",
            rendered_profile.decode("utf-8", errors="strict"),
            *expected_argv,
        ]
        audit_read_fd, audit_write_fd = os.pipe()
        try:
            execution = _run_real_capability_probe_process(
                sandbox_argv,
                cwd=cwd,
                environment=environment,
                timeout_seconds=120,
                stdout_limit_bytes=65_536,
                stderr_limit_bytes=65_536,
                audit_read_fd=audit_read_fd,
                audit_write_fd=audit_write_fd,
            )
        finally:
            try:
                os.close(audit_read_fd)
            except OSError:
                pass
        self.snapshot_observation = {
            "argv": expected_argv,
            "sandboxArgv": sandbox_argv,
            "cwd": cwd,
            "publicEnvironment": copy.deepcopy(bindings["environment"]),
            "rawToken": raw_token,
            "processFamilyPlan": copy.deepcopy(process_family_plan),
            "renderedProfileSha256": _sha256(rendered_profile),
            "process": execution["process"],
            "spawnedPid": execution["process"].pid,
            "processGroupId": execution["processGroupId"],
            "returnCode": execution["returnCode"],
            "signal": execution["signal"],
            "rawStdout": execution["stdout"],
            "rawStderr": execution["stderr"],
            "timedOut": execution["timedOut"],
            "overflowStream": execution["overflowStream"],
            "outerProcessTable": execution["outerProcessTable"],
            "outerFinalProcessTable": execution["outerFinalProcessTable"],
        }
        return self._raw_process_result(execution, process_family_plan)

    def run_candidate_command(
        self,
        *,
        command_id: str,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        process_family_plan: dict[str, Any],
        timeout_seconds: int,
        stdout_limit_bytes: int,
        stderr_limit_bytes: int,
    ) -> dict[str, Any]:
        assert command_id not in self.command_observations
        row = next(
            item for item in handoff.CANDIDATE_REGRESSION_ROWS
            if item[0] == command_id
        )
        _identifier, script, capability_id, expected_timeout = row
        assert command_id not in {"POST-018", "POST-031"}
        assert isinstance(capability_id, str)
        assert expected_timeout == timeout_seconds
        if command_id == "POST-037":
            expected_argv = [
                str(ROOT / ".venv/bin/python"),
                "-B",
                "-m",
                "pip",
                "check",
            ]
        else:
            assert isinstance(script, str)
            expected_argv = [
                str(ROOT / ".venv/bin/python"),
                "-B",
                script,
            ]
        assert list(argv) == expected_argv
        assert cwd == str(self._candidate_root)
        assert stdout_limit_bytes == stderr_limit_bytes == 1_048_576
        raw_token = environment[PROCESS_TOKEN_ENVIRONMENT_KEY]
        assert len(raw_token) == 69 and raw_token.startswith("ux1b_")
        assert raw_token not in self._raw_tokens
        self._raw_tokens.add(raw_token)
        expected_family = copy.deepcopy(_schema_process_fixtures()["tokenPlan"])
        expected_family["tokenSha256"] = _sha256(raw_token.encode("ascii"))
        assert process_family_plan == expected_family
        command_index = int(command_id.removeprefix("POST-"))
        plan_bindings = self._plans[capability_id]["bindings"]
        expected_environment = copy.deepcopy(plan_bindings["environment"])
        for key, suffix in (
            ("HOME", "h"),
            ("TMPDIR", "t"),
            ("TMP", "t"),
            ("TEMP", "t"),
            ("XDG_CACHE_HOME", "a"),
            ("XDG_CONFIG_HOME", "g"),
            ("XDG_DATA_HOME", "d"),
        ):
            expected_environment[key] = str(
                self._session_root / f".c{command_index:03d}{suffix}"
            )
        assert environment == {
            **expected_environment,
            PROCESS_TOKEN_ENVIRONMENT_KEY: raw_token,
        }
        assert all(
            path.encode("utf-8") in rendered_profile
            for path in {
                expected_environment["HOME"],
                expected_environment["TMPDIR"],
                expected_environment["XDG_CACHE_HOME"],
                expected_environment["XDG_CONFIG_HOME"],
                expected_environment["XDG_DATA_HOME"],
            }
        )
        sandbox_path = Path("/usr/bin/sandbox-exec")
        sandbox_argv = [
            str(sandbox_path),
            "-p",
            rendered_profile.decode("utf-8", errors="strict"),
            *expected_argv,
        ]
        audit_read_fd, audit_write_fd = os.pipe()
        try:
            execution = _run_real_capability_probe_process(
                sandbox_argv,
                cwd=cwd,
                environment=environment,
                timeout_seconds=timeout_seconds,
                stdout_limit_bytes=stdout_limit_bytes,
                stderr_limit_bytes=stderr_limit_bytes,
                audit_read_fd=audit_read_fd,
                audit_write_fd=audit_write_fd,
            )
        finally:
            try:
                os.close(audit_read_fd)
            except OSError:
                pass
        self.command_observations[command_id] = {
            "argv": expected_argv,
            "sandboxArgv": sandbox_argv,
            "cwd": cwd,
            "publicEnvironment": expected_environment,
            "rawToken": raw_token,
            "processFamilyPlan": copy.deepcopy(process_family_plan),
            "renderedProfileSha256": _sha256(rendered_profile),
            "process": execution["process"],
            "spawnedPid": execution["process"].pid,
            "processGroupId": execution["processGroupId"],
            "returnCode": execution["returnCode"],
            "signal": execution["signal"],
            "rawStdout": execution["stdout"],
            "rawStderr": execution["stderr"],
            "timedOut": execution["timedOut"],
            "overflowStream": execution["overflowStream"],
            "outerProcessTable": execution["outerProcessTable"],
            "outerFinalProcessTable": execution["outerFinalProcessTable"],
        }
        return self._raw_process_result(execution, process_family_plan)

    def assert_complete(self) -> None:
        assert list(self.observations) == sorted(CAPABILITIES)
        assert self.snapshot_observation is not None
        expected_commands = [
            row[0]
            for row in handoff.CANDIDATE_REGRESSION_ROWS
            if row[0] not in {"POST-018", "POST-031"}
        ]
        assert list(self.command_observations) == expected_commands
        assert len(self._raw_tokens) == 42
        assert len({_sha256(token.encode("ascii")) for token in self._raw_tokens}) == 42
        assert len(self._private_roots) == 30
        assert self.canary_artifact is not None
        assert len(
            {
                row["spawnedPid"]
                for row in (
                    *self.observations.values(),
                    self.snapshot_observation,
                    *self.command_observations.values(),
                )
            }
        ) == 42

    def assert_canary_deleted(self, report_canary: dict[str, Any]) -> None:
        self.assert_complete()
        assert report_canary == {
            "artifact": self.canary_artifact,
            "contentSha256": PROBE_CANARY_SHA256,
            "unchangedAfterEveryProbe": True,
            "deletedBeforeReport": True,
        }
        assert self.canary_artifact is not None
        try:
            os.lstat(self.canary_artifact["absolutePath"])
        except FileNotFoundError:
            return
        raise AssertionError("probe canary still existed when regression report returned")


class SealRegressionDriver:
    """Deterministic process seam for TEST-017 publication fault injection."""

    def __init__(
        self,
        *,
        plans: Sequence[dict[str, Any]],
        session_root: Path,
        candidate_root: Path,
    ) -> None:
        self._plans = {plan["id"]: plan for plan in plans}
        self._session_root = session_root
        self._candidate_root = candidate_root
        self._count = 0
        self._tokens: set[str] = set()

    def _raw(
        self,
        *,
        stdout: bytes,
        stderr: bytes,
        environment: Mapping[str, str],
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        raw_token = environment[PROCESS_TOKEN_ENVIRONMENT_KEY]
        assert raw_token not in self._tokens
        assert _sha256(raw_token.encode("ascii")) == process_family_plan["tokenSha256"]
        self._tokens.add(raw_token)
        self._count += 1
        process_group_id = 70_000 + self._count
        execution = {
            "returnCode": 0,
            "signal": None,
            "stdout": stdout,
            "stderr": stderr,
            "processGroupId": process_group_id,
            "timedOut": False,
            "overflowStream": None,
            "outerProcessTable": [],
            "outerFinalProcessTable": [],
        }
        return CapabilityProbeDriverRecorder._raw_process_result(
            execution,
            process_family_plan,
        )

    def run_probe(
        self,
        *,
        capability_id: str,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        denied_read_canary: str,
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        assert capability_id in self._plans
        assert cwd == str(self._candidate_root)
        assert Path(denied_read_canary).parent == self._session_root
        assert rendered_profile == self._plans[capability_id]["profile"]
        positive_ids, negative_ids = _expected_probe_ids(capability_id)
        document = {
            "schemaVersion": "quant-radar-ui-ux-capability-probe-assertions/v1",
            "capabilityId": capability_id,
            "positive": [
                _probe_outcome_fixture(identifier, "succeeded")
                for identifier in positive_ids
            ],
            "negative": [
                _probe_outcome_fixture(identifier, "denied")
                for identifier in negative_ids
            ],
            "browser": (
                _probe_browser_fixture()
                if capability_id == "candidate-browser-tcp-unix-ux1b-v1"
                else None
            ),
        }
        return self._raw(
            stdout=_canonical(document),
            stderr=b"",
            environment=environment,
            process_family_plan=process_family_plan,
        )

    def run_snapshot_subset(
        self,
        *,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        process_family_plan: dict[str, Any],
    ) -> dict[str, Any]:
        assert cwd == str(self._candidate_root)
        document = {
            "excluded": [
                "test_ux1b_cleanup_retries_real_child_and_retains_persistent_runtimes",
                "test_ux1b_darwin_sandbox_contract_has_only_two_allowed_ports",
                "test_sequence13_stack_selection_is_distinct_and_root_bound",
            ],
            "failed": 0,
            "passed": 56,
            "schemaVersion": "quant-radar-ui-ux-snapshot-subset/v1",
            "selectedSha256": "3065243726a7d190f52b38242d83d790a7ff6cf1a7a30001c22cad30c2cb8c19",
            "status": "passed",
        }
        return self._raw(
            stdout=_canonical(document),
            stderr=b"",
            environment=environment,
            process_family_plan=process_family_plan,
        )

    def run_candidate_command(
        self,
        *,
        command_id: str,
        argv: Sequence[str],
        cwd: str,
        environment: dict[str, str],
        rendered_profile: bytes,
        process_family_plan: dict[str, Any],
        timeout_seconds: int,
        stdout_limit_bytes: int,
        stderr_limit_bytes: int,
    ) -> dict[str, Any]:
        assert command_id not in {"POST-018", "POST-031"}
        assert cwd == str(self._candidate_root)
        assert timeout_seconds > 0
        assert stdout_limit_bytes == stderr_limit_bytes == 1_048_576
        return self._raw(
            stdout=b"",
            stderr=b"",
            environment=environment,
            process_family_plan=process_family_plan,
        )

    def assert_complete(self) -> None:
        assert self._count == len(self._tokens) == 42


@contextmanager
def _seal_regression_test_seam(
    root: Path,
    fixture: Mapping[str, Any],
) -> Iterator[None]:
    candidate_source = root / str(fixture["candidateSourceRoot"])

    def passed_scratch_report(
        _images: Sequence[tuple[str, int, int]],
        *,
        source_root: Path | None = None,
    ) -> dict[str, Any]:
        del source_root
        return handoff._theme_scratch_report(
            [
                handoff._theme_scratch_internal_result(
                    identifier,
                    status_value="passed",
                    error_code=None,
                )
                for identifier in handoff.THEME_SCRATCH_IDS
            ]
        )

    with patch.object(
        handoff,
        "_CandidateRegressionProcessDriver",
        SealRegressionDriver,
    ), patch.object(
        handoff,
        "_candidate_source_root_for_seal",
        return_value=candidate_source,
    ), patch.object(
        handoff,
        "_run_theme_scratch_verifiers",
        passed_scratch_report,
    ):
        yield


def _scratch_theme_candidate_images() -> tuple[dict[str, bytes], dict[str, bytes]]:
    pre = {relative: (ROOT / relative).read_bytes() for relative in APPLY_PATHS}

    config = pre[".streamlit/config.toml"].decode("utf-8")
    config = config.replace('primaryColor = "#ef4444"', 'primaryColor = "#2563eb"')
    config = config.replace(
        'primaryColor = "#2563eb"\n',
        'primaryColor = "#2563eb"\nlinkColor = "#60a5fa"\nlinkUnderline = true\n',
    )

    app = pre["app.py"].decode("utf-8")
    app = app.replace(
        "from ui import (  # noqa: E402  (must follow set_page_config)\n",
        "from ui import (  # noqa: E402  (must follow set_page_config)\n    _design,\n",
        1,
    )
    metric_marker = 'st.markdown(\n    """\n    <style>\n    [data-testid="stMetricValue"]'
    assert metric_marker in app
    app = app.replace(
        metric_marker,
        "st.markdown(\n"
        "    _design.build_global_theme_css(),\n"
        "    unsafe_allow_html=True,\n"
        ")\n\n\n"
        + metric_marker,
        1,
    )

    rules: list[str] = []
    contract: list[dict[str, Any]] = []

    def owners(*cases: str) -> tuple[str, ...]:
        return tuple(
            sorted(
                f"ux1b_owner_{surface}_{case}"
                for case in cases
                for surface in ("canvas", "panel", "elevated")
            )
        )

    def add_rule(
        selector: str,
        declarations: Mapping[str, str],
        cases: tuple[str, ...],
        states: tuple[str, ...],
    ) -> None:
        rules.append(
            selector
            + " {{ "
            + " ".join(f"{name}: {value};" for name, value in declarations.items())
            + " }}"
        )
        for name, value in declarations.items():
            contract.append(
                {
                    "selector": selector,
                    "property": name,
                    "owners": owners(*cases),
                    "states": states,
                    "important": value.casefold().endswith("!important"),
                }
            )

    add_rule(
        '[data-testid="stButton"] button[kind="primary"]',
        {
            "background-color": "{COLOR_TOKENS['interactive.primary']}",
            "color": "{COLOR_TOKENS['text.on-primary']}",
        },
        ("primary",),
        ("default",),
    )
    add_rule(
        '[data-testid="stButton"] button[kind="primary"]:hover',
        {"background-color": "{COLOR_TOKENS['interactive.hover']}"},
        ("primary",),
        ("hover",),
    )
    add_rule(
        '[data-testid="stButton"] button[kind="primary"]:active',
        {"background-color": "{COLOR_TOKENS['interactive.active']}"},
        ("primary",),
        ("active",),
    )
    add_rule(
        '[data-testid="stFormSubmitButton"] button[kind="primary"]',
        {"background-color": "{COLOR_TOKENS['interactive.primary']}"},
        ("form_submit",),
        ("default",),
    )
    add_rule(
        '[data-testid="stDownloadButton"] button[kind="primary"]',
        {"background-color": "{COLOR_TOKENS['interactive.primary']}"},
        ("download",),
        ("default",),
    )
    add_rule(
        '[data-testid="stLinkButton"] a[kind="primary"]',
        {"background-color": "{COLOR_TOKENS['interactive.primary']}"},
        ("link_button",),
        ("default",),
    )
    add_rule(
        '[data-testid="stButton"] button[kind="tertiary"]',
        {"color": "{COLOR_TOKENS['interactive.accent']}"},
        ("tertiary",),
        ("default",),
    )
    add_rule(
        '[data-testid="stButton"] button[kind="primary"]:disabled',
        {
            "background-color": "{COLOR_TOKENS['interactive.disabled']}",
            "color": "{COLOR_TOKENS['text.disabled']}",
        },
        ("disabled",),
        ("disabled",),
    )
    add_rule(
        '[data-testid="stTabs"] [role="tab"][aria-selected="true"]',
        {"color": "{COLOR_TOKENS['interactive.accent']}"},
        ("tabs",),
        ("selected",),
    )
    add_rule(
        '[data-testid="stMarkdownContainer"] a:link',
        {
            "color": "{COLOR_TOKENS['interactive.accent']}",
            "text-decoration": "underline",
        },
        ("markdown_link",),
        ("default",),
    )
    add_rule(
        '[data-testid="stMarkdownContainer"] a:visited',
        {
            "color": "{COLOR_TOKENS['interactive.accent']}",
            "text-decoration": "underline",
        },
        ("markdown_link",),
        ("visited-static",),
    )
    for selector, case in (
        ('[data-testid="stCheckbox"] [aria-checked="true"]', "checkbox"),
        ('[data-testid="stRadio"] [aria-checked="true"]', "radio"),
        ('[data-testid="stToggle"] [aria-checked="true"]', "toggle"),
        ('[data-testid="stSlider"] [role="slider"]', "slider"),
        (
            '[data-testid="stRadio"] [data-baseweb="button-group"] [aria-checked="true"]',
            "radio_horizontal",
        ),
        ('[data-testid="stSelectbox"] [role="combobox"]', "selectbox"),
    ):
        add_rule(
            selector,
            {"background-color": "{COLOR_TOKENS['interactive.control']}"},
            (case,),
            ("checked",) if "checked" in selector else ("selected",),
        )
    add_rule(
        '[data-testid="stButton"] button[kind="primary"]:focus-visible',
        {
            "outline-color": "{COLOR_TOKENS['border.focus']}",
            "outline-style": "solid",
            "outline-width": "3px",
            "outline-offset": "2px",
        },
        ("primary",),
        ("focus-visible",),
    )

    design = pre["ui/_design.py"].decode("utf-8")
    design = design.replace(
        '    "text.disabled": "#7f8799",\n',
        '    "text.disabled": "#8b93a7",\n    "text.on-primary": "#ffffff",\n',
        1,
    )
    design = design.replace(
        'INTERACTIVE_TOKENS: Mapping[str, str] = MappingProxyType({\n'
        '    "interactive.primary": "#ef4444",\n'
        '    "interactive.hover": "#fb7185",\n'
        '    "interactive.disabled": "#6b7280",\n'
        '})',
        'INTERACTIVE_TOKENS: Mapping[str, str] = MappingProxyType({\n'
        '    "interactive.primary": "#2563eb",\n'
        '    "interactive.hover": "#1d4ed8",\n'
        '    "interactive.active": "#1e40af",\n'
        '    "interactive.accent": "#60a5fa",\n'
        '    "interactive.control": "#3b82f6",\n'
        '    "interactive.disabled": "#6b7280",\n'
        '})',
        1,
    )
    design += (
        "\n\nTHEME_SELECTOR_CONTRACT = "
        + repr(tuple(contract))
        + "\n\n\ndef build_global_theme_css() -> str:\n"
        + "    \"\"\"Return the fixed component-scoped UX-1B theme CSS.\"\"\"\n"
        + "    return f'''<style>\\n"
        + "\\n".join(rules)
        + "\\n</style>'''\n"
    )

    requirements = pre["requirements.txt"].decode("utf-8")
    requirements = re.sub(
        r"(?m)^streamlit[^\n]*$",
        "streamlit==1.57.0",
        requirements,
        count=1,
    )

    expression = ast.parse("_design.build_global_theme_css()", mode="eval").body
    expression_fingerprint = hashlib.sha256(
        ast.dump(expression, annotate_fields=True, include_attributes=False).encode(
            "utf-8"
        )
    ).hexdigest()
    site_id = (
        "app.py|<module>|st.markdown|call|"
        + expression_fingerprint
        + "|1"
    )
    classification = json.loads(
        pre["docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json"]
    )
    classification["state"] = "accepted"
    classification["unsafe_html"]["trusted_static_theme_css"] = [
        {
            "builder": "_design.build_global_theme_css",
            "expression_fingerprint": expression_fingerprint,
            "rationale_code": "trusted_static_theme_css",
            "site_id": site_id,
        }
    ]
    post = {
        ".streamlit/config.toml": config.encode("utf-8"),
        "app.py": app.encode("utf-8"),
        "ui/_design.py": design.encode("utf-8"),
        "requirements.txt": requirements.encode("utf-8"),
        "docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json": (
            json.dumps(
                classification,
                ensure_ascii=False,
                indent=2,
                sort_keys=True,
            )
            + "\n"
        ).encode("utf-8"),
    }
    return pre, post


def _run_real_scratch_fixture(
    pre: Mapping[str, bytes],
    post: Mapping[str, bytes],
    *,
    paths: Sequence[str] = APPLY_PATHS,
) -> dict[str, Any]:
    with tempfile.TemporaryDirectory(prefix="quant-radar-scratch-verifiers-") as raw:
        root = Path(raw)
        descriptors: list[tuple[str, int, int]] = []
        try:
            for index, relative in enumerate(paths):
                pre_path = root / "pre" / f"{index:02d}"
                post_path = root / "post" / f"{index:02d}"
                pre_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
                post_path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
                _write_owned(pre_path, pre[relative], 0o644)
                _write_owned(post_path, post[relative], 0o644)
                descriptors.append(
                    (
                        relative,
                        os.open(
                            pre_path,
                            os.O_RDONLY
                            | os.O_NOFOLLOW
                            | getattr(os, "O_CLOEXEC", 0),
                        ),
                        os.open(
                            post_path,
                            os.O_RDONLY
                            | os.O_NOFOLLOW
                            | getattr(os, "O_CLOEXEC", 0),
                        ),
                    )
                )
            return handoff._run_theme_scratch_verifiers(
                descriptors,
                source_root=ROOT,
            )
        finally:
            for _relative, pre_fd, post_fd in descriptors:
                os.close(pre_fd)
                os.close(post_fd)


def _assert_real_scratch_verifier_matrix() -> None:
    pre, post = _scratch_theme_candidate_images()
    passed = _run_real_scratch_fixture(pre, post)
    assert passed["status"] == "passed"
    assert (passed["passed"], passed["failed"]) == (7, 0)
    assert [row["id"] for row in passed["results"]] == list(
        handoff.THEME_SCRATCH_IDS
    )
    assert all(
        row["status"] == "passed"
        and row["kind"] == "internal"
        and row["outcome"] == "internal"
        and row["errorCode"] is None
        for row in passed["results"]
    )
    without_hash = {key: value for key, value in passed.items() if key != "sha256"}
    assert passed["sha256"] == _sha256(_canonical(without_hash))

    mutations: list[tuple[str, dict[str, bytes], Sequence[str]]] = []
    mutations.append(
        (
            handoff.THEME_SCRATCH_IDS[0],
            dict(post),
            tuple(reversed(APPLY_PATHS)),
        )
    )
    bad_config = dict(post)
    bad_config[".streamlit/config.toml"] = bad_config[
        ".streamlit/config.toml"
    ].replace(b"#2563eb", b"#ef4444", 1)
    mutations.append((handoff.THEME_SCRATCH_IDS[1], bad_config, APPLY_PATHS))
    bad_syntax = dict(post)
    bad_syntax["app.py"] += b"\nif\n"
    mutations.append((handoff.THEME_SCRATCH_IDS[2], bad_syntax, APPLY_PATHS))
    bad_css = dict(post)
    bad_css["ui/_design.py"] = bad_css["ui/_design.py"].replace(
        b'[data-testid="stButton"] button[kind="tertiary"]',
        b"button",
    )
    mutations.append((handoff.THEME_SCRATCH_IDS[3], bad_css, APPLY_PATHS))
    bad_injection = dict(post)
    bad_injection["app.py"] = pre["app.py"]
    mutations.append((handoff.THEME_SCRATCH_IDS[4], bad_injection, APPLY_PATHS))
    bad_version = dict(post)
    bad_version["requirements.txt"] = pre["requirements.txt"]
    mutations.append((handoff.THEME_SCRATCH_IDS[5], bad_version, APPLY_PATHS))
    bad_classification = dict(post)
    bad_classification[
        "docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json"
    ] = pre["docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json"]
    mutations.append(
        (handoff.THEME_SCRATCH_IDS[6], bad_classification, APPLY_PATHS)
    )

    for expected_id, mutated, paths in mutations:
        report = _run_real_scratch_fixture(pre, mutated, paths=paths)
        result = next(row for row in report["results"] if row["id"] == expected_id)
        assert result["status"] == "failed", expected_id
        assert result["errorCode"] == "assertion_failed", expected_id
        assert report["status"] == "failed"
        assert report["passed"] + report["failed"] == 7


class SyscallRecorder:
    """Fail closed before a test double can signal anything it does not own."""

    def __init__(
        self,
        *,
        fault: str | None = None,
        delegate_killpg: bool = False,
        owned_runner_pgids: Sequence[int] = (),
        owned_observer_pgids: Sequence[int] = (),
        owned_observer_pids: Sequence[int] = (),
        owned_observer_fds: Sequence[int] = (),
        owned_leases: Sequence[str] = (),
    ) -> None:
        self.fault = fault
        self.delegate_killpg = delegate_killpg
        self.owned_runner_pgids = frozenset(owned_runner_pgids)
        self.owned_observer_pgids = frozenset(owned_observer_pgids)
        self.owned_observer_pids = frozenset(owned_observer_pids)
        self.owned_observer_fds = frozenset(owned_observer_fds)
        self.owned_leases = frozenset(owned_leases)
        assert self.owned_runner_pgids.isdisjoint(self.owned_observer_pgids)
        assert self.owned_observer_pids == self.owned_observer_pgids
        assert all(isinstance(value, int) and value > 0 for value in self.owned_runner_pgids)
        assert all(isinstance(value, int) and value > 0 for value in self.owned_observer_pgids)
        assert all(isinstance(value, int) and value > 0 for value in self.owned_observer_pids)
        assert all(isinstance(value, int) and value >= 0 for value in self.owned_observer_fds)
        self.calls: list[tuple[Any, ...]] = []
        self.rejected_calls: list[tuple[Any, ...]] = []
        self._runner_signals: dict[int, list[int]] = {
            process_group_id: [] for process_group_id in self.owned_runner_pgids
        }
        self._observer_signaled: set[int] = set()
        self._closed_observer_fds: set[int] = set()
        self._released_leases: set[str] = set()
        self.lease_calls: list[tuple[str, str]] = []

    def record(self, name: str, *args: Any) -> None:
        self.calls.append((name, *args))
        if self.fault == name:
            raise OSError(errno.EIO, f"injected {name}")

    def killpg(self, process_group_id: int, sig: int) -> None:
        if process_group_id in self.owned_runner_pgids:
            observed = self._runner_signals[process_group_id]
            allowed = [signal.SIGTERM] if not observed else [signal.SIGTERM, signal.SIGKILL]
            if observed + [sig] != allowed:
                self.rejected_calls.append(("killpg", process_group_id, sig))
                raise AssertionError("runner signaling must be TERM followed optionally by KILL")
            observed.append(sig)
            role = "runner"
        elif process_group_id in self.owned_observer_pgids:
            if sig != signal.SIGKILL or process_group_id in self._observer_signaled:
                self.rejected_calls.append(("killpg", process_group_id, sig))
                raise AssertionError("an owned observer permits exactly one SIGKILL")
            self._observer_signaled.add(process_group_id)
            role = "observer"
        else:
            self.rejected_calls.append(("killpg", process_group_id, sig))
            raise AssertionError("refusing to signal an unregistered process group")

        self.record("killpg", role, process_group_id, sig)
        if self.fault == f"{role}_kill_esrch":
            raise ProcessLookupError(errno.ESRCH, "injected owned process-group disappearance")
        if self.fault in {f"{role}_kill_eperm", "observer_kill_eperm_owned_zombie"}:
            raise PermissionError(errno.EPERM, "injected owned process-group permission race")
        if self.delegate_killpg:
            os.killpg(process_group_id, sig)

    def kill(self, pid: int, sig: int) -> None:
        self.rejected_calls.append(("kill", pid, sig))
        raise AssertionError("os.kill/PID signaling is forbidden")

    def wait_direct_child(self, pid: int, timeout_seconds: float) -> dict[str, Any]:
        if pid not in self.owned_observer_pids:
            self.rejected_calls.append(("wait_direct_child", pid, timeout_seconds))
            raise AssertionError("refusing to wait for an unregistered observer child")
        self.record("wait_direct_child", pid, timeout_seconds)
        if self.fault == "observer_failed_reap":
            raise TimeoutError("injected observer reap timeout")
        return {
            "pid": pid,
            "reaped": True,
            "ownedZombie": self.fault == "observer_kill_eperm_owned_zombie",
        }

    def close_observer_fd(self, fd: int) -> None:
        if fd not in self.owned_observer_fds or fd in self._closed_observer_fds:
            self.rejected_calls.append(("close_observer_fd", fd))
            raise AssertionError("refusing to close an unregistered or already closed observer FD")
        self._closed_observer_fds.add(fd)
        self.record("close_observer_fd", fd)

    def release_lease(self, lease_id: str) -> None:
        if lease_id not in self.owned_leases or lease_id in self._released_leases:
            self.rejected_calls.append(("release_lease", lease_id))
            raise AssertionError("refusing to release an unregistered or already released lease")
        self._released_leases.add(lease_id)
        self.lease_calls.append(("release_lease", lease_id))


class ForcedWriteSyscalls(SyscallRecorder):
    def __init__(self, root: Path, *, fault: str | None = None) -> None:
        super().__init__(fault=fault)
        self.root = root
        self._fixture_write = os.write
        self.write_family_calls: list[tuple[Any, ...]] = []
        self.open_fds: dict[int, tuple[str, int]] = {}
        self.created_inodes: list[int] = []
        self.deleted_inodes: list[int] = []

    def open(self, relative: str, flags: int, mode: int | None = None) -> int:
        self.record("open", relative, flags, mode)
        path = self.root / relative
        if mode is None:
            fd = os.open(path, flags)
        else:
            fd = os.open(path, flags, mode)
        inode = os.fstat(fd).st_ino
        self.open_fds[fd] = (relative, inode)
        if flags & os.O_CREAT:
            self.created_inodes.append(inode)
        return fd

    @property
    def write_calls(self) -> int:
        return len(self.write_family_calls)

    def _forbid_write_family(self, name: str, *args: Any) -> None:
        call = (name, *args)
        self.write_family_calls.append(call)
        self.calls.append(call)
        raise AssertionError("negative probe attempted a write-family syscall")

    def write(self, fd: int, data: bytes) -> int:
        self._forbid_write_family("write", fd, len(data))

    def pwrite(self, fd: int, data: bytes, offset: int) -> int:
        self._forbid_write_family("pwrite", fd, len(data), offset)

    def writev(self, fd: int, buffers: Sequence[bytes]) -> int:
        self._forbid_write_family("writev", fd, tuple(len(buffer) for buffer in buffers))

    def ftruncate(self, fd: int, length: int) -> None:
        self._forbid_write_family("ftruncate", fd, length)

    def truncate(self, relative: str, length: int) -> None:
        self._forbid_write_family("truncate", relative, length)

    def close(self, fd: int) -> None:
        if fd not in self.open_fds:
            raise AssertionError("negative probe closed an unregistered descriptor")
        self.record("close", fd)
        os.close(fd)
        del self.open_fds[fd]

    def unlink_same_inode(self, relative: str, expected_inode: int) -> None:
        path = self.root / relative
        if self.fault == "identity_swap":
            held = self.root / f".held-{expected_inode}"
            os.rename(path, held)
            foreign_fd = os.open(
                path,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
                0o600,
            )
            try:
                assert self._fixture_write(foreign_fd, b"foreign-inode\n") == len(b"foreign-inode\n")
            finally:
                os.close(foreign_fd)
        self.record("unlink_same_inode", relative, expected_inode)
        observed = os.lstat(path)
        if observed.st_ino != expected_inode:
            raise handoff.ContractViolation("created inode was swapped")
        os.unlink(path)
        self.deleted_inodes.append(expected_inode)

    def fsync_parent(self) -> None:
        self.record("fsync_parent")
        fd = os.open(self.root, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(fd)
        finally:
            os.close(fd)

    def verify_absent(self, relative: str) -> None:
        self.record("verify_absent", relative)
        try:
            os.lstat(self.root / relative)
        except FileNotFoundError:
            return
        raise handoff.ContractViolation("negative probe cleanup is not absent")

    def assert_all_closed(self) -> None:
        assert self.open_fds == {}, f"negative probe leaked descriptors: {self.open_fds}"


def _post_apply_report(attempt: dict[str, Any]) -> dict[str, Any]:
    command_ids = (
        "POST-038-COMPILE-NOWRITE",
        "POST-039-AST310",
        "POST-040-PROTECTED",
        "POST-041-SCOPE-NOWRITE",
    )
    commands = [{"id": command_id, "kind": "internal", "execution": None} for command_id in command_ids]
    results = [
        {
            "id": command_id,
            "kind": "internal",
            "status": "passed",
            "outcome": "internal",
            "errorCode": None,
            "returnCode": None,
            "signal": None,
            "stdoutSha256": EMPTY_SHA256,
            "stderrSha256": EMPTY_SHA256,
            "stdoutBytes": 0,
            "stderrBytes": 0,
            "processGroupId": None,
            "processFamily": None,
        }
        for command_id in command_ids
    ]
    value = {
        "schemaVersion": "quant-radar-ui-ux-theme-batch-postapply-tests/v1",
        "status": "passed",
        "attempt": attempt,
        "commands": commands,
        "results": results,
        "passed": 4,
        "failed": 0,
        "notRun": 0,
        "resultsSha256": _sha256(_canonical(results)),
    }
    return {**value, "sha256": _sha256(_canonical(value))}


PROCESS_READ_QUANTUM_BYTES = 65_536
PROCESS_READS_PER_ROLE_TURN = 4
PROCESS_ROLE_QUANTUM_BYTES = 262_144
PROCESS_ROLE_ORDER = (
    "runner_stdout",
    "runner_stderr",
    "observer_stdout",
    "observer_stderr",
)


def _controller_result(
    case_id: str,
    *,
    outcome: str,
    exit_code: int,
    closure_kind: str | None,
    phases: Sequence[str] = (),
    signal_trace: Sequence[dict[str, Any]] = (),
    observer_trace: Sequence[dict[str, Any]] = (),
    selector_turns: Sequence[dict[str, Any]] = (),
    exit_watch: dict[str, Any] | None = None,
    manual_gate: bool = False,
    observer_sample: bool = True,
    interrupt_count: int = 0,
    latched_interrupt: str | None = None,
    local_reads_closed: bool = True,
    leases_released: bool = True,
) -> dict[str, Any]:
    return {
        "caseId": case_id,
        "outcome": outcome,
        "exitCode": exit_code,
        "receipt": None
        if closure_kind is None
        else {
            "closureKind": closure_kind,
            "phases": list(phases),
            "quiescent": True,
        },
        "exitWatchResult": exit_watch,
        "streamTrace": {
            "readQuantumBytes": PROCESS_READ_QUANTUM_BYTES,
            "readsPerRoleTurn": PROCESS_READS_PER_ROLE_TURN,
            "roleQuantumBytes": PROCESS_ROLE_QUANTUM_BYTES,
            "roleOrder": list(PROCESS_ROLE_ORDER),
            "turns": list(selector_turns),
            "zeroTimeKqueueTurns": len(selector_turns),
        },
        "observerTrace": list(observer_trace),
        "observerSampleEmitted": observer_sample,
        "signalTrace": list(signal_trace),
        "interruptCount": interrupt_count,
        "latchedInterrupt": latched_interrupt,
        "markerPidSignaled": False,
        "detachedMarkerPgidSignaled": False,
        "manualGateRetained": manual_gate,
        "localReadFdsClosed": local_reads_closed,
        "leasesReleased": leases_released,
    }


def _process_row(pid: int, process_group_id: int, state: str, *, marker: bool = False) -> dict[str, Any]:
    return {
        "pid": pid,
        "uid": os.getuid(),
        "processGroupId": process_group_id,
        "state": state,
        "waitStatus": 0 if "Z" not in state else 0x0300,
        "markerMatch": marker,
    }


