            assert set(before_manifest) == {"root", "directories", "files", "symlinks", "digest"}
            assert tuple(item["path"] for item in before_manifest["directories"]) == tuple(sorted(item["path"] for item in before_manifest["directories"]))
            assert tuple(item["path"] for item in before_manifest["files"]) == tuple(sorted(item["path"] for item in before_manifest["files"]))
