            assert before_manifest["root"]["mode"] == "0700"

            actual_directories: list[str] = []
            actual_files: list[str] = []
            actual_symlinks: list[str] = []

            def walk_candidate(directory: Path, relative_parent: str = "") -> None:
                with os.scandir(directory) as entries:
                    for entry in sorted(entries, key=lambda value: value.name):
                        relative = f"{relative_parent}/{entry.name}" if relative_parent else entry.name
                        observed = entry.stat(follow_symlinks=False)
                        if stat.S_ISLNK(observed.st_mode):
                            actual_symlinks.append(relative)
                        elif stat.S_ISDIR(observed.st_mode):
                            actual_directories.append(relative)
                            walk_candidate(Path(entry.path), relative)
                        elif stat.S_ISREG(observed.st_mode):
                            actual_files.append(relative)
                        else:
                            raise AssertionError(f"unexpected candidate entry type: {relative}")

            walk_candidate(candidate_root)
            assert actual_directories == [item["path"] for item in before_manifest["directories"]]
            assert actual_files == [item["path"] for item in before_manifest["files"]]
            assert actual_symlinks == [item["path"] for item in before_manifest["symlinks"]]
