class _SemanticTraceRecorder:
    def __init__(self) -> None:
        self.calls: list[tuple[Any, ...]] = []

    def record(self, *event: Any) -> None:
        self.calls.append(tuple(event))


class _SemanticProbeSocket:
    def __init__(self, owner: "_SemanticInProcessPrimitives", label: str) -> None:
        self.owner = owner
        self.label = label

    def _call(self, name: str, *args: Any) -> None:
        self.owner._call(f"socket.{name}", self.label, *args)

    def bind(self, address: Any, /) -> None: self._call("bind", address)
    def listen(self, backlog: int = 1, /) -> None: self._call("listen", backlog)
    def getsockname(self) -> Any:
        self._call("getsockname")
        return "bound-address"
    def accept(self) -> tuple["_SemanticProbeSocket", Any]:
        self._call("accept")
        return _SemanticProbeSocket(self.owner, "accepted"), "peer-address"
    def connect(self, address: Any, /) -> None: self._call("connect", address)
    def sendall(self, data: bytes, flags: int = 0, /) -> None: self._call("sendall", data, flags)
    def sendto(self, data: bytes, address: Any, /) -> int:
        self._call("sendto", data, address)
        return len(data)
    def recv(self, bufsize: int, flags: int = 0, /) -> bytes:
        self._call("recv", bufsize, flags)
        if self.owner.fault == "short-read": self._call("recv-result", b"short")
        if self.owner.fault == "wrong-payload": self._call("recv-result", b"wrong-payload")
        if self.owner.fault == "empty-payload": self._call("recv-result", b"")
        return b"semantic-marker"
    def recvfrom(self, bufsize: int, flags: int = 0, /) -> tuple[bytes, Any]:
        self._call("recvfrom", bufsize, flags)
        return b"semantic-marker", "peer-address"
    def settimeout(self, value: float | None, /) -> None: self._call("settimeout", value)
    def close(self) -> None:
        self._call("close")
        if self.owner.fault == "close-failure": self._call("close-error", "EIO")


class _SemanticInProcessPrimitives:
    """Raw-call recorder with the exact production primitive surface."""

    def __init__(self, *, fault: str | None = None) -> None:
        self.calls: list[tuple[Any, ...]] = []
        self.fault = fault
        self.operation_index = -1
        self._socket_number = 0
        self._socket: _SemanticProbeSocket | None = None
        self._accepted: _SemanticProbeSocket | None = None

    def _call(self, name: str, *args: Any) -> None:
        if name in {"raw-policy-error", "raw-gai-error"} and self.fault == "admitted-denial":
            self.calls.append((self.operation_index, "denial-admitted", *args))
            return
        if name in {"raw-policy-error", "raw-gai-error"} and self.fault == "wrong-exception-code":
            self.calls.append((self.operation_index, name, "EINVAL"))
            return
        self.calls.append((self.operation_index, name, *args))

    def import_module(self, name: str, package: str | None = None) -> Any:
        self._call("import_module", name, package)
        return {"origin": "authenticated-live-venv"}
    def open(self, path: str, flags: int, mode: int = 0o777) -> int:
        self._call("open", path, flags, mode)
        return 100 + self.operation_index
    def read(self, fd: int, size: int) -> bytes:
        self._call("read", fd, size)
        if self.fault == "short-read": self._call("read-result", b"short")
        if self.fault == "wrong-payload": self._call("read-result", b"wrong-payload")
        if self.fault == "empty-payload": self._call("read-result", b"")
        return b"semantic-payload"
    def write(self, fd: int, data: bytes) -> int:
        self._call("write", fd, data)
        if self.fault == "short-write": self._call("write-result", len(data) - 1)
        return len(data)
    def fstat(self, fd: int) -> Any:
        self._call("fstat", fd)
        return {"inode": fd}
    def lstat(self, path: str) -> Any:
        self._call("lstat", path)
        if self.fault == "identity-swap": self._call("lstat-result", "foreign-inode")
        if self.fault == "absence-check-failure": self._call("lstat-result", "still-exists")
        return {"inode": 100 + self.operation_index}
    def close(self, fd: int) -> None:
        self._call("close", fd)
        if self.fault == "close-failure": self._call("close-error", "EIO")
    def unlink(self, path: str) -> None:
        self._call("unlink", path)
        if self.fault == "unlink-failure": self._call("unlink-error", "EPERM")
    def fsync(self, fd: int) -> None:
        self._call("fsync", fd)
        if self.fault == "fsync-failure": self._call("fsync-error", "EIO")
    def listdir(self, path: str) -> list[str]:
        self._call("listdir", path)
        return []
    def scandir(self, path: str) -> Any:
        self._call("scandir", path)
        return ()
    def socket(self, family: int, type: int, proto: int = 0) -> _SemanticProbeSocket:
        self._socket_number += 1
        label = f"socket-{self._socket_number}"
        self._call("socket", family, type, proto, label)
        self._socket = _SemanticProbeSocket(self, label)
        return self._socket
    def socketpair(self) -> tuple[_SemanticProbeSocket, _SemanticProbeSocket]:
        self._call("socketpair", (), {})
        return _SemanticProbeSocket(self, "pair-left"), _SemanticProbeSocket(self, "pair-right")
    def getaddrinfo(self, host: str, port: int, family: int, type: int) -> list[Any]:
        self._call("getaddrinfo", host, port, family, type)
        return []

    def perform(self, operation_index: int, event: tuple[Any, ...]) -> None:
        self.operation_index = operation_index
        name = event[0]
        marker = b"semantic-marker"
        if name == "import":
            self.import_module(event[1], None); self._call("validate-import-origin", event[2])
        elif name in {"open", "create", "open-denied"}:
            mode = event[3] if name == "create" or (name == "open-denied" and len(event) == 5) else 0o777
            self.open(str(event[1]), int(event[2]), int(mode))
            if name == "open-denied": self._call("raw-policy-error", event[-1])
        elif name == "bounded-read-hash":
            fd = 100 + operation_index
            self._call("bounded-target", event[1]); self.fstat(fd); self.read(fd, 65_536)
        elif name == "close":
            self._call("close-target", event[1]); self.close(100 + max(0, operation_index - 2))
        elif name == "write-fsync-close":
            fd = 100 + max(0, operation_index - 1)
            self._call("write-target", event[1]); self.write(fd, marker); self.fsync(fd); self.close(fd)
        elif name == "nofollow-readback-close":
            fd = self.open(str(event[1]), int(event[2]), 0o777)
            self.fstat(fd); self.read(fd, 65_536); self.close(fd)
        elif name == "cas-unlink":
            self.lstat(str(event[1])); self.fstat(100 + max(0, operation_index - 1)); self.unlink(str(event[1]))
        elif name == "fsync-parent":
            fd = self.open(f"{event[1]}/..", os.O_RDONLY, 0o777)
            self.fsync(fd); self.close(fd)
        elif name == "verify-absent":
            self.lstat(str(event[1])); self._call("require-file-not-found", event[1])
        elif name == "identity-unchanged":
            self.lstat(str(event[1])); self._call("compare-identity", event[1])
        elif name == "listdir-denied":
            self.listdir(str(event[1])); self._call("raw-policy-error", event[2])
        elif name == "zero-write-family":
            self._call("assert-zero-write-family")
        elif name == "socket":
            families = {"AF_INET": 2, "AF_INET6": 30, "AF_UNIX": 1}
            types = {"SOCK_STREAM": 1, "SOCK_DGRAM": 2}
            self.socket(families[str(event[1])], types[str(event[2])], 0)
        elif name in {"bind", "bind-denied"}:
            assert self._socket is not None
            address = event[1] if len(event) == 2 else (event[1], event[2])
            self._socket.bind(address)
            if name.endswith("denied"): self._call("raw-policy-error", event[-1])
        elif name == "listen":
            assert self._socket is not None; self._socket.listen(int(event[1]))
        elif name == "connect":
            assert self._socket is not None; self._socket.connect(event[1])
        elif name == "connect-denied":
            assert self._socket is not None; self._socket.connect((event[1], event[2])); self._call("raw-policy-error", event[3])
        elif name == "accept":
            assert self._socket is not None; self._accepted, _ = self._socket.accept()
        elif name == "sendall":
            target = self._accepted or self._socket; assert target is not None; target.sendall(marker)
            self._call("validate-sendall", event[1])
        elif name in {"sendto-denied"}:
            assert self._socket is not None
            payload = marker if event[1] == "nonempty-marker" else b""
            self._socket.sendto(payload, (event[2], event[3])); self._call("raw-policy-error", event[4])
        elif name == "recv":
            target = self._accepted or self._socket; assert target is not None; target.recv(65_536)
            self._call("validate-recv", event[1])
        elif name == "settimeout":
            assert self._socket is not None; self._socket.settimeout(10.0); self._call("validate-timeout", event[1])
        elif name == "socketpair":
            left, right = self.socketpair(); self._socket, self._accepted = left, right
            self._call("validate-socketpair-args", event[1], event[2])
        elif name == "close-all":
            sockets = [item for item in (self._accepted, self._socket) if item is not None]
            while len(sockets) < int(event[1]): sockets.append(_SemanticProbeSocket(self, f"close-{len(sockets)}"))
            for sock in sockets[: int(event[1])]: sock.close()
        elif name == "getaddrinfo-denied":
            families = {"AF_UNSPEC": 0}; types = {"SOCK_DGRAM": 2}
            self.getaddrinfo(str(event[1]), int(event[2]), families[str(event[3])], types[str(event[4])])
            self._call("raw-gai-error", event[5])
        else:
            self._call("coordinator-primitive", *event)


class _SemanticChildLowLevelExecutor:
    def __init__(self) -> None:
        self.calls: list[tuple[Any, ...]] = []

    def _call(self, name: str, *args: Any) -> None: self.calls.append((name, *args))
    def popen(self, plan: Mapping[str, Any], disposition: str) -> int | None:
        self._call(
            "Popen", plan["argv"], plan["cwd"], tuple(sorted(plan["environment"].items())),
            "DEVNULL", "PIPE", "PIPE", True, plan["passFds"], True, disposition,
        )
        return None if disposition in {"spawn_denied", "spawn_failed"} else 41001
    def selector_drain(self, pid: int, *, timeout: int = 10, stdout_limit: int = 65_536, stderr_limit: int = 65_536) -> None:
        self._call("selector.register", pid, "stdout", "stderr")
        self._call("selector.drain", timeout, stdout_limit, stderr_limit)
    def waitpid(self, pid: int, result: str = "exit-0") -> None: self._call("waitpid", pid, result)
    def killpg(self, pid: int, signum: str, result: str = "sent") -> None: self._call("killpg", pid, signum, result)
    def close_pipes(self, pid: int, eof: tuple[str, ...] = ("stdout", "stderr")) -> None: self._call("close-pipes", pid, eof)
    def observe_union(self, rows: tuple[str, ...] = ()) -> None: self._call("post-reap-union", rows)

    def execute(self, recipe: str, *, fault: str | None = None) -> tuple[tuple[Any, ...], ...]:
        expected_argv = _semantic_expected_trace(recipe)[0][1]
        argv = ("WRONG",) if fault == f"{recipe.lower()}-argv-changed" else expected_argv
        plan = {
            "id": recipe,
            "argv": argv,
            "cwd": "AUTHENTICATED_CWD",
            "environment": {"QUANT_RADAR_UX1B_PROCESS_TOKEN": "unchanged-raw-token"},
            "stdin": "devnull",
            "timeoutSeconds": 10,
            "stdoutLimitBytes": 65_536,
            "stderrLimitBytes": 65_536,
            "passFds": (),
            "processGroup": "fresh_child",
        }
        assert set(plan) == set(get_type_hints(handoff.ProbeChildPlan))
        assert plan["stdin"] == "devnull" and plan["processGroup"] == "fresh_child"
        assert plan["timeoutSeconds"] == 10 and plan["stdoutLimitBytes"] == plan["stderrLimitBytes"] == 65_536
        assert plan["passFds"] == () and plan["environment"]["QUANT_RADAR_UX1B_PROCESS_TOKEN"] == "unchanged-raw-token"
        if fault == "fake-arm-without-popen-trace":
            self._call("forged-raw-arm", "completed")
            return tuple(self.calls)
        disposition = "spawn_denied" if recipe.startswith("N") else "completed"
        if fault in {
            "spawn-denial", "spawn-denied-with-family", "spawn-denied-non-oserror",
            "spawn-denied-wrong-errno", "spawn-denied-bool-errno",
        }: disposition = "spawn_denied"
        if fault in {"spawn-failure", "spawn-failed-policy-error"}: disposition = "spawn_failed"
        pid = self.popen(plan, disposition)
        if pid is None:
            self.close_pipes(-1)
            self.observe_union()
            return tuple(self.calls)
        if fault == "unbounded-child":
            self._call("communicate", pid, "no-timeout", "no-stream-limit")
            self.waitpid(pid); self.close_pipes(pid); self.observe_union()
            return tuple(self.calls)
        self.selector_drain(pid)
        if recipe == "P17":
            self._call(
                "read", "stdout",
                b"forged-version\n" if fault == "shared-p17-stdout" else b"v22.14.0\n",
            )
        if fault == "partial-stdout": self._call("read", "stdout", b"partial")
        if fault == "partial-stderr": self._call("read", "stderr", b"partial")
        if fault == "timeout":
            self._call("monotonic", "deadline"); self.killpg(pid, "SIGTERM"); self.killpg(pid, "SIGKILL")
        elif fault == "stdout-overflow":
            self._call("read", "stdout", 65_537); self.killpg(pid, "SIGTERM")
        elif fault == "stderr-overflow":
            self._call("read", "stderr", 65_537); self.killpg(pid, "SIGTERM")
        elif fault == "term-race":
            self.killpg(pid, "SIGTERM", "ESRCH")
        elif fault == "kill-race":
            self.killpg(pid, "SIGTERM"); self.killpg(pid, "SIGKILL", "ESRCH")
        if fault == "wrong-pid-pgid": self._call("getpgid", pid, pid + 1)
        wait_result = {
            "nonzero": "exit-1", "signal": "signal-9", "wait-mismatch": "wrong-pid",
            "timeout": "signal-9", "stdout-overflow": "signal-15", "stderr-overflow": "signal-15",
        }.get(fault, "exit-0")
        self.waitpid(pid, wait_result)
        eof = ("stdout",) if fault == "missing-eof" else ("stdout", "stderr")
        self.close_pipes(pid, eof)
        union = ("survivor",) if fault == "surviving-token-row" else ()
        self.observe_union(union)
        return tuple(self.calls)

    def execute_raw(self, recipe: str, *, fault: str | None = None) -> tuple[tuple[tuple[Any, ...], ...], dict[str, Any]]:
        trace = self.execute(recipe, fault=fault)
        argv = _semantic_expected_trace(recipe)[0][1]
        family: dict[str, Any] | None = {"processGroupId": 41001, "quiescent": True, "postReapUnion": ()}
        observed_stdout = b"".join(
            row[2] for row in trace
            if row[0] == "read" and row[1] == "stdout" and isinstance(row[2], bytes)
        )
        raw: dict[str, Any] = {
            "kind": "completed" if recipe.startswith("P") else "spawn_denied",
            "argv": argv,
            "pid": 41001 if recipe.startswith("P") else None,
            "processGroupId": 41001 if recipe.startswith("P") else None,
            "returnCode": 0 if recipe.startswith("P") else None,
            "signal": None,
            "stdout": observed_stdout,
            "stderr": b"",
            "timedOut": False,
            "overflowStream": None,
            "pipesClosed": True,
            "processFamily": family if recipe.startswith("P") else None,
            "error": None if recipe.startswith("P") else PermissionError(errno.EPERM, "denied"),
        }
        if fault == f"{recipe.lower()}-argv-changed": raw["argv"] = ("WRONG",)
        if fault in {"spawn-denial", "spawn-denied-with-family", "spawn-denied-non-oserror", "spawn-denied-wrong-errno", "spawn-denied-bool-errno"}:
            raw.update(kind="spawn_denied", pid=None, processGroupId=None, returnCode=None, signal=None, processFamily=None, error=PermissionError(errno.EPERM, "denied"))
        elif fault in {"spawn-failure", "spawn-failed-policy-error"}:
            raw.update(kind="spawn_failed", pid=None, processGroupId=None, returnCode=None, signal=None, processFamily=None, error=RuntimeError("spawn failed"))
        elif fault == "nonzero": raw["returnCode"] = 1
        elif fault == "signal": raw.update(returnCode=None, signal=9)
        elif fault == "partial-stdout": raw["stdout"] = b"partial"
        elif fault == "partial-stderr": raw["stderr"] = b"partial"
        elif fault == "timeout": raw.update(kind="timed_out", returnCode=None, signal=9, timedOut=True)
        elif fault == "stdout-overflow": raw.update(kind="output_overflow", returnCode=None, signal=15, overflowStream="stdout")
        elif fault == "stderr-overflow": raw.update(kind="output_overflow", returnCode=None, signal=15, overflowStream="stderr")
        elif fault == "wrong-pid-pgid": raw["processGroupId"] = 41002
        elif fault == "missing-eof": raw["pipesClosed"] = False
        elif fault == "wait-mismatch": raw.update(returnCode=None, signal=None)
        elif fault == "surviving-token-row": raw["processFamily"] = {"processGroupId": 41001, "quiescent": False, "postReapUnion": ("survivor",)}
        elif fault == "completed-both-status": raw.update(kind="completed", returnCode=0, signal=9)
        elif fault == "completed-missing-status": raw.update(kind="completed", returnCode=None, signal=None)
        elif fault == "timed-out-false": raw.update(kind="timed_out", returnCode=None, signal=9, timedOut=False, overflowStream=None)
        elif fault == "timed-out-with-overflow": raw.update(kind="timed_out", returnCode=None, signal=9, timedOut=True, overflowStream="stdout")
        elif fault == "overflow-timed-out": raw.update(kind="output_overflow", returnCode=None, signal=15, timedOut=True, overflowStream="stdout")
        elif fault == "overflow-missing-stream": raw.update(kind="output_overflow", returnCode=None, signal=15, timedOut=False, overflowStream=None)
        elif fault == "return-code-bool": raw.update(kind="completed", returnCode=True, signal=None)
        elif fault == "signal-bool": raw.update(kind="completed", returnCode=None, signal=True)
        elif fault == "pid-bool": raw.update(kind="completed", pid=True, processGroupId=True, returnCode=0, signal=None, processFamily={"processGroupId": True, "quiescent": True, "postReapUnion": ()})
        elif fault == "pgid-bool": raw.update(kind="completed", pid=41001, processGroupId=True, returnCode=0, signal=None)
        elif fault == "raw-only-argv": raw["argv"] = ("WRONG",)
        elif fault == "raw-only-return-code": raw["returnCode"] = 7
        elif fault == "raw-only-signal": raw.update(returnCode=None, signal=9)
        elif fault == "raw-only-pid-family": raw.update(pid=42_000, processGroupId=42_000, processFamily={"processGroupId": 42_000, "quiescent": True, "postReapUnion": ()})
        elif fault == "raw-only-stdout": raw["stdout"] = b"forged"
        elif fault == "raw-only-kind": raw.update(kind="timed_out", returnCode=None, signal=9, timedOut=True, overflowStream=None)
        elif fault == "nested-family-pgid-bool": raw.update(pid=1, processGroupId=1, processFamily={"processGroupId": True, "quiescent": True, "postReapUnion": ()})
        if fault == "spawn-denied-with-family": raw["processFamily"] = family
        if fault == "spawn-denied-non-oserror": raw["error"] = RuntimeError("forged policy denial")
        if fault == "spawn-denied-wrong-errno": raw["error"] = FileNotFoundError(errno.ENOENT, "missing")
        if fault == "spawn-denied-bool-errno": raw["error"] = OSError(True, "boolean is not an errno")
        if fault == "spawn-failed-policy-error": raw["error"] = PermissionError(errno.EACCES, "denied")
        return trace, raw


def _validate_semantic_raw_child_execution(raw: Mapping[str, Any]) -> str | None:
    exact_keys = {
        "kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr",
        "timedOut", "overflowStream", "pipesClosed", "processFamily", "error",
    }
    if set(raw) != exact_keys: return "keys"
    if not isinstance(raw["argv"], tuple) or not raw["argv"]: return "argv"
    if not isinstance(raw["stdout"], bytes) or not isinstance(raw["stderr"], bytes): return "streams"
    if raw["pipesClosed"] is not True: return "pipes-closed"
    kind = raw["kind"]
    if kind in {"spawn_denied", "spawn_failed"}:
        if any(raw[key] is not None for key in ("pid", "processGroupId", "returnCode", "signal", "processFamily")): return "spawn-nullability"
        if raw["stdout"] or raw["stderr"] or raw["timedOut"] is not False or raw["overflowStream"] is not None: return "spawn-terminal-fields"
        error = raw["error"]
        is_policy_error = (
            isinstance(error, OSError)
            and type(error.errno) is int
            and error.errno in {errno.EPERM, errno.EACCES}
        )
        if kind == "spawn_denied" and not is_policy_error: return "spawn-policy-error"
        if kind == "spawn_failed" and (not isinstance(error, BaseException) or is_policy_error): return "spawn-failure-error"
        return None
    if kind not in {"completed", "timed_out", "output_overflow"}: return "kind"
    if type(raw["pid"]) is not int or raw["pid"] <= 0 or type(raw["processGroupId"]) is not int or raw["processGroupId"] != raw["pid"]: return "pid-pgid"
    has_return = type(raw["returnCode"]) is int and raw["returnCode"] >= 0
    has_signal = type(raw["signal"]) is int and raw["signal"] > 0
    if has_return == has_signal: return "wait-status-exclusive"
    if raw["error"] is not None: return "post-spawn-error"
    family = raw["processFamily"]
    if not isinstance(family, Mapping): return "family-closure"
    family_pgid = family.get("processGroupId")
    if type(family_pgid) is not int or family_pgid != raw["pid"] or family.get("quiescent") is not True or family.get("postReapUnion") != (): return "family-closure"
    if kind == "completed":
        if raw["timedOut"] is not False or raw["overflowStream"] is not None: return "completed-discriminator"
    elif kind == "timed_out":
        if raw["timedOut"] is not True or raw["overflowStream"] is not None: return "timeout-discriminator"
    elif raw["timedOut"] is not False or raw["overflowStream"] not in {"stdout", "stderr"}: return "overflow-discriminator"
    return None


def _validate_semantic_child_trace_binding(
    recipe: str,
    trace: tuple[tuple[Any, ...], ...],
    raw: Mapping[str, Any],
) -> str | None:
    popen_rows = [row for row in trace if row and row[0] == "Popen"]
    if len(popen_rows) != 1: return "popen-cardinality"
    popen = popen_rows[0]
    expected_argv = _semantic_expected_trace(recipe)[0][1]
    expected_environment = (("QUANT_RADAR_UX1B_PROCESS_TOKEN", "unchanged-raw-token"),)
    if popen[1:] != (
        expected_argv, "AUTHENTICATED_CWD", expected_environment,
        "DEVNULL", "PIPE", "PIPE", True, (), True, popen[-1],
    ): return "popen-contract"
    if raw["argv"] != expected_argv or raw["argv"] != popen[1]: return "argv-binding"
    kind = raw["kind"]
    disposition = popen[-1]
    if kind in {"spawn_denied", "spawn_failed"}:
        if disposition != kind: return "spawn-disposition"
        if any(row[0] in {"selector.register", "selector.drain", "waitpid"} for row in trace): return "spawn-with-child-trace"
        return None
    if disposition != "completed": return "spawn-disposition"
    register = [row for row in trace if row[0] == "selector.register"]
    drains = [row for row in trace if row[0] == "selector.drain"]
    waits = [row for row in trace if row[0] == "waitpid"]
    closes = [row for row in trace if row[0] == "close-pipes"]
    unions = [row for row in trace if row[0] == "post-reap-union"]
    if len(register) != 1 or len(drains) != 1: return "selector-cardinality"
    if register != [("selector.register", raw["pid"], "stdout", "stderr")]: return "pid-selector-binding"
    if drains != [("selector.drain", 10, 65_536, 65_536)]: return "selector-bounds"
    if len(waits) != 1 or waits[0][1] != raw["pid"]: return "wait-pid-binding"
    wait_projection = {
        "exit-0": (0, None), "exit-1": (1, None),
        "signal-9": (None, 9), "signal-15": (None, 15),
    }.get(waits[0][2])
    if wait_projection is None or wait_projection != (raw["returnCode"], raw["signal"]): return "wait-status-binding"
    if closes != [("close-pipes", raw["pid"], ("stdout", "stderr"))] or raw["pipesClosed"] is not True: return "pipe-binding"
    if unions != [("post-reap-union", ())]: return "union-trace-binding"
    family = raw["processFamily"]
    if family != {"processGroupId": raw["pid"], "quiescent": True, "postReapUnion": ()}: return "family-binding"
    stdout = b"".join(row[2] for row in trace if row[0] == "read" and row[1] == "stdout" and isinstance(row[2], bytes))
    stderr = b"".join(row[2] for row in trace if row[0] == "read" and row[1] == "stderr" and isinstance(row[2], bytes))
    if raw["stdout"] != stdout or raw["stderr"] != stderr: return "stream-binding"
    if recipe == "P17":
        if _sha256(SEMANTIC_P17_PREFLIGHT_STDOUT) != SEMANTIC_P17_PREFLIGHT_STDOUT_SHA256: return "p17-preflight-hash"
        if raw["stdout"] != SEMANTIC_P17_PREFLIGHT_STDOUT: return "p17-preflight-stdout"
    elif kind == "completed" and raw["stdout"]: return "unexpected-stdout"
    if kind == "completed" and any(row[0] in {"monotonic", "killpg"} for row in trace): return "completed-cleanup-binding"
    if kind == "timed_out" and not (("monotonic", "deadline") in trace and any(row[:3] == ("killpg", raw["pid"], "SIGKILL") for row in trace)): return "timeout-binding"
    if kind == "output_overflow":
        overflow_reads = [row for row in trace if row[:2] == ("read", raw["overflowStream"]) and row[2] == 65_537]
        if len(overflow_reads) != 1: return "overflow-binding"
    return None


class _SemanticPage:
    def __init__(self, calls: list[tuple[Any, ...]], fault: str | None) -> None: self.calls, self.fault = calls, fault
    def goto(self, url: str) -> None: self.calls.append(("page.goto", url))
    def close(self) -> None:
        if self.fault != "missing-page-close": self.calls.append(("page.close",))
        if self.fault == "duplicate-page-close": self.calls.append(("page.close",))


class _SemanticContext:
    def __init__(self, calls: list[tuple[Any, ...]], fault: str | None) -> None: self.calls, self.fault = calls, fault
    def new_page(self) -> _SemanticPage:
        self.calls.append(("context.new_page",))
        return _SemanticPage(self.calls, self.fault)
    def close(self) -> None:
        if self.fault != "missing-context-close": self.calls.append(("context.close",))
        if self.fault == "duplicate-context-close": self.calls.append(("context.close",))


class _SemanticBrowser:
    def __init__(self, calls: list[tuple[Any, ...]], fault: str | None) -> None: self.calls, self.fault = calls, fault
    @property
    def version(self) -> str:
        value = "wrong-version" if self.fault == "wrong-version" else "authenticated-version"
        self.calls.append(("browser.version", value)); return value
    def new_context(self) -> _SemanticContext:
        self.calls.append(("browser.new_context",)); return _SemanticContext(self.calls, self.fault)
    def close(self) -> None:
        if self.fault != "missing-browser-close": self.calls.append(("browser.close",))
        if self.fault == "duplicate-browser-close": self.calls.append(("browser.close",))


class _SemanticChromium:
    def __init__(self, calls: list[tuple[Any, ...]], fault: str | None) -> None: self.calls, self.fault = calls, fault
    @property
    def executable_path(self) -> str:
        value = "wrong-api-path" if self.fault == "wrong-api-path" else "API_PATH"
        self.calls.append(("chromium.executable_path", value)); return value
    def launch(self, **kwargs: Any) -> _SemanticBrowser:
        if self.fault == "explicit-executable": kwargs["executable_path"] = "API_PATH"
        self.calls.append(("chromium.launch", tuple(sorted(kwargs.items()))))
        return _SemanticBrowser(self.calls, self.fault)


class _SemanticPlaywrightOwner:
    def __init__(self, fault: str | None = None) -> None:
        self.calls: list[tuple[Any, ...]] = []
        self.fault = fault
        self.chromium = _SemanticChromium(self.calls, fault)
    def start(self) -> "_SemanticPlaywrightOwner": self.calls.append(("playwright.start",)); return self
    def stop(self) -> None:
        if self.fault != "missing-owner-close": self.calls.append(("playwright.stop",))
        if self.fault == "duplicate-owner-close": self.calls.append(("playwright.stop",))


def _exercise_semantic_browser_low_level(fault: str | None = None) -> tuple[tuple[Any, ...], ...]:
    owner = _SemanticPlaywrightOwner(fault).start()
    owner.chromium.executable_path
    if fault == "direct-process-launch": owner.calls.append(("subprocess.Popen", "chromium"))
    browser = owner.chromium.launch(headless=True)
    context = browser.new_context()
    if fault != "no-page":
        page = context.new_page(); page.goto("about:blank"); browser.version
        if fault == "reordered-page-close": context.close()
        page.close()
    if fault == "reordered-owner-close":
        owner.stop(); context.close(); browser.close()
    elif fault == "reordered-browser-close":
        if fault != "reordered-page-close": context.close()
        owner.stop(); browser.close()
    elif fault == "reordered-context-close":
        browser.close(); context.close(); owner.stop()
    else:
        if fault != "reordered-page-close": context.close()
        browser.close(); owner.stop()
    owner.calls.append(("consume-p17", fault not in {"failed-p17", "ignored-p17"}))
    owner.calls.append(("validate-node-hash", fault != "wrong-node-hash"))
    owner.calls.append(("validate-node-output", fault != "wrong-node-output"))
    owner.calls.append(("validate-profile", fault != "wrong-profile-exec-leaves"))
    owner.calls.append(("validate-family-receipt", fault != "invalid-family-receipt"))
    owner.calls.append(("validate-stdout-receipt", fault != "stdout-receipt-mismatch"))
    owner.calls.append(("final-union", ("survivor",) if fault == "nonquiescent-final-union" else ()))
    owner.calls.append(("required-not-skipped", fault != "optional-skip"))
    return tuple(owner.calls)


class _SemanticObserverLowLevel:
    ARGV = ("/bin/ps", "eww", "-axo", "pid=,uid=,pgid=,stat=,xstat=,command=")
    ENVIRONMENT = (("LANG", "C"), ("LC_ALL", "C"), ("PATH", "/usr/bin:/bin:/usr/sbin:/sbin"))
    PID = 999
    TARGET_PID = 100
    CURRENT_UID = 501
    ORIGINAL_PGID = 100
    # Deliberately independent from SEMANTIC_PLAN_PROCESS_TOKEN so the producer
    # and validator cannot drift together as one shared oracle.
    TOKEN = b"ux1b_" + b"a" * 64

    def _sample(self, raw: bytes, fault: str | None = None) -> tuple[tuple[Any, ...], ...]:
        environment = self.ENVIRONMENT if fault != "wrong-environment" else (("PATH", "/usr/bin"),)
        calls: list[tuple[Any, ...]] = [
            ("Popen", self.ARGV, "DEVNULL", "PIPE", "PIPE", True, (), True, environment),
        ]
        if fault != "not-nonblocking": calls.append(("set-nonblocking", "stdout", "stderr"))
        calls.append(("selector.drain", 3 if fault == "wrong-timeout" else 2, 4_194_304, 65_536))
        calls.append(("stdout", raw))
        calls.append(("stderr", b"observer-error" if fault == "nonempty-stderr" else b""))
        eof = ("stderr",) if fault == "missing-stdout-eof" else (("stdout",) if fault == "missing-stderr-eof" else ("stdout", "stderr"))
        calls.append(("eof", eof))
        calls.append(("child-result", fault if fault in {"nonzero", "signal", "timeout", "stdout-overflow", "stderr-overflow"} else "exit-0"))
        calls.append(("parse-rows", raw))
        calls.append(("waitpid", self.PID, 1.0 if fault == "wrong-wait-timeout" else 0.5, self.PID, "exit-0"))
        return tuple(calls)

    def run(self, fault: str | None = None) -> tuple[tuple[Any, ...], ...]:
        raw_token = self.TOKEN
        if fault == "invalid-plan-token": raw_token = b"bad"
        if fault == "mismatched-plan-token": raw_token = b"ux1b_" + b"b" * 64
        marker = b"QUANT_RADAR_UX1B_PROCESS_TOKEN=" + raw_token
        target = b"100 501 100 U+< a python " + marker + b"\n"
        detached = b"101 501 101 S 0 python " + marker + b"\n"
        zombie = b"100 501 100 Z f <defunct>\n"
        observer = b"999 501 999 R 0 /bin/ps eww -axo process-table\n"
        immediate_raw = target + observer
        if fault == "bad-field-count": immediate_raw = b"100 501\n"
        elif fault == "bad-pid": immediate_raw = immediate_raw.replace(b"100 ", b"pid ", 1)
        elif fault == "bad-uid": immediate_raw = immediate_raw.replace(b"501", b"uid", 1)
        elif fault == "zero-pid": immediate_raw = immediate_raw.replace(b"100 ", b"0 ", 1)
        elif fault == "negative-uid": immediate_raw = immediate_raw.replace(b"501", b"-1", 1)
        elif fault == "empty-command": immediate_raw = immediate_raw.replace(b" python " + marker, b" ", 1)
        elif fault == "duplicate-pid": immediate_raw = target + target + observer
        elif fault == "unsorted-pid": immediate_raw = observer + target
        elif fault == "zero-pgid": immediate_raw = immediate_raw.replace(b" 100 U+< ", b" 0 U+< ")
        elif fault == "invalid-state": immediate_raw = immediate_raw.replace(b" U+< a ", b" D a ")
        elif fault == "invalid-xstat": immediate_raw = immediate_raw.replace(b" U+< a ", b" U+< nope ")
        elif fault == "missing-own-row": immediate_raw = target
        elif fault == "extra-observer-pgid-row": immediate_raw = target + b"998 501 999 S 0 helper\n" + observer
        elif fault == "marker-boundary-false-positive":
            immediate_raw = target.replace(b" 100 U+< ", b" 777 U+< ").replace(b"TOKEN=", b"TOKEN_PREFIX=") + observer
        if fault == "with-foreign-noise": immediate_raw = target + b"101 0 777 S 0 foreign " + marker + b"\n" + observer
        if fault == "with-unrelated-noise": immediate_raw = target + b"101 501 777 S 0 unrelated\n" + observer
        if fault == "with-detached-marker": immediate_raw = target + detached + observer
        if fault == "wrong-target-leader": immediate_raw = target.replace(b"100 501", b"102 501", 1) + observer
        if fault == "esrch-owned-zombie": immediate_raw = zombie + observer

        if fault == "esrch-owned-zombie":
            note = ("NOTE_EXIT.register", self.TARGET_PID, 0, "owned_zombie", "esrch")
        else:
            note = ("NOTE_EXIT.register", self.TARGET_PID, 2 if fault == "note-exit-count" else 1, "NOTE_EXIT", "ESRCH-unproved" if fault == "bad-esrch-fallback" else "registered")
        immediate = ("sample", "immediate", self._sample(immediate_raw, fault))
        cadence = ("cadence-seconds", 0.051 if fault == "bad-cadence" else 0.05)
        pre_raw = target + observer if fault == "pre-reap-not-zombie" else zombie + observer
        if fault == "wrong-target-leader": pre_raw = zombie.replace(b"100 501", b"102 501", 1) + observer
        if fault == "pre-reap-extra-row": pre_raw = zombie + detached + observer
        pre = ("sample", "pre_reap", self._sample(pre_raw))
        owned_eof = ("owned-pipes-eof", True, True)
        wait = ("waitpid-owned", self.TARGET_PID, 0.5, self.TARGET_PID, 14 if fault == "xstat-wait-mismatch" else 15)
        compare = ("xstat-wait-equal", 15, 14 if fault == "xstat-wait-mismatch" else 15)
        post_raw = zombie + observer if fault == "nonempty-post-reap-union" else observer
        post = ("sample", "post_reap", self._sample(post_raw))
        union = ("post-reap-union", ("survivor",) if fault == "nonempty-post-reap-union" else ())
        calls: list[tuple[Any, ...]] = [note, immediate, cadence]
        if fault == "with-detached-marker":
            calls.append(("sample", "settling_exit", self._sample(zombie + detached + observer)))
        if fault == "marker-boundary-false-negative": calls.append(("marker-matcher", "forced-miss"))
        if fault == "replayed-audit-frame": calls.append(("audit-sequence", "replayed"))
        if fault == "token-hash-different": calls.append(("token-binding", "one-byte-different"))
        if fault == "early-owned-wait": calls.append(wait)
        if fault != "missing-pre-reap": calls.append(pre)
        calls.append(owned_eof)
        if fault != "early-owned-wait": calls.append(wait)
        if fault == "duplicate-owned-wait": calls.append(wait)
        calls.extend((compare, post, union))
        if fault == "duplicate-note-exit": calls.insert(1, note)
        if fault == "premature-reap":
            calls.remove(wait); calls.insert(3, wait)
        return tuple(calls)


def _exercise_semantic_cas_cleanup(*, unsafe_unlink: bool) -> tuple[tuple[Any, ...], ...]:
    calls: list[tuple[Any, ...]] = []
    with tempfile.TemporaryDirectory(prefix="ux1b-semantic-cas-") as raw_root:
        root = Path(raw_root)
        target = root / "candidate"
        replacement = root / "replacement"
        target.write_bytes(b"owned")
        replacement.write_bytes(b"foreign")
        grant = os.lstat(target)
        calls.append(("lstat-grant", grant.st_dev, grant.st_ino))
        os.replace(replacement, target)
        current = os.lstat(target)
        calls.append(("lstat-current", current.st_dev, current.st_ino))
        same_inode = (grant.st_dev, grant.st_ino) == (current.st_dev, current.st_ino)
        if unsafe_unlink or same_inode:
            os.unlink(target); calls.append(("unlink", "foreign" if not same_inode else "owned"))
        else:
            calls.append(("unlink-refused", "identity-mismatch"))
        calls.append(("foreign-exists", target.exists()))
    return tuple(calls)


def _semantic_execute_low_level(recipe: str, operations: tuple[tuple[Any, ...], ...]) -> tuple[tuple[Any, ...], ...]:
    owner = SEMANTIC_OWNER_BY_RECIPE[recipe]
    if owner == "INPROC":
        primitives = _SemanticInProcessPrimitives()
        for index, operation in enumerate(operations): primitives.perform(index, operation)
        return tuple(primitives.calls)
    if owner == "CHILD": return _SemanticChildLowLevelExecutor().execute(recipe)
    if owner == "BROWSER-FINAL": return _exercise_semantic_browser_low_level()
    if owner == "TOKEN": return _SemanticObserverLowLevel().run()
    return tuple(("coordinator", index, *operation) for index, operation in enumerate(operations))


def _semantic_q_low_level(recipe: str, operations: tuple[tuple[Any, ...], ...]) -> tuple[tuple[Any, ...], ...]:
    if recipe == "P07": return _SemanticChildLowLevelExecutor().execute(recipe, fault="nonzero")
    if recipe == "P17": return _SemanticChildLowLevelExecutor().execute(recipe, fault="partial-stdout")
    if recipe in {"N01", "N26"}: return _SemanticChildLowLevelExecutor().execute(recipe, fault="fake-arm-without-popen-trace")
    if recipe in {"N02", "N03", "N24", "N25"}: return _SemanticChildLowLevelExecutor().execute(recipe, fault=f"{recipe.lower()}-argv-changed")
    if recipe == "P08": return _SemanticObserverLowLevel().run("token-hash-different")
    if recipe == "P18": return _exercise_semantic_browser_low_level("missing-context-close")
    return _semantic_execute_low_level(recipe, operations)


def _semantic_inprocess_fault_cases() -> tuple[dict[str, Any], ...]:
    cases: list[dict[str, Any]] = []
    for recipe in SEMANTIC_INPROCESS_RECIPES:
        operations = _semantic_expected_trace(recipe)
        for index, event in enumerate(operations):
            label = str(event[0]).replace("_", "-")
            cases.append({
                "id": f"{recipe.lower()}-missing-{index:02d}-{label}",
                "recipe": recipe,
                "mutation": "missing",
                "index": index,
                "oracle": f"operation-{index:02d}-{label}",
            })
            contract_fields = range(1, len(event)) if len(event) > 1 else (0,)
            for field_index in contract_fields:
                cases.append({
                    "id": f"{recipe.lower()}-wrong-contract-{index:02d}-{field_index:02d}-{label}",
                    "recipe": recipe,
                    "mutation": "wrong-contract",
                    "index": index,
                    "field": field_index,
                    "oracle": f"operation-{index:02d}-field-{field_index:02d}-{label}",
                })
        for index in range(max(0, len(operations) - 1)):
            cases.append({
                "id": f"{recipe.lower()}-reordered-{index:02d}-{index + 1:02d}",
                "recipe": recipe,
                "mutation": "reordered",
                "index": index,
                "oracle": f"ordered-edge-{index:02d}-{index + 1:02d}",
            })
        cases.append({
            "id": f"{recipe.lower()}-extra-{len(operations):02d}",
            "recipe": recipe,
            "mutation": "extra",
            "index": len(operations),
            "oracle": "closed-primitive-set",
        })
    special_faults = (
        ("short-write", ("P05", "P13", "P14", "P15")),
        ("short-read", ("P04", "P05", "P06", "P09", "P10", "P11", "P12", "P13", "P14", "P15")),
        ("wrong-payload", ("P04", "P05", "P06", "P09", "P10", "P11", "P12", "P13", "P14", "P15")),
        ("empty-payload", ("P04", "P05", "P06", "P09", "P10", "P11", "P12", "P13", "P14", "P15")),
        ("admitted-denial", tuple(f"N{number:02d}" for number in range(4, 24))),
        ("wrong-exception-code", tuple(f"N{number:02d}" for number in range(4, 24))),
        ("close-failure", ("P04", "P05", "P09", "P10", "P11", "P12", "P13", "P14", "P15", "P16", "N12", "N13", "N15", "N16", "N17", "N18", "N19", "N20")),
        ("unlink-failure", ("P05", "P13", "P14", "P15", "P16")),
        ("fsync-failure", ("P05", "P13", "P14", "P15", "P16")),
        ("identity-swap", ("P05", "P13", "P14", "P15", "P16", "N05")),
        ("absence-check-failure", ("P05", "P13", "P14", "P15", "P16")),
    )
    for fault, recipes in special_faults:
        for recipe in recipes:
            cases.append({
                "id": f"{recipe.lower()}-fault-{fault}",
                "recipe": recipe,
                "mutation": "low-level",
                "index": -1,
                "fault": fault,
                "oracle": f"low-level-{fault}",
            })
    return tuple(cases)


SEMANTIC_INPROCESS_FAULT_CASES = _semantic_inprocess_fault_cases()
SEMANTIC_INPROCESS_FAULTS = tuple(case["id"] for case in SEMANTIC_INPROCESS_FAULT_CASES)


def _mutate_inprocess_operations(case: Mapping[str, Any]) -> tuple[tuple[Any, ...], ...]:
    operations = list(_semantic_expected_trace(str(case["recipe"])))
    index = int(case["index"])
    mutation = case["mutation"]
    if mutation == "missing": operations.pop(index)
    elif mutation == "wrong-contract":
        event = operations[index]
        changed = list(event)
        field_index = int(case["field"])
        if field_index == 0:
            changed[0] = f"wrong-{event[0]}"
        else:
            value = changed[field_index]
            if isinstance(value, bool): changed[field_index] = not value
            elif isinstance(value, int): changed[field_index] = value + 1
            elif isinstance(value, str): changed[field_index] = "EINVAL" if "EPERM" in value or "EAI_" in value else f"wrong-{value}"
            elif isinstance(value, tuple): changed[field_index] = (*value, "wrong")
            else: changed[field_index] = ("wrong", repr(value))
        operations[index] = tuple(changed)
    elif mutation == "reordered": operations[index], operations[index + 1] = operations[index + 1], operations[index]
    elif mutation == "extra": operations.append(("unexpected-primitive",))
    else: raise AssertionError(f"unknown in-process mutation: {mutation}")
    return tuple(operations)


def _assert_inprocess_fault_injected(case: Mapping[str, Any], facts: Mapping[str, Any]) -> None:
    case_id = str(case["id"])
    oracle = str(case["oracle"])
    expected = _semantic_expected_trace(str(case["recipe"]))
    if case["mutation"] == "missing":
        index = int(case["index"])
        assert len(facts["trace"]) == len(expected) - 1 and facts["trace"][index:] == expected[index + 1 :], f"{case_id}/{oracle}: exact missing operation"
    elif case["mutation"] == "wrong-contract":
        index = int(case["index"])
        assert facts["trace"][index][0] == expected[index][0] or len(expected[index]) == 1, f"{case_id}/{oracle}: primitive identity"
        assert facts["trace"][index] != expected[index], f"{case_id}/{oracle}: concrete contract value"
    elif case["mutation"] == "reordered":
        index = int(case["index"])
        assert facts["trace"][index : index + 2] == (expected[index + 1], expected[index]), f"{case_id}/{oracle}: exact ordered edge"
    elif case["mutation"] == "extra":
        assert facts["trace"] == (*expected, ("unexpected-primitive",)), f"{case_id}/{oracle}: closed primitive set"
    else:
        fault_markers = {
            "short-write": ("write-result",),
            "short-read": ("read-result", "socket.recv-result"),
            "wrong-payload": ("read-result", "socket.recv-result"),
            "empty-payload": ("read-result", "socket.recv-result"),
            "admitted-denial": ("denial-admitted",),
            "wrong-exception-code": ("raw-policy-error", "raw-gai-error"),
            "close-failure": ("close-error", "socket.close-error"),
            "unlink-failure": ("unlink-error",),
            "fsync-failure": ("fsync-error",),
            "identity-swap": ("lstat-result",),
            "absence-check-failure": ("lstat-result",),
        }
        names = {row[1] for row in facts["lowLevelTrace"] if len(row) > 1}
        assert names & set(fault_markers[str(case["fault"])]), f"{case_id}/{oracle}: low-level fault marker"


def _assert_child_fault_low_level(case_id: str, trace: tuple[tuple[Any, ...], ...]) -> None:
    if case_id.endswith("argv-changed"):
        assert trace[0][0] == "Popen" and trace[0][1] == ("WRONG",), f"{case_id}: exact argv oracle"
    elif case_id == "spawn-denial":
        assert trace[0][-1] == "spawn_denied" and not any(row[0] == "selector.drain" for row in trace), f"{case_id}: raw spawn denial"
    elif case_id == "spawn-failure":
        assert trace[0][-1] == "spawn_failed" and not any(row[0] == "selector.drain" for row in trace), f"{case_id}: raw spawn failure"
    elif case_id == "nonzero": assert ("waitpid", 41001, "exit-1") in trace, f"{case_id}: wait status"
    elif case_id == "signal": assert ("waitpid", 41001, "signal-9") in trace, f"{case_id}: signal status"
    elif case_id == "partial-stdout": assert ("read", "stdout", b"partial") in trace, f"{case_id}: stdout bytes"
    elif case_id == "partial-stderr": assert ("read", "stderr", b"partial") in trace, f"{case_id}: stderr bytes"
    elif case_id == "timeout":
        assert ("monotonic", "deadline") in trace and ("killpg", 41001, "SIGKILL", "sent") in trace, f"{case_id}: bounded timeout cleanup"
    elif case_id == "stdout-overflow": assert ("read", "stdout", 65_537) in trace, f"{case_id}: stdout bound"
    elif case_id == "stderr-overflow": assert ("read", "stderr", 65_537) in trace, f"{case_id}: stderr bound"
    elif case_id == "wrong-pid-pgid": assert ("getpgid", 41001, 41002) in trace, f"{case_id}: pid/pgid equality"
    elif case_id == "missing-eof": assert ("close-pipes", 41001, ("stdout",)) in trace, f"{case_id}: both EOFs"
    elif case_id == "wait-mismatch": assert ("waitpid", 41001, "wrong-pid") in trace, f"{case_id}: matching reap"
    elif case_id == "term-race": assert ("killpg", 41001, "SIGTERM", "ESRCH") in trace, f"{case_id}: TERM race"
    elif case_id == "kill-race": assert ("killpg", 41001, "SIGKILL", "ESRCH") in trace, f"{case_id}: KILL race"
    elif case_id == "surviving-token-row": assert ("post-reap-union", ("survivor",)) in trace, f"{case_id}: family closure"
    elif case_id == "fake-arm-without-popen-trace": assert trace == (("forged-raw-arm", "completed"),), f"{case_id}: concrete Popen trace"
    else: raise AssertionError(f"{case_id}: missing child fault oracle")


def _assert_browser_fault_low_level(case_id: str, trace: tuple[tuple[Any, ...], ...]) -> None:
    baseline = _exercise_semantic_browser_low_level()
    assert trace != baseline, f"{case_id}: browser fault did not alter low-level calls"
    predicates: dict[str, Callable[[tuple[tuple[Any, ...], ...]], bool]] = {
        "wrong-api-path": lambda rows: ("chromium.executable_path", "wrong-api-path") in rows,
        "wrong-version": lambda rows: ("browser.version", "wrong-version") in rows,
        "explicit-executable": lambda rows: any(row[0] == "chromium.launch" and ("executable_path", "API_PATH") in row[1] for row in rows),
        "direct-process-launch": lambda rows: ("subprocess.Popen", "chromium") in rows,
        "missing-page-close": lambda rows: ("page.close",) not in rows,
        "duplicate-page-close": lambda rows: rows.count(("page.close",)) == 2,
        "reordered-page-close": lambda rows: rows.index(("context.close",)) < rows.index(("page.close",)),
        "missing-context-close": lambda rows: ("context.close",) not in rows,
        "duplicate-context-close": lambda rows: rows.count(("context.close",)) == 2,
        "reordered-context-close": lambda rows: rows.index(("browser.close",)) < rows.index(("context.close",)),
        "missing-browser-close": lambda rows: ("browser.close",) not in rows,
        "duplicate-browser-close": lambda rows: rows.count(("browser.close",)) == 2,
        "reordered-browser-close": lambda rows: rows.index(("playwright.stop",)) < rows.index(("browser.close",)),
        "missing-owner-close": lambda rows: ("playwright.stop",) not in rows,
        "duplicate-owner-close": lambda rows: rows.count(("playwright.stop",)) == 2,
        "reordered-owner-close": lambda rows: rows.index(("playwright.stop",)) < rows.index(("context.close",)),
        "no-page": lambda rows: not any(row[0] == "context.new_page" for row in rows),
        "failed-p17": lambda rows: ("consume-p17", False) in rows,
        "ignored-p17": lambda rows: ("consume-p17", False) in rows,
        "wrong-node-hash": lambda rows: ("validate-node-hash", False) in rows,
        "wrong-node-output": lambda rows: ("validate-node-output", False) in rows,
        "wrong-profile-exec-leaves": lambda rows: ("validate-profile", False) in rows,
        "invalid-family-receipt": lambda rows: ("validate-family-receipt", False) in rows,
        "nonquiescent-final-union": lambda rows: ("final-union", ("survivor",)) in rows,
        "stdout-receipt-mismatch": lambda rows: ("validate-stdout-receipt", False) in rows,
        "optional-skip": lambda rows: ("required-not-skipped", False) in rows,
    }
    assert set(predicates) == set(SEMANTIC_BROWSER_FAULTS)
    assert predicates[case_id](trace), f"{case_id}: named browser oracle"


def _observer_sample_projection(trace: tuple[tuple[Any, ...], ...]) -> tuple[str | None, tuple[dict[str, Any], ...]]:
    if len(trace) != 9 or trace[0] != (
        "Popen", _SemanticObserverLowLevel.ARGV, "DEVNULL", "PIPE", "PIPE",
        True, (), True, _SemanticObserverLowLevel.ENVIRONMENT,
    ): return "spawn-contract", ()
    if trace[1] != ("set-nonblocking", "stdout", "stderr"): return "nonblocking", ()
    if trace[2] != ("selector.drain", 2, 4_194_304, 65_536): return "bounds", ()
    if trace[4] != ("stderr", b""): return "stderr", ()
    if trace[5] != ("eof", ("stdout", "stderr")): return "eof", ()
    if trace[6] != ("child-result", "exit-0"): return "child-result", ()
    if trace[8] != ("waitpid", _SemanticObserverLowLevel.PID, 0.5, _SemanticObserverLowLevel.PID, "exit-0"): return "direct-child-wait", ()
    if trace[3][0] != "stdout" or trace[7] != ("parse-rows", trace[3][1]): return "parse-binding", ()
    raw = trace[3][1]
    if len(raw) > 4_194_304: return "stdout-limit", ()
    parsed: list[tuple[int, int, int, str, int, bytes]] = []
    for row in raw.splitlines():
        fields = row.split(maxsplit=5)
        if len(fields) != 6: return "field-count", ()
        try:
            pid, uid, pgid = int(fields[0]), int(fields[1]), int(fields[2])
            state = fields[3].decode("ascii", "strict")
            raw_xstat = fields[4].decode("ascii", "strict")
        except (UnicodeDecodeError, ValueError): return "integer-field", ()
        if pid <= 0: return "pid", ()
        if uid < 0: return "uid", ()
        if pgid <= 0: return "pgid", ()
        if re.fullmatch(r"[IRSTUZ][+<>AELNSsVWX]{0,15}", state) is None: return "state", ()
        if re.fullmatch(r"[0-9a-f]+", raw_xstat) is None: return "xstat", ()
        xstat = int(raw_xstat, 16)
        if xstat < 0: return "xstat", ()
        if not fields[5]: return "command", ()
        parsed.append((pid, uid, pgid, state, xstat, fields[5]))
    pids = [row[0] for row in parsed]
    if pids != sorted(pids): return "pid-order", ()
    if len(pids) != len(set(pids)): return "pid-duplicate", ()
    own_rows = [row for row in parsed if row[0] == _SemanticObserverLowLevel.PID]
    if len(own_rows) != 1 or own_rows[0][2] != _SemanticObserverLowLevel.PID: return "own-row", ()
    if sum(row[2] == _SemanticObserverLowLevel.PID for row in parsed) != 1: return "observer-pgid", ()
    marker = b"QUANT_RADAR_UX1B_PROCESS_TOKEN=" + SEMANTIC_PLAN_PROCESS_TOKEN
    marker_pattern = re.compile(rb"(?:^| )" + re.escape(marker) + rb"(?: |$)")
    remaining = [row for row in parsed if row[0] != _SemanticObserverLowLevel.PID]
    normalized_rows = tuple({
        "pid": pid,
        "uid": uid,
        "processGroupId": pgid,
        "state": state,
        "waitStatus": xstat,
        "markerMatch": marker_pattern.search(command) is not None,
    } for pid, uid, pgid, state, xstat, command in remaining)
    return None, normalized_rows


def _project_semantic_observer_family(
    rows: tuple[dict[str, Any], ...],
    *,
    include_marker: bool,
) -> tuple[dict[str, Any], ...]:
    current_uid = _SemanticObserverLowLevel.CURRENT_UID
    original_pgid = _SemanticObserverLowLevel.ORIGINAL_PGID
    return tuple(
        row
        for row in rows
        if row["uid"] == current_uid
        and (
            row["processGroupId"] == original_pgid
            or (include_marker and row["markerMatch"])
        )
    )


def _observer_projection(trace: tuple[tuple[Any, ...], ...]) -> tuple[str | None, tuple[dict[str, Any], ...]]:
    if re.fullmatch(rb"ux1b_[0-9a-f]{64}", SEMANTIC_PLAN_PROCESS_TOKEN) is None: return "plan-token-format", ()
    if _sha256(SEMANTIC_PLAN_PROCESS_TOKEN) != SEMANTIC_PLAN_PROCESS_TOKEN_SHA256: return "plan-token-hash", ()
    if len(trace) < 9: return "lifecycle-order-cardinality", ()
    registered_arm = ("NOTE_EXIT.register", _SemanticObserverLowLevel.TARGET_PID, 1, "NOTE_EXIT", "registered")
    esrch_arm = ("NOTE_EXIT.register", _SemanticObserverLowLevel.TARGET_PID, 0, "owned_zombie", "esrch")
    if trace[0] not in {registered_arm, esrch_arm}: return "note-exit", ()
    if trace[1][:2] != ("sample", "immediate"): return "first-immediate", ()
    immediate_reason, immediate_rows = _observer_sample_projection(trace[1][2])
    if immediate_reason is not None: return f"immediate-{immediate_reason}", ()
    if type(trace[2][1]) is not float or not (0 < trace[2][1] <= 0.05): return "cadence", ()

    immediate_family = _project_semantic_observer_family(immediate_rows, include_marker=True)
    immediate_leaders = tuple(row for row in immediate_family if row["pid"] == _SemanticObserverLowLevel.TARGET_PID)
    if len(immediate_leaders) != 1: return "initial-owned-leader", ()
    immediate_leader = immediate_leaders[0]
    if (
        immediate_leader["uid"] != _SemanticObserverLowLevel.CURRENT_UID
        or immediate_leader["processGroupId"] != _SemanticObserverLowLevel.ORIGINAL_PGID
    ): return "initial-owned-leader", ()
    if trace[0] == registered_arm:
        if immediate_leader["state"].startswith("Z") or immediate_leader["markerMatch"] is not True: return "registered-live-leader", ()
    elif not immediate_leader["state"].startswith("Z") or immediate_leader["markerMatch"] is not False:
        return "esrch-owned-zombie", ()

    cursor = 3
    while cursor < len(trace) and trace[cursor][:2] == ("sample", "settling_exit"):
        settling_reason, settling_rows = _observer_sample_projection(trace[cursor][2])
        if settling_reason is not None: return f"settling-exit-{settling_reason}", ()
        settling_family = _project_semantic_observer_family(settling_rows, include_marker=True)
        settling_leaders = tuple(row for row in settling_family if row["pid"] == _SemanticObserverLowLevel.TARGET_PID)
        if len(settling_leaders) != 1: return "settling-owned-leader", ()
        settling_leader = settling_leaders[0]
        if (
            settling_leader["uid"] != _SemanticObserverLowLevel.CURRENT_UID
            or settling_leader["processGroupId"] != _SemanticObserverLowLevel.ORIGINAL_PGID
            or not settling_leader["state"].startswith("Z")
            or settling_leader["markerMatch"] is not False
            or len(settling_family) < 2
        ): return "settling-family", ()
        cursor += 1

    if len(trace) != cursor + 6: return "lifecycle-order-cardinality", ()
    if trace[cursor][:2] != ("sample", "pre_reap"): return "pre-reap", ()
    pre_reason, pre_rows = _observer_sample_projection(trace[cursor][2])
    if pre_reason is not None: return f"pre-reap-{pre_reason}", ()
    if trace[cursor + 1] != ("owned-pipes-eof", True, True): return "owned-eof", ()
    wait = trace[cursor + 2]
    if wait[:4] != ("waitpid-owned", _SemanticObserverLowLevel.TARGET_PID, 0.5, _SemanticObserverLowLevel.TARGET_PID): return "owned-wait", ()
    if type(wait[4]) is not int or wait[4] < 0: return "owned-wait-status", ()
    if trace[cursor + 3] != ("xstat-wait-equal", wait[4], wait[4]): return "xstat-wait", ()
    if trace[cursor + 4][:2] != ("sample", "post_reap"): return "post-reap", ()
    post_reason, post_rows = _observer_sample_projection(trace[cursor + 4][2])
    if post_reason is not None: return f"post-reap-{post_reason}", ()
    if trace[cursor + 5] != ("post-reap-union", ()): return "post-reap-union", ()
    pre_family = _project_semantic_observer_family(pre_rows, include_marker=True)
    post_family = _project_semantic_observer_family(post_rows, include_marker=True)
    if len(pre_family) != 1: return "pre-reap-cardinality", ()
    pre_leader = pre_family[0]
    if (
        pre_leader["pid"] != _SemanticObserverLowLevel.TARGET_PID
        or pre_leader["uid"] != _SemanticObserverLowLevel.CURRENT_UID
        or pre_leader["processGroupId"] != _SemanticObserverLowLevel.ORIGINAL_PGID
        or not pre_leader["state"].startswith("Z")
        or pre_leader["markerMatch"] is not False
    ): return "zombie-only-pre-reap", ()
    if pre_leader["waitStatus"] != wait[4]: return "xstat-wait", ()
    if post_family: return "post-reap-family", ()
    return None, immediate_family


def _observer_fault_reason(trace: tuple[tuple[Any, ...], ...]) -> str | None:
    return _observer_projection(trace)[0]


def _semantic_reference_facts(recipe: str) -> dict[str, Any]:
    """Test-owned reference twin; it does not read the expected trace builder."""

    recorder = _SemanticTraceRecorder()
    read_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    existing_write_flags = os.O_WRONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    absent_write_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    if recipe == "P01":
        recorder.record("compare-launcher", "authenticated-venv-launcher")
    elif recipe == "P02":
        recorder.record("compare-prefix", "authenticated-live-venv")
    elif recipe == "P03":
        for package in ("fastapi", "streamlit", "playwright"):
            recorder.record("import", package, "authenticated-live-venv")
    elif recipe == "P04":
        recorder.record("open", "candidate/Makefile", read_flags)
        recorder.record("bounded-read-hash", "candidate/Makefile")
        recorder.record("close", "candidate/Makefile")
    elif recipe == "P05":
        for root in ("home", "tmp", "cache", "config", "data"):
            for event in (
                ("create", root, absent_write_flags, 0o600), ("write-fsync-close", root),
                ("nofollow-readback-close", root, read_flags), ("cas-unlink", root),
                ("fsync-parent", root), ("verify-absent", root),
            ):
                recorder.record(*event)
    elif recipe == "P06":
        recorder.record("bounded-read-hash", "base-python-runtime")
        recorder.record("bounded-read-hash", "system-runtime-leaf")
    elif recipe == "P08":
        recorder.record("token-regex", "ux1b_[0-9a-f]{64}")
        recorder.record("token-sha256", "plan")
        recorder.record("token-not-public")
    elif recipe in {"P09", "P10"}:
        family, address = ("AF_INET", "127.0.0.1") if recipe == "P09" else ("AF_INET6", "::1")
        for event in (
            ("socket", family, "SOCK_STREAM"), ("bind", address, 0),
            ("listen", 1), ("connect", "bound-address"), ("accept",),
            ("sendall", "nonempty-marker"), ("recv", "equal-marker"),
            ("close-all", 3),
        ):
            recorder.record(*event)
    elif recipe == "P11":
        for event in (("socket", "AF_INET", "SOCK_DGRAM"), ("bind", "127.0.0.1", 0), ("settimeout", "bounded"), ("recv", "socket.timeout"), ("close-all", 1)):
            recorder.record(*event)
    elif recipe == "P12":
        for event in (("socketpair", (), ()), ("sendall", "nonempty-marker"), ("recv", "equal-marker"), ("close-all", 2)):
            recorder.record(*event)
    elif recipe in {"P13", "P14", "P15"}:
        root = {"P13": "candidate-run-status", "P14": "candidate-ux1b", "P15": "candidate-ui"}[recipe]
        for event in (
            ("create", root, absent_write_flags, 0o600), ("write-fsync-close", root),
            ("nofollow-readback-close", root, read_flags), ("cas-unlink", root),
            ("fsync-parent", root), ("verify-absent", root),
        ):
            recorder.record(*event)
    elif recipe == "P16":
        for event in (("socket", "AF_UNIX", "SOCK_STREAM"), ("bind", "private-tmp/socket"), ("listen", 1), ("close-all", 1), ("cas-unlink", "private-tmp/socket"), ("fsync-parent", "private-tmp"), ("verify-absent", "private-tmp/socket")):
            recorder.record(*event)
    elif recipe in {"P07", "P17", "N01", "N02", "N03", "N24", "N25", "N26"}:
        argv = {
            "P07": ("VENV_LAUNCHER", "-B", "-c", "pass"),
            "P17": ("PLAYWRIGHT_NODE", "--version"),
            "N01": ("/usr/bin/true",),
            "N02": ("/usr/bin/sandbox-exec", "-p", "(version 1)\n(allow default)", "/usr/bin/true"),
            "N03": ("/bin/ps", "-p", "PROBE_PID"),
            "N24": ("PLAYWRIGHT_NODE", "--version"),
            "N25": ("HEADLESS_SHELL", "--version"),
            "N26": ("CHROMIUM_APP", "--version"),
        }[recipe]
        recorder.record("popen", argv, "devnull", "pipe", "pipe", True, (), True)
        if recipe.startswith("P"):
            recorder.record("bounded-selector", 10, 65_536, 65_536)
        recorder.record("raw-child-arm", "completed" if recipe.startswith("P") else "spawn-denied")
        recorder.record("pipes-closed")
        recorder.record("post-reap-union", ())
    elif recipe == "P18":
        for event in (
            ("playwright-start",), ("read-default-executable",),
            ("launch", (), (("headless", True),)), ("new-page", "about:blank"),
            ("read-version",), ("close-page",), ("close-context",),
            ("close-browser",), ("close-owner",), ("consume-p17",),
            ("validate-serialized-stdout",), ("final-family-union", ()),
        ):
            recorder.record(*event)
    else:
        negative_specs = {
            "N04": (("open-denied", "live/Makefile", read_flags, "EPERM|EACCES"),),
            "N05": (("open-denied", "exact-canary", read_flags, "EPERM|EACCES"), ("identity-unchanged", "exact-canary")),
            "N06": (("listdir-denied", "/Users/ken/.ssh", "EPERM|EACCES"),),
            "N07": (("listdir-denied", "/Users/ken/Library/Caches/ms-playwright", "EPERM|EACCES"),),
            "N08": (("open-denied", "live/Makefile", existing_write_flags, "EPERM|EACCES"), ("zero-write-family",)),
            "N09": (("open-denied", "candidate/direct-child", absent_write_flags, 0o600, "EPERM|EACCES"), ("zero-write-family",)),
            "N10": (("open-denied", "live-venv/pyvenv.cfg", existing_write_flags, "EPERM|EACCES"), ("zero-write-family",)),
            "N11": (("open-denied", "headless-shell", existing_write_flags, "EPERM|EACCES"), ("zero-write-family",)),
            "N12": (("socket", "AF_INET", "SOCK_STREAM"), ("connect-denied", "203.0.113.1", 9, "EPERM|EACCES"), ("close-all", 1)),
            "N13": (("socket", "AF_INET", "SOCK_DGRAM"), ("sendto-denied", "nonempty-marker", "1.1.1.1", 53, "EPERM|EACCES"), ("close-all", 1)),
            "N14": (("getaddrinfo-denied", "example.com", 53, "AF_UNSPEC", "SOCK_DGRAM", "EAI_AGAIN|EAI_FAIL|EAI_NONAME"),),
            "N15": (("socket", "AF_INET", "SOCK_STREAM"), ("bind-denied", "127.0.0.1", 0, "EPERM|EACCES"), ("close-all", 1)),
            "N16": (("socket", "AF_INET6", "SOCK_STREAM"), ("bind-denied", "::1", 0, "EPERM|EACCES"), ("close-all", 1)),
            "N17": (("socket", "AF_INET", "SOCK_DGRAM"), ("bind-denied", "127.0.0.1", 0, "EPERM|EACCES"), ("close-all", 1)),
            "N18": (("socket", "AF_INET6", "SOCK_DGRAM"), ("bind-denied", "::1", 0, "EPERM|EACCES"), ("close-all", 1)),
            "N19": (("socket", "AF_UNIX", "SOCK_STREAM"), ("bind-denied", "private-tmp/socket", "EPERM|EACCES"), ("close-all", 1)),
            "N20": (("socket", "AF_INET", "SOCK_DGRAM"), ("sendto-denied", "nonempty-marker", "127.0.0.1", 9, "EPERM|EACCES"), ("close-all", 1)),
            "N21": (("open-denied", "candidate-run-status", absent_write_flags, 0o600, "EPERM|EACCES"), ("zero-write-family",)),
            "N22": (("open-denied", "candidate-ux1b", absent_write_flags, 0o600, "EPERM|EACCES"), ("zero-write-family",)),
            "N23": (("open-denied", "candidate-ui", absent_write_flags, 0o600, "EPERM|EACCES"), ("zero-write-family",)),
        }
        for event in negative_specs[recipe]:
            recorder.record(*event)

    positive = recipe.startswith("P")
    child = SEMANTIC_OWNER_BY_RECIPE[recipe] == "CHILD"
    abstract_trace = tuple(recorder.calls)
    if child:
        low_level_trace, raw_execution = _SemanticChildLowLevelExecutor().execute_raw(recipe)
    else:
        low_level_trace = _semantic_execute_low_level(recipe, abstract_trace)
        raw_execution = None
    return {
        "recipe": recipe,
        "owner": SEMANTIC_OWNER_BY_RECIPE[recipe],
        "trace": abstract_trace,
        "lowLevelTrace": low_level_trace,
        "rawExecution": raw_execution,
        "actualOutcome": "succeeded" if positive else "denied",
        "returnCode": 0 if child else None,
        "signal": None,
        "passed": True,
        "consumed": True,
        "aggregatePassed": True,
        "auditChainValid": True,
        "observerUnion": ("original-pgid", "detached-marker"),
        "observerRowValid": True,
        "foreignInodeUnlinked": False,
    }


def _assert_semantic_facts(recipe: str, facts: dict[str, Any], *, case_id: str) -> None:
    assert facts["recipe"] == recipe, f"{case_id}: recipe identity"
    assert facts["owner"] == SEMANTIC_OWNER_BY_RECIPE[recipe], f"{case_id}: single owner"
    assert facts["trace"] == _semantic_expected_trace(recipe), f"{case_id}: exact primitive trace"
    expected_low_level = _semantic_execute_low_level(recipe, _semantic_expected_trace(recipe))
    assert facts["lowLevelTrace"] == expected_low_level, f"{case_id}: exact low-level trace"
    if SEMANTIC_OWNER_BY_RECIPE[recipe] == "CHILD":
        assert _validate_semantic_raw_child_execution(facts["rawExecution"]) is None, f"{case_id}: closed raw child union"
        assert _validate_semantic_child_trace_binding(recipe, facts["lowLevelTrace"], facts["rawExecution"]) is None, f"{case_id}: raw child/trace binding"
    else:
        assert facts["rawExecution"] is None, f"{case_id}: non-child raw execution"
    assert facts["actualOutcome"] == ("succeeded" if recipe.startswith("P") else "denied"), f"{case_id}: outcome projection"
    expected_return = 0 if SEMANTIC_OWNER_BY_RECIPE[recipe] == "CHILD" else None
    assert facts["returnCode"] == expected_return and facts["signal"] is None, f"{case_id}: child-form projection"
    assert facts["passed"] is True and facts["consumed"] is True, f"{case_id}: returned raw facts consumed"
    assert facts["aggregatePassed"] is True, f"{case_id}: aggregate status"
    assert facts["auditChainValid"] is True, f"{case_id}: audit sequence chain"
    assert facts["observerUnion"] == ("original-pgid", "detached-marker"), f"{case_id}: marker-plus-PGID union"
    assert facts["observerRowValid"] is True, f"{case_id}: observer row grammar"
    assert facts["foreignInodeUnlinked"] is False, f"{case_id}: same-inode CAS cleanup"


def _assert_named_semantic_kill(recipe: str, facts: dict[str, Any], case_id: str, *, oracle: str | None = None) -> None:
    label = case_id if oracle is None else f"{case_id}/{oracle}"
    try:
        _assert_semantic_facts(recipe, facts, case_id=label)
    except AssertionError as exc:
        assert str(exc).startswith(f"{label}:"), f"{label}: unnamed kill: {exc}"
    else:
        raise AssertionError(f"{label}: mutant survived its named oracle")


def _mutated_semantic_facts(recipe: str, case_id: str) -> dict[str, Any]:
    facts = copy.deepcopy(_semantic_reference_facts(recipe))
    trace = list(facts["trace"])

    def replace_event(name: str, replacement: tuple[Any, ...]) -> None:
        index = next(index for index, event in enumerate(trace) if event[0] == name)
        trace[index] = replacement

    if recipe == "P01":
        trace[0] = ("compare-launcher", "/usr/bin/python3")
    elif recipe == "P02":
        trace[0] = ("compare-prefix", "authenticated-live-venv-parent")
    elif recipe == "P03":
        trace = [event for event in trace if event[1] != "playwright"]
    elif recipe == "P04":
        trace[0] = ("open", "candidate/Makefile", os.O_RDONLY | getattr(os, "O_CLOEXEC", 0))
    elif recipe == "P05":
        trace = [event for event in trace if len(event) < 2 or event[1] != "data"]
    elif recipe == "P06":
        trace.pop()
    elif recipe == "P07":
        replace_event("raw-child-arm", ("raw-child-arm", "completed-nonzero-1"))
    elif recipe == "P08":
        replace_event("token-sha256", ("token-sha256", "one-byte-different-token"))
    elif recipe == "P09":
        replace_event("recv", ("recv", "wrong-marker"))
    elif recipe == "P10":
        trace.clear()
    elif recipe == "P11":
        replace_event("recv", ("recv", "one-byte-payload"))
    elif recipe == "P12":
        replace_event("socketpair", ("socketpair", ("AF_UNIX", "SOCK_STREAM"), ()))
    elif recipe == "P13":
        trace = [event for event in trace if event[0] != "fsync-parent"]
    elif recipe == "P14":
        trace[0] = ("create", "candidate-ui", *trace[0][2:])
    elif recipe == "P15":
        trace = [event for event in trace if event[0] != "nofollow-readback-close"]
    elif recipe == "P16":
        trace = [event for event in trace if event[0] not in {"cas-unlink", "fsync-parent", "verify-absent"}]
    elif recipe == "P17":
        replace_event("raw-child-arm", ("raw-child-arm", "completed-wrong-stdout"))
    elif recipe == "P18":
        trace = [event for event in trace if event[0] != "close-context"]
    elif recipe in {"N01", "N26"}:
        trace.clear()
    elif recipe == "N02":
        trace[0] = ("popen", ("/usr/bin/sandbox-exec", "/usr/bin/true"), *trace[0][2:])
    elif recipe == "N03":
        trace[0] = ("popen", ("/bin/ps",), *trace[0][2:])
    elif recipe == "N04":
        trace[0] = ("open-denied", "candidate/Makefile", *trace[0][2:])
    elif recipe == "N05":
        trace[0] = ("open-denied", "canary-sibling", *trace[0][2:])
    elif recipe == "N06":
        trace[0] = ("listdir-denied", "/Users/ken", *trace[0][2:])
    elif recipe == "N07":
        trace[0] = ("listdir-denied", "/Users/ken/Library/Caches", *trace[0][2:])
    elif recipe == "N08":
        trace[0] = ("open-denied", trace[0][1], trace[0][2] | os.O_TRUNC, *trace[0][3:])
    elif recipe == "N09":
        trace[0] = ("open-denied", trace[0][1], trace[0][2] & ~os.O_EXCL, *trace[0][3:])
    elif recipe == "N10":
        trace[0] = ("open-denied", "live-venv", *trace[0][2:])
    elif recipe == "N11":
        trace[0] = ("open-denied", "chromium-app", *trace[0][2:])
    elif recipe == "N12":
        replace_event("connect-denied", ("connect-denied", "203.0.113.2", 9, "EPERM|EACCES"))
    elif recipe == "N13":
        replace_event("sendto-denied", ("sendto-denied", "empty-marker", "1.1.1.1", 53, "EPERM|EACCES"))
    elif recipe == "N14":
        trace[0] = ("getaddrinfo-denied", "example.org", *trace[0][2:])
    elif recipe == "N15":
        trace[0] = ("socket", "AF_INET6", "SOCK_STREAM")
    elif recipe == "N16":
        trace[0] = ("socket", "AF_INET", "SOCK_STREAM")
    elif recipe == "N17":
        trace[0] = ("socket", "AF_INET", "SOCK_STREAM")
    elif recipe == "N18":
        trace[0] = ("socket", "AF_INET6", "SOCK_STREAM")
    elif recipe == "N19":
        trace[:2] = [("open-denied", "private-tmp/socket", os.O_WRONLY, "EPERM|EACCES")]
    elif recipe == "N20":
        replace_event("sendto-denied", ("sendto-denied", "nonempty-marker", "1.1.1.1", 53, "EPERM|EACCES"))
    elif recipe == "N21":
        trace[0] = ("open-denied", "candidate-root", *trace[0][2:])
    elif recipe == "N22":
        trace[0] = ("open-denied", "candidate-ui", *trace[0][2:])
    elif recipe == "N23":
        trace[0] = ("open-denied", "candidate-ux1b", *trace[0][2:])
    elif recipe == "N24":
        trace[0] = ("popen", ("HEADLESS_SHELL", "--version"), *trace[0][2:])
    elif recipe == "N25":
        trace[0] = ("popen", ("HEADLESS_SHELL",), *trace[0][2:])
    else:
        raise AssertionError(f"{case_id}: unknown qualified mutation")
    facts["trace"] = tuple(trace)
    facts["lowLevelTrace"] = _semantic_q_low_level(recipe, facts["trace"])
    return facts


def _semantic_m_mutant(mutant_id: str) -> tuple[str, dict[str, Any]]:
    recipe = {
        "M01": "P09", "M02": "P09", "M03": "P09", "M04": "P04", "M05": "P09",
        "M06": "P13", "M07": "P17", "M08": "N15", "M09": "P12", "M10": "P18",
        "M11": "P18", "M12": "P08", "M13": "P08", "M14": "P08", "M15": "N09",
    }[mutant_id]
    facts = copy.deepcopy(_semantic_reference_facts(recipe))
    if mutant_id == "M01":
        facts["trace"] = ()
    elif mutant_id == "M02":
        facts["trace"] = facts["trace"][:3]
    elif mutant_id == "M03":
        facts["consumed"] = False
        facts["aggregatePassed"] = False
    elif mutant_id == "M04":
        facts["trace"] = (("open", "candidate/Makefile", os.O_RDONLY), *facts["trace"][1:])
    elif mutant_id == "M05":
        facts["trace"] = tuple(("recv", "wrong-marker") if row[:1] == ("recv",) else row for row in facts["trace"])
    elif mutant_id == "M06":
        facts["trace"] = tuple(row for row in facts["trace"] if row[:1] != ("fsync-parent",))
    elif mutant_id == "M07":
        facts["trace"] = tuple(row for row in facts["trace"] if row[:1] != ("bounded-selector",))
    elif mutant_id == "M08":
        facts["trace"] = ()
    elif mutant_id == "M09":
        facts["trace"] = (("socketpair", ("AF_UNIX", "SOCK_STREAM"), ()), *facts["trace"][1:])
    elif mutant_id == "M10":
        facts["trace"] = tuple(("launch", (), (("executable_path", "API_PATH"), ("headless", True))) if row[:1] == ("launch",) else row for row in facts["trace"])
    elif mutant_id == "M11":
        facts["consumed"] = False
    elif mutant_id == "M12":
        facts["observerUnion"] = ("original-pgid",)
    elif mutant_id == "M13":
        facts["auditChainValid"] = False
    elif mutant_id == "M14":
        facts["observerRowValid"] = False
    elif mutant_id == "M15":
        facts["foreignInodeUnlinked"] = True
    facts["lowLevelTrace"] = _semantic_execute_low_level(recipe, tuple(facts["trace"]))
    return recipe, facts


def _semantic_declaration_contract() -> dict[str, Any]:
    typed_names = (
        "ProbeChildPlan", "ProbeChildSpawnDenied", "_ProbeChildCompletedExit",
        "_ProbeChildCompletedSignal", "_ProbeChildTimedOutExit", "_ProbeChildTimedOutSignal",
        "_ProbeChildOutputOverflowExit", "_ProbeChildOutputOverflowSignal",
        "ProbeChildSpawnFailed", "BrowserApiEvidence", "ChildProbeAssertionResult", "BrowserBuildResult",
    )
    protocol_names = ("ProbeSocket", "InProcessPrimitives", "ProbeChildExecutor")
    return {
        "typed": {
            name: tuple((key, repr(value)) for key, value in get_type_hints(getattr(handoff, name)).items())
            for name in typed_names
        },
        "protocols": {
            name: {
                "isProtocol": getattr(getattr(handoff, name), "_is_protocol", None) is True,
                "methods": tuple(
                    (method_name, str(inspect.signature(method)))
                    for method_name, method in getattr(handoff, name).__dict__.items()
                    if inspect.isfunction(method) and not method_name.startswith("_")
                ),
            }
            for name in protocol_names
        },
        "aliases": {
            "ProbeChildCompleted": tuple(value.__name__ for value in get_args(handoff.ProbeChildCompleted)),
            "ProbeChildTimedOutOrOverflow": tuple(value.__name__ for value in get_args(handoff.ProbeChildTimedOutOrOverflow)),
            "ProbeChildExecution": tuple(value.__name__ for value in get_args(handoff.ProbeChildExecution)),
        },
    }


def _assert_test021_semantic_declarations() -> None:
    assert _sha256(_canonical(_semantic_declaration_contract())) == SEMANTIC_DECLARATION_CONTRACT_SHA256
    assert _sha256(handoff.PROBE_BOOTSTRAP.encode("utf-8")) == "2cc4512ad0cde91af302b0ce378065200c542abb9dcb2ab197d9f3266dbd66dc"
    assert len(handoff.PROBE_BOOTSTRAP.encode("utf-8")) == 85
    expected_typed_dict_keys = {
        "ProbeChildPlan": {"id", "argv", "cwd", "environment", "stdin", "timeoutSeconds", "stdoutLimitBytes", "stderrLimitBytes", "passFds", "processGroup"},
        "ProbeChildSpawnDenied": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildCompletedExit": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildCompletedSignal": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildTimedOutExit": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildTimedOutSignal": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildOutputOverflowExit": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "_ProbeChildOutputOverflowSignal": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "ProbeChildSpawnFailed": {"kind", "argv", "pid", "processGroupId", "returnCode", "signal", "stdout", "stderr", "timedOut", "overflowStream", "pipesClosed", "processFamily", "error"},
        "BrowserApiEvidence": {"apiExecutablePath", "observedVersion", "launched", "pageCreated", "pageClosed", "contextClosed", "browserClosed"},
        "ChildProbeAssertionResult": {"outcome", "execution"},
        "BrowserBuildResult": {"outcome", "browser"},
    }
    for name, keys in expected_typed_dict_keys.items():
        declaration = getattr(handoff, name)
        assert declaration.__required_keys__ == frozenset(keys), f"{name}: required keys"
        assert declaration.__optional_keys__ == frozenset(), f"{name}: optional key drift"
    for name in ("ProbeSocket", "InProcessPrimitives", "ProbeChildExecutor"):
        assert getattr(getattr(handoff, name), "_is_protocol", None) is True, f"{name}: not a Protocol"
    spawn_denied_hints = get_type_hints(handoff.ProbeChildSpawnDenied)
    assert spawn_denied_hints["processFamily"] is type(None)
    assert spawn_denied_hints["error"] is OSError
    completed_variants = get_args(handoff.ProbeChildCompleted)
    terminal_variants = get_args(handoff.ProbeChildTimedOutOrOverflow)
    assert completed_variants == (handoff._ProbeChildCompletedExit, handoff._ProbeChildCompletedSignal)
    assert terminal_variants == (
        handoff._ProbeChildTimedOutExit, handoff._ProbeChildTimedOutSignal,
        handoff._ProbeChildOutputOverflowExit, handoff._ProbeChildOutputOverflowSignal,
    )
    assert get_args(handoff.ProbeChildExecution) == (
        handoff.ProbeChildSpawnDenied,
        *completed_variants,
        *terminal_variants,
        handoff.ProbeChildSpawnFailed,
    )
    for variant in (*completed_variants, *terminal_variants):
        hints = get_type_hints(variant)
        assert hints["pipesClosed"] == Literal[True]
        assert hints["processFamily"] == Mapping[str, Any]
        assert (hints["returnCode"] is int) != (hints["signal"] is int)
    for variant in completed_variants:
        hints = get_type_hints(variant)
        assert hints["kind"] == Literal["completed"] and hints["timedOut"] == Literal[False]
        assert hints["overflowStream"] is type(None)
    for variant in terminal_variants[:2]:
        hints = get_type_hints(variant)
        assert hints["kind"] == Literal["timed_out"] and hints["timedOut"] == Literal[True]
        assert hints["overflowStream"] is type(None)
    for variant in terminal_variants[2:]:
        hints = get_type_hints(variant)
        assert hints["kind"] == Literal["output_overflow"] and hints["timedOut"] == Literal[False]
        assert hints["overflowStream"] == Literal["stdout", "stderr"]
    assert {
        name for name, value in handoff.ProbeSocket.__dict__.items()
        if inspect.isfunction(value) and not name.startswith("_")
    } == {"bind", "listen", "getsockname", "accept", "connect", "sendall", "sendto", "recv", "recvfrom", "settimeout", "close"}
    assert {
        name for name, value in handoff.InProcessPrimitives.__dict__.items()
        if inspect.isfunction(value) and not name.startswith("_")
    } == {"import_module", "open", "read", "write", "fstat", "lstat", "close", "unlink", "fsync", "listdir", "scandir", "socket", "socketpair", "getaddrinfo"}
    assert tuple(inspect.signature(handoff.InProcessPrimitives.socketpair).parameters) == ("self",)
    assert tuple(inspect.signature(handoff.ProbeChildExecutor.execute).parameters) == ("self", "plan")

    seam_names = (
        "_evaluate_start_probe_assertion", "_evaluate_token_probe_assertion",
        "_evaluate_inprocess_probe_assertion", "_execute_probe_child",
        "_evaluate_child_probe_assertion", "_exercise_browser_api",
        "_build_browser_probe", "_validate_serialized_browser_probe",
    )
    expected_signatures = {
        "_evaluate_start_probe_assertion": "(assertion_id: 'str', context: 'Mapping[str, Any]') -> 'dict[str, Any]'",
        "_evaluate_token_probe_assertion": "(context: 'Mapping[str, Any]') -> 'dict[str, Any]'",
        "_evaluate_inprocess_probe_assertion": "(assertion_id: 'str', context: 'Mapping[str, Any]', *, primitives: 'InProcessPrimitives') -> 'dict[str, Any]'",
        "_execute_probe_child": "(plan: 'ProbeChildPlan', *, syscalls: 'Any | None' = None) -> 'ProbeChildExecution'",
        "_evaluate_child_probe_assertion": "(assertion_id: 'str', context: 'Mapping[str, Any]', *, executor: 'ProbeChildExecutor') -> 'ChildProbeAssertionResult'",
        "_exercise_browser_api": "(context: 'Mapping[str, Any]', *, playwright_factory: 'Callable[[], Any]') -> 'BrowserApiEvidence'",
        "_build_browser_probe": "(api: 'BrowserApiEvidence', node_execution: 'ProbeChildExecution', runtime: 'Mapping[str, Any]') -> 'BrowserBuildResult'",
        "_validate_serialized_browser_probe": "(browser: 'Mapping[str, Any]', p18: 'Mapping[str, Any]', runtime: 'Mapping[str, Any]', execution_plan: 'Mapping[str, Any]', family_receipt: 'Mapping[str, Any]', *, raw_assertion_bytes: 'bytes', assertion_document: 'Mapping[str, Any]') -> 'None'",
    }
    expected_missing_messages = {
        "_evaluate_start_probe_assertion": "START capability assertion evaluation",
        "_evaluate_token_probe_assertion": "process-family token assertion evaluation",
        "_evaluate_inprocess_probe_assertion": "in-process capability assertion evaluation",
        "_execute_probe_child": "bounded raw probe-child execution",
        "_evaluate_child_probe_assertion": "child capability assertion evaluation",
        "_exercise_browser_api": "default Playwright API evidence",
        "_build_browser_probe": "browser probe and P18 projection",
        "_validate_serialized_browser_probe": "serialized browser probe outer validation",
    }
    for name, expected in expected_signatures.items():
        assert str(inspect.signature(getattr(handoff, name))) == expected, f"{name}: signature drift"
    module_ast = ast.parse(MODULE_PATH.read_text(encoding="utf-8"), feature_version=(3, 10))
    functions = {node.name: node for node in module_ast.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))}
    for name in seam_names:
        node = functions[name]
        assert node.decorator_list == [], f"{name}: decorator side effect"
        assert len(node.body) == 1 and isinstance(node.body[0], ast.Expr), f"{name}: body is not immediate missing"
        call = node.body[0].value
        assert isinstance(call, ast.Call) and isinstance(call.func, ast.Name) and call.func.id == "_missing", f"{name}: non-missing behavior"
        assert len(call.args) == 2 and all(isinstance(argument, ast.Constant) for argument in call.args), f"{name}: missing arguments are not literals"
        assert tuple(argument.value for argument in call.args) == ("TEST-021", expected_missing_messages[name]), f"{name}: wrong missing literals"
        assert call.keywords == [], f"{name}: missing seam keyword side effect"
    test_module_ast = ast.parse(Path(__file__).read_text(encoding="utf-8"), feature_version=(3, 10))
    test_functions = {
        node.name: node
        for node in test_module_ast.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    fitness_node = test_functions["_assert_test021_semantic_harness_fitness"]
    fitness_calls = [node for node in ast.walk(fitness_node) if isinstance(node, ast.Call)]
    required_direct_helpers = (
        "test_semantic_matrix_and_independent_oracles", "test_semantic_reference_twin",
        "test_semantic_recipe_mutant_matrix", "test_semantic_inprocess_fault_matrix",
        "test_semantic_child_fault_matrix", "test_semantic_browser_fault_matrix",
        "test_semantic_observer_fault_matrix",
    )
    direct_names = tuple(
        call.func.id for call in fitness_calls if isinstance(call.func, ast.Name)
    )
    assert all(direct_names.count(name) == 1 for name in required_direct_helpers), "semantic helper call graph drift"
    dynamic_m_calls = tuple(
        call for call in fitness_calls
        if isinstance(call.func, ast.Subscript)
        and isinstance(call.func.value, ast.Call)
        and isinstance(call.func.value.func, ast.Name)
        and call.func.value.func.id == "globals"
    )
    assert len(dynamic_m_calls) == 1, "M helper call graph drift"
    probe_node = functions["_run_capability_probe"]
    assert len(probe_node.body) == 1 and isinstance(probe_node.body[0], ast.Expr)

    invocations: tuple[Callable[[], Any], ...] = (
        lambda: handoff._evaluate_start_probe_assertion("P01", {}),
        lambda: handoff._evaluate_token_probe_assertion({}),
        lambda: handoff._evaluate_inprocess_probe_assertion("P03", {}, primitives=object()),  # type: ignore[arg-type]
        lambda: handoff._execute_probe_child({}, syscalls=object()),  # type: ignore[arg-type]
        lambda: handoff._evaluate_child_probe_assertion("P07", {}, executor=object()),  # type: ignore[arg-type]
        lambda: handoff._exercise_browser_api({}, playwright_factory=lambda: None),
        lambda: handoff._build_browser_probe({}, {}, {}),  # type: ignore[arg-type]
        lambda: handoff._validate_serialized_browser_probe({}, {}, {}, {}, {}, raw_assertion_bytes=b"", assertion_document={}),
        handoff._run_capability_probe,
    )
    for invoke in invocations:
        try:
            invoke()
        except handoff.ThemeHandoffNotImplemented as exc:
            assert exc.test_ids == ("TEST-021",)
        else:
            raise AssertionError("Task 1 seam did not fail closed")


def test_semantic_matrix_and_independent_oracles() -> None:
    capability_order = (
        "candidate-basic-v1", "candidate-browser-tcp-unix-ux1b-v1",
        "candidate-tcp-loopback-ux1b-v1", "candidate-tcp-loopback-v1",
        "candidate-udp-bind-v1", "candidate-write-run-status-v1",
    )
    assert tuple(sorted(CAPABILITIES)) == capability_order
    composites = tuple(
        (
            capability_id, polarity, position, assertion_id,
            SEMANTIC_RECIPE_BY_ASSERTION[assertion_id],
            SEMANTIC_OWNER_BY_RECIPE[SEMANTIC_RECIPE_BY_ASSERTION[assertion_id]],
            SEMANTIC_QUALIFIED_KILL_BY_RECIPE[SEMANTIC_RECIPE_BY_ASSERTION[assertion_id]],
        )
        for capability_id in capability_order
        for polarity, assertion_ids in zip(("positive", "negative"), _expected_probe_ids(capability_id))
        for position, assertion_id in enumerate(assertion_ids, 1)
    )
    assert len(composites) == len(set(composites)) == 194
    assert sum(row[1] == "positive" for row in composites) == 63
    assert sum(row[1] == "negative" for row in composites) == 131
    assert _sha256(_canonical(SEMANTIC_RECIPE_BY_ASSERTION)) == SEMANTIC_RECIPE_MAP_SHA256
    assert _sha256(_canonical(composites)) == SEMANTIC_COMPOSITES_SHA256
    assert len(SEMANTIC_RECIPE_BY_ASSERTION) == len(SEMANTIC_OWNER_BY_RECIPE) == 44
    assert set(SEMANTIC_RECIPE_BY_ASSERTION.values()) == set(SEMANTIC_OWNER_BY_RECIPE)
    assert set(SEMANTIC_QUALIFIED_KILL_BY_RECIPE) == set(SEMANTIC_OWNER_BY_RECIPE)
    assert tuple(case["id"] for case in SEMANTIC_Q_CASES) == tuple(SEMANTIC_QUALIFIED_KILL_BY_RECIPE.values())
    assert len({case["id"] for case in SEMANTIC_Q_CASES}) == 44
    assert _sha256(_canonical(SEMANTIC_Q_CASES)) == SEMANTIC_Q_CASES_SHA256
    assert tuple(row[0] for row in SEMANTIC_M_CASES) == tuple(f"M{index:02d}" for index in range(1, 16))
    assert _sha256(_canonical(SEMANTIC_M_CASES)) == SEMANTIC_M_CASES_SHA256
    assert len(SEMANTIC_INPROCESS_FAULTS) == len(SEMANTIC_INPROCESS_FAULT_CASES)
    assert len(SEMANTIC_INPROCESS_FAULTS) == 598
    assert _sha256(_canonical(SEMANTIC_INPROCESS_FAULT_CASES)) == "a306e9837e2cce2874752ca5ac1e4824ae691a0006b34266a6aea2e649bd5d54"
    assert len(SEMANTIC_CHILD_FAULTS) == 47
    assert len(SEMANTIC_BROWSER_FAULTS) == 26
    assert len(SEMANTIC_OBSERVER_FAULTS) == 42
    assert _sha256(_canonical(SEMANTIC_CHILD_FAULTS)) == SEMANTIC_CHILD_FAULTS_SHA256
    assert _sha256(_canonical(SEMANTIC_BROWSER_FAULTS)) == SEMANTIC_BROWSER_FAULTS_SHA256
    assert _sha256(_canonical(SEMANTIC_OBSERVER_FAULTS)) == SEMANTIC_OBSERVER_FAULTS_SHA256
    assert all(len(table) == len(set(table)) for table in (SEMANTIC_INPROCESS_FAULTS, SEMANTIC_CHILD_FAULTS, SEMANTIC_BROWSER_FAULTS, SEMANTIC_OBSERVER_FAULTS))
    for case in SEMANTIC_INPROCESS_FAULT_CASES:
        recipe = case["recipe"]
        index = case["index"]
        mutation = case["mutation"]
        assert recipe in SEMANTIC_INPROCESS_RECIPES
        if mutation != "low-level":
            assert case["id"].startswith(f"{recipe.lower()}-{mutation}-")
        if mutation == "missing":
            label = _semantic_expected_trace(recipe)[index][0].replace("_", "-")
            assert case["oracle"] == f"operation-{index:02d}-{label}"
        elif mutation == "wrong-contract":
            label = _semantic_expected_trace(recipe)[index][0].replace("_", "-")
            assert case["field"] in range(len(_semantic_expected_trace(recipe)[index]))
            assert case["oracle"] == f"operation-{index:02d}-field-{case['field']:02d}-{label}"
        elif mutation == "reordered":
            assert case["oracle"] == f"ordered-edge-{index:02d}-{index + 1:02d}"
        elif mutation == "low-level":
            assert case["index"] == -1
            assert case["oracle"] == f"low-level-{case['fault']}"
            assert case["id"] == f"{recipe.lower()}-fault-{case['fault']}"
        else:
            assert mutation == "extra" and case["oracle"] == "closed-primitive-set"
    assert "_semantic_expected_trace" not in _semantic_reference_facts.__code__.co_names
    assert "_probe_outcome_fixture" not in _semantic_reference_facts.__code__.co_names
    assert "_probe_browser_fixture" not in _semantic_reference_facts.__code__.co_names
    assert not {"expectedOutcome", "passed", "ProbeOutcome"} & set(dir(_SemanticInProcessPrimitives()))
    assert all(callable(getattr(_SemanticInProcessPrimitives(), name)) for name in get_type_hints(handoff.InProcessPrimitives))
    assert all(not test.__name__.startswith("test_semantic_") for _, test in TESTS)


def test_semantic_reference_twin() -> None:
    executed: list[str] = []
    for recipe in SEMANTIC_OWNER_BY_RECIPE:
        _assert_semantic_facts(recipe, _semantic_reference_facts(recipe), case_id=f"REF-{recipe}")
        executed.append(recipe)
    assert tuple(executed) == tuple(SEMANTIC_OWNER_BY_RECIPE), "reference recipe execution ledger"
    reason, rows = _observer_projection(_semantic_reference_facts("P08")["lowLevelTrace"])
    assert reason is None
    assert rows == ({
        "pid": 100, "uid": 501, "processGroupId": 100, "state": "U+<",
        "waitStatus": 10, "markerMatch": True,
    },)
    for noise in ("with-foreign-noise", "with-unrelated-noise"):
        noise_reason, noise_rows = _observer_projection(_SemanticObserverLowLevel().run(noise))
        assert noise_reason is None, f"{noise}: valid noise was rejected: {noise_reason}"
        assert noise_rows == rows, f"{noise}: UID/PGID/token filter leaked an unrelated row"
    detached_reason, detached_rows = _observer_projection(_SemanticObserverLowLevel().run("with-detached-marker"))
    assert detached_reason is None, f"detached marker family was rejected: {detached_reason}"
    assert detached_rows == (
        rows[0],
        {
            "pid": 101, "uid": 501, "processGroupId": 101, "state": "S",
            "waitStatus": 0, "markerMatch": True,
        },
    ), "same-UID detached marker descendant was not retained"
    detached_trace = _SemanticObserverLowLevel().run("with-detached-marker")
    assert tuple(event[1] for event in detached_trace if event[:1] == ("sample",)) == (
        "immediate", "settling_exit", "pre_reap", "post_reap",
    )
    pre_event = next(event for event in detached_trace if event[:2] == ("sample", "pre_reap"))
    pre_reason, pre_rows = _observer_sample_projection(pre_event[2])
    assert pre_reason is None
    pre_family = _project_semantic_observer_family(pre_rows, include_marker=True)
    assert pre_family == ({
        "pid": 100, "uid": 501, "processGroupId": 100, "state": "Z",
        "waitStatus": 15, "markerMatch": False,
    },), "decisive pre_reap must contain only the owned marker-false zombie leader"
    esrch_reason, esrch_rows = _observer_projection(_SemanticObserverLowLevel().run("esrch-owned-zombie"))
    assert esrch_reason is None, f"valid ESRCH owned-zombie fallback was rejected: {esrch_reason}"
    assert esrch_rows == pre_family, "ESRCH fallback must begin with the same owned zombie leader"
    for changed_token in (b"bad", b"ux1b_" + b"b" * 64):
        with patch.object(_SemanticObserverLowLevel, "TOKEN", changed_token):
            token_reason, _ = _observer_projection(_SemanticObserverLowLevel().run())
        assert token_reason is not None, "observer producer token drift survived the independent plan binding"


