def _run_semantic_m_case(mutant_id: str) -> None:
    recipe, facts = _semantic_m_mutant(mutant_id)
    baseline = _semantic_reference_facts(recipe)["lowLevelTrace"]
    if mutant_id == "M07":
        facts["lowLevelTrace"] = _SemanticChildLowLevelExecutor().execute(recipe, fault="unbounded-child")
        assert any(row[0] == "communicate" and row[2:] == ("no-timeout", "no-stream-limit") for row in facts["lowLevelTrace"]), "M07: bounded selector oracle"
    elif mutant_id == "M10":
        facts["lowLevelTrace"] = _exercise_semantic_browser_low_level("explicit-executable")
        _assert_browser_fault_low_level("explicit-executable", facts["lowLevelTrace"])
    elif mutant_id == "M11":
        facts["lowLevelTrace"] = _exercise_semantic_browser_low_level("ignored-p17")
        _assert_browser_fault_low_level("ignored-p17", facts["lowLevelTrace"])
    elif mutant_id == "M12":
        facts["lowLevelTrace"] = _SemanticObserverLowLevel().run("with-detached-marker")
        reason, correct_family = _observer_projection(facts["lowLevelTrace"])
        assert reason is None and tuple(row["pid"] for row in correct_family) == (100, 101), "M12: correct marker-plus-PGID union"
        pgid_only = _project_semantic_observer_family(correct_family, include_marker=False)
        assert tuple(row["pid"] for row in pgid_only) == (100,), "M12: PGID-only mutant did not drop detached marker PID"
    elif mutant_id == "M13":
        facts["lowLevelTrace"] = _SemanticObserverLowLevel().run("replayed-audit-frame")
        assert ("audit-sequence", "replayed") in facts["lowLevelTrace"], "M13: audit replay oracle"
    elif mutant_id == "M14":
        facts["lowLevelTrace"] = _SemanticObserverLowLevel().run("bad-field-count")
        assert _observer_fault_reason(facts["lowLevelTrace"]) == "immediate-field-count", "M14: raw row grammar oracle"
    elif mutant_id == "M15":
        safe = _exercise_semantic_cas_cleanup(unsafe_unlink=False)
        unsafe = _exercise_semantic_cas_cleanup(unsafe_unlink=True)
        assert safe[-1] == ("foreign-exists", True) and ("unlink-refused", "identity-mismatch") in safe, "M15: safe CAS oracle"
        assert unsafe[-1] == ("foreign-exists", False) and ("unlink", "foreign") in unsafe, "M15: foreign unlink mutant"
        facts["lowLevelTrace"] = unsafe
    if mutant_id in {"M07", "M10", "M11", "M12", "M13", "M14", "M15"}:
        assert facts["lowLevelTrace"] != baseline, f"{mutant_id}: low-level mutation not exercised"
    oracle = next(row[2] for row in SEMANTIC_M_CASES if row[0] == mutant_id)
    _assert_named_semantic_kill(recipe, facts, mutant_id, oracle=oracle)


