def test_semantic_inprocess_fault_matrix() -> None:
    inprocess_recipes = tuple(recipe for recipe, owner in SEMANTIC_OWNER_BY_RECIPE.items() if owner == "INPROC")
    assert len(inprocess_recipes) == 32
    assert inprocess_recipes == SEMANTIC_INPROCESS_RECIPES
    executed: list[str] = []
    for case in SEMANTIC_INPROCESS_FAULT_CASES:
        case_id = case["id"]
        recipe = case["recipe"]
        facts = copy.deepcopy(_semantic_reference_facts(recipe))
        if case["mutation"] == "low-level":
            primitives = _SemanticInProcessPrimitives(fault=case["fault"])
            for index, operation in enumerate(facts["trace"]): primitives.perform(index, operation)
            facts["lowLevelTrace"] = tuple(primitives.calls)
        else:
            facts["trace"] = _mutate_inprocess_operations(case)
            try:
                facts["lowLevelTrace"] = _semantic_execute_low_level(recipe, facts["trace"])
            except (AssertionError, KeyError, TypeError, ValueError) as exc:
                facts["lowLevelTrace"] = (("low-level-rejected", type(exc).__name__),)
        assert facts["lowLevelTrace"] != _semantic_reference_facts(recipe)["lowLevelTrace"], f"{case_id}: low-level fault was not exercised"
        _assert_inprocess_fault_injected(case, facts)
        _assert_named_semantic_kill(recipe, facts, case_id, oracle=case["oracle"])
        executed.append(case_id)
    assert tuple(executed) == SEMANTIC_INPROCESS_FAULTS, "INPROC fault execution ledger"


def test_semantic_child_fault_matrix() -> None:
    child_recipes = ("P07", "P17", "N01", "N02", "N03", "N24", "N25", "N26")
    raw_union_faults = {
        "completed-both-status", "completed-missing-status", "timed-out-false",
        "timed-out-with-overflow", "overflow-timed-out", "overflow-missing-stream",
        "spawn-denied-with-family", "spawn-denied-non-oserror",
        "spawn-denied-wrong-errno", "spawn-failed-policy-error", "spawn-denied-bool-errno",
        "return-code-bool", "signal-bool", "pid-bool", "pgid-bool", "nested-family-pgid-bool",
    }
    raw_binding_faults = {
        "raw-only-argv", "raw-only-return-code", "raw-only-signal",
        "raw-only-pid-family", "raw-only-stdout", "raw-only-kind", "shared-p17-stdout",
    }
    executed: list[str] = []
    for case_id in SEMANTIC_CHILD_FAULTS:
        recipe = case_id[:3].upper() if case_id.endswith("argv-changed") else "P17"
        assert recipe in child_recipes
        facts = copy.deepcopy(_semantic_reference_facts(recipe))
        facts["lowLevelTrace"], facts["rawExecution"] = _SemanticChildLowLevelExecutor().execute_raw(recipe, fault=case_id)
        if case_id in raw_union_faults:
            assert _validate_semantic_raw_child_execution(facts["rawExecution"]) is not None, f"{case_id}: impossible raw arm accepted"
        elif case_id in raw_binding_faults:
            assert _validate_semantic_raw_child_execution(facts["rawExecution"]) is None, f"{case_id}: raw-only mutant must remain internally shaped"
            assert _validate_semantic_child_trace_binding(recipe, facts["lowLevelTrace"], facts["rawExecution"]) is not None, f"{case_id}: raw-only mismatch accepted"
        else:
            _assert_child_fault_low_level(case_id, facts["lowLevelTrace"])
            assert facts["lowLevelTrace"] != _semantic_reference_facts(recipe)["lowLevelTrace"], f"{case_id}: low-level child fault was not exercised"
        _assert_named_semantic_kill(recipe, facts, case_id)
        executed.append(case_id)
    assert tuple(executed) == SEMANTIC_CHILD_FAULTS, "CHILD fault execution ledger"


