def _assert_test021_semantic_harness_fitness() -> None:
    executed_helpers: list[str] = []
    test_semantic_matrix_and_independent_oracles()
    executed_helpers.append("matrix-and-independent-oracles")
    test_semantic_reference_twin()
    executed_helpers.append("reference-twin")
    test_semantic_recipe_mutant_matrix()
