        if result is not None:
            assert raw_killpg.call_count == 0
            assert raw_kill.call_count == 0
            assert result == case["expected"]
            expected_syscalls = tuple(call for call in case["calls"] if call[0] != "release_lease")
            expected_leases = tuple(call for call in case["calls"] if call[0] == "release_lease")
            if not expected_leases and result["leasesReleased"]:
                expected_leases = tuple(("release_lease", lease) for lease in fixture["leases"])
            assert tuple(recorder.calls) == expected_syscalls
            assert tuple(recorder.lease_calls) == expected_leases
            assert recorder.rejected_calls == []
            signal_targets = {call[2] for call in recorder.calls if call[0] == "killpg"}
            assert signal_targets <= {fixture["runnerPgid"], fixture["observerPgid"]}
            assert fixture["markerPid"] not in signal_targets
            assert fixture["detachedMarkerPgid"] not in signal_targets
            observer_signals = [call for call in recorder.calls if call[:2] == ("killpg", "observer")]
            runner_signals = [call for call in recorder.calls if call[:2] == ("killpg", "runner")]
            assert observer_signals in ([], [("killpg", "observer", fixture["observerPgid"], signal.SIGKILL)])
            assert runner_signals in (
                [],
                [("killpg", "runner", fixture["runnerPgid"], signal.SIGTERM)],
                [
                    ("killpg", "runner", fixture["runnerPgid"], signal.SIGTERM),
                    ("killpg", "runner", fixture["runnerPgid"], signal.SIGKILL),
                ],
            )

