def _schema_process_fixtures() -> dict[str, Any]:
    runtime = _runtime_receipt_fixture()
    observer = {
        "executable": next(
            row for row in runtime["directExecutables"] if row["absolutePath"] == "/bin/ps"
        ),
        "argv": [
            "/bin/ps",
            "eww",
            "-axo",
            "pid=,uid=,pgid=,stat=,xstat=,command=",
        ],
        "environment": {
            "PATH": "/usr/bin:/bin:/usr/sbin:/sbin",
            "LANG": "C",
            "LC_ALL": "C",
        },
        "stdin": "devnull",
        "timeoutSeconds": 2,
        "waitTimeoutSeconds": 0.5,
        "stdoutLimitBytes": 4_194_304,
        "stderrLimitBytes": 65_536,
        "processGroup": "new",
        "passFds": [],
        "failureCleanup": {
            "kind": "direct_owned_observer",
            "target": "observer_pgid",
            "signal": "SIGKILL",
            "maxKillpgCalls": 1,
            "killPidCalls": 0,
            "allowEsrch": True,
            "allowOwnedZombieEperm": True,
            "closeLocalFdsOnTimeout": True,
        },
    }
    exit_watch = {
        "kind": "darwin_kqueue_proc",
        "filter": "EVFILT_PROC",
        "flags": ["EV_ADD", "EV_ENABLE", "EV_CLEAR"],
        "fflags": ["NOTE_EXIT"],
        "alreadyExitedFallback": "esrch_requires_owned_zombie",
    }
    token_plan = {
        "kind": "token_pgid",
        "environmentKey": "QUANT_RADAR_UX1B_PROCESS_TOKEN",
        "tokenSha256": "5" * 64,
        "tokenFormat": "ux1b_<64hex>",
        "observer": observer,
        "exitWatch": exit_watch,
        "quiescenceTimeoutSeconds": 25,
        "termGraceSeconds": 3,
        "killGraceSeconds": 7,
    }
    outer_plan = {
        "kind": "outer_pgid",
        "observer": observer,
        "exitWatch": exit_watch,
        "quiescenceTimeoutSeconds": 25,
        "termGraceSeconds": 3,
        "killGraceSeconds": 7,
    }

    def row(*, zombie: bool, marker: bool, wait_status: int) -> dict[str, Any]:
        return {
            "pid": 100,
            "uid": os.getuid(),
            "processGroupId": 100,
            "state": "Z" if zombie else "R",
            "waitStatus": wait_status,
            "markerMatch": marker,
        }

    def sample(
        phase: str,
        *,
        rows: Sequence[dict[str, Any]],
        stdout_byte: str,
        stdout_eof: bool = True,
        stderr_eof: bool = True,
    ) -> dict[str, Any]:
        observer_pid = 200 + int(stdout_byte, 16)
        return {
            "phase": phase,
            "observerPid": observer_pid,
            "observerProcessGroupId": observer_pid,
            "rows": list(rows),
            "observerReturnCode": 0,
            "observerSignal": None,
            "stdoutSha256": stdout_byte * 64,
            "stderrSha256": EMPTY_SHA256,
            "stdoutBytes": 10,
            "stderrBytes": 0,
            "runnerStdoutEof": stdout_eof,
            "runnerStderrEof": stderr_eof,
        }

    def receipt(
        plan: dict[str, Any],
        closure_kind: str,
        *,
        return_code: int | None,
        signal_number: int | None,
        exit_result: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        wait_status = return_code << 8 if return_code is not None else signal_number
        assert wait_status is not None
        live_marker = plan["kind"] == "token_pgid"
        zombie = row(zombie=True, marker=False, wait_status=wait_status)
        live = row(zombie=False, marker=live_marker, wait_status=0)
        phases: dict[str, list[dict[str, Any]]] = {
            "clean_exit": [
                sample("pre_reap", rows=[zombie], stdout_byte="6"),
                sample("post_reap", rows=[], stdout_byte="7"),
            ],
            "failed_no_signal": [
                sample("pre_no_signal", rows=[zombie], stdout_byte="6"),
                sample("pre_reap", rows=[zombie], stdout_byte="7"),
                sample("post_reap", rows=[], stdout_byte="8"),
            ],
            "terminated_term": [
                sample("pre_term", rows=[live], stdout_byte="6", stdout_eof=False),
                sample("pre_reap", rows=[zombie], stdout_byte="7"),
                sample("post_reap", rows=[], stdout_byte="8"),
            ],
            "terminated_kill": [
                sample("pre_term", rows=[live], stdout_byte="6", stdout_eof=False),
                sample("pre_kill", rows=[live], stdout_byte="7", stdout_eof=False),
                sample("pre_reap", rows=[zombie], stdout_byte="8"),
                sample("post_reap", rows=[], stdout_byte="9"),
            ],
        }
        without_digest = {
            "plan": plan,
            "closureKind": closure_kind,
            "leaderPid": 100,
            "processGroupId": 100,
            "ownerUid": os.getuid(),
            "exitWatchResult": exit_result
            or {"registration": "registered", "outcome": "note_exit", "eventCount": 1},
            "samples": phases[closure_kind],
            "quiescent": True,
            "leaderTermination": {
                "returnCode": return_code,
                "signal": signal_number,
                "waitStatus": wait_status,
            },
        }
        return {
            **without_digest,
            "observationSha256": _sha256(
                b"quant-radar-ui-ux-process-observation/v1\0"
                + _canonical(without_digest)
            ),
        }

    receipts = {
        "clean_exit": receipt(
            token_plan,
            "clean_exit",
            return_code=0,
            signal_number=None,
        ),
        "failed_no_signal": receipt(
            token_plan,
            "failed_no_signal",
            return_code=None,
            signal_number=15,
        ),
        "terminated_term": receipt(
            token_plan,
            "terminated_term",
            return_code=None,
            signal_number=15,
        ),
        "terminated_kill": receipt(
            token_plan,
            "terminated_kill",
            return_code=None,
            signal_number=9,
        ),
    }
    outer_clean = receipt(
        outer_plan,
        "clean_exit",
        return_code=0,
        signal_number=None,
    )
    esrch_clean = receipt(
        token_plan,
        "clean_exit",
        return_code=0,
        signal_number=None,
        exit_result={"registration": "esrch", "outcome": "owned_zombie", "eventCount": 0},
    )
    nonzero = receipt(
        token_plan,
        "clean_exit",
        return_code=1,
        signal_number=None,
    )
    signaled = receipt(
        token_plan,
        "clean_exit",
        return_code=None,
        signal_number=15,
    )

    def result(
        identifier: str,
        *,
        kind: str = "candidate_python",
        status: str,
        outcome: str,
        error_code: str | None = None,
        return_code: int | None = None,
        signal_number: int | None = None,
        family: dict[str, Any] | None = None,
        overflow: bool = False,
    ) -> dict[str, Any]:
        byte_count = 1_048_577 if overflow else 0
        return {
            "id": identifier,
            "kind": kind,
            "status": status,
            "outcome": outcome,
            "errorCode": error_code,
            "returnCode": return_code,
            "signal": signal_number,
            "stdoutSha256": "a" * 64 if overflow else EMPTY_SHA256,
            "stderrSha256": EMPTY_SHA256,
            "stdoutBytes": byte_count,
            "stderrBytes": 0,
            "processGroupId": None if family is None else family["processGroupId"],
            "processFamily": family,
        }

    command_results = [
        result("INTERNAL-PASS", kind="internal", status="passed", outcome="internal"),
        result("INTERNAL-ASSERT", kind="internal", status="failed", outcome="internal", error_code="assertion_failed"),
        result("INTERNAL-EXCEPTION", kind="internal", status="failed", outcome="internal", error_code="internal_exception"),
        result("EXTERNAL-NOT-RUN", status="not_run", outcome="not_run"),
        result("EXTERNAL-SPAWN", status="failed", outcome="spawn_failed"),
        result("EXTERNAL-EXIT-0", status="passed", outcome="exited", return_code=0, family=receipts["clean_exit"]),
        result("EXTERNAL-EXIT-1", status="failed", outcome="exited", return_code=1, family=nonzero),
        result("EXTERNAL-SIGNAL", status="failed", outcome="signaled", signal_number=15, family=signaled),
    ]
    for closure_kind in ("failed_no_signal", "terminated_term", "terminated_kill"):
        command_results.append(
            result(
                f"EXTERNAL-TIMEOUT-{closure_kind}",
                status="failed",
                outcome="timed_out",
                family=receipts[closure_kind],
            )
        )
        command_results.append(
            result(
                f"EXTERNAL-OVERFLOW-{closure_kind}",
                status="failed",
                outcome="output_overflow",
                family=receipts[closure_kind],
                overflow=True,
            )
        )

    return {
        "observer": observer,
        "exitWatch": exit_watch,
        "tokenPlan": token_plan,
        "outerPlan": outer_plan,
        "receipts": receipts,
        "outerClean": outer_clean,
        "esrchClean": esrch_clean,
        "commandResults": command_results,
    }


def _schema_capability(capability_id: str) -> dict[str, Any]:
    network, environment_id, template_sha = CAPABILITIES[capability_id]
    browser = capability_id == "candidate-browser-tcp-unix-ux1b-v1"
    read_roles = [
        "candidate-root",
        "private-home",
        "private-tmp",
        "private-cache",
        "private-config",
        "private-data",
        "live-venv",
        "base-python-runtime",
        "system-runtime",
    ]
    if browser:
        read_roles.append("headless-shell-runtime")
    write_roles = [
        "private-home",
        "private-tmp",
        "private-cache",
        "private-config",
        "private-data",
        "dev-null",
    ]
    write_roles.extend(
        {
            "candidate-write-run-status-v1": ["candidate-run-status"],
            "candidate-tcp-loopback-ux1b-v1": ["candidate-ux1b"],
            "candidate-browser-tcp-unix-ux1b-v1": ["candidate-ux1b", "candidate-ui"],
        }.get(capability_id, [])
    )
    return {
        "id": capability_id,
        "network": network,
        "execRoles": (
            ["resolved-python", "playwright-node", "headless-shell"]
            if browser
            else ["resolved-python"]
        ),
        "readRoles": read_roles,
        "writeRoles": write_roles,
        "environmentId": environment_id,
        "profileTemplateSha256": template_sha,
    }


