def _schema_runner_receipt(
    process: dict[str, Any],
    capability_id: str,
    *,
    index: int,
) -> dict[str, Any]:
    family_plan = copy.deepcopy(process["tokenPlan"])
    family_plan["tokenSha256"] = _sha256(
        f"schema-probe-token-{index}".encode("ascii")
    )
    execution = _schema_execution_plan(
        family_plan,
        capability_id,
        index=index,
    )
    execution["argv"] = [
        "/Users/ken/Workspace/AI/surge-screener/.venv/bin/python",
        "-B",
        "-c",
        handoff.PROBE_BOOTSTRAP,
    ]
    runner_plan = {
        "kind": "capability_probe",
        "stage": "capability-probe",
        "execution": execution,
        "capabilityId": capability_id,
    }
    family = copy.deepcopy(process["receipts"]["clean_exit"])
    family["plan"] = execution["processFamily"]
    without_digest = {key: family[key] for key in family if key != "observationSha256"}
    family["observationSha256"] = _sha256(
        b"quant-radar-ui-ux-process-observation/v1\0" + _canonical(without_digest)
    )
    return {
        "plan": runner_plan,
        "startedAt": "2026-07-20T00:00:00Z",
        "finishedAt": "2026-07-20T00:00:01Z",
        "outcome": "exited",
        "returnCode": 0,
        "signal": None,
        "stdoutSha256": EMPTY_SHA256,
        "stderrSha256": EMPTY_SHA256,
        "stdoutBytes": 0,
        "stderrBytes": 0,
        "processGroupId": family["processGroupId"],
        "processFamily": family,
    }


