def _schema_wrong_type(value: Any) -> Any:
    if value is None:
        return "unexpected-nonnull"
    if type(value) is bool:
        return 0
    if type(value) is int:
        return True
    if isinstance(value, str):
        return []
    if isinstance(value, list):
        return {}
    if isinstance(value, dict):
        return []
    return None


def _schema_replace_at(value: Any, path: tuple[Any, ...], replacement: Any) -> Any:
    def replace(node: Any, depth: int) -> Any:
        if depth == len(path):
            return replacement
        part = path[depth]
        attacked = dict(node) if isinstance(node, dict) else list(node)
        attacked[part] = replace(node[part], depth + 1)
        return attacked

    return replace(value, 0)


def _recursive_schema_attacks(
    value: dict[str, Any],
) -> Iterator[tuple[str, dict[str, Any]]]:
    def walk(node: Any, path: tuple[Any, ...]) -> Iterator[tuple[str, dict[str, Any]]]:
        rendered = ".".join(str(part) for part in path) or "<root>"
        if isinstance(node, dict):
            attacked_node = dict(node)
            attacked_node["__unknown_schema_key__"] = None
            yield (
                f"extra key at {rendered}",
                _schema_replace_at(value, path, attacked_node),
            )
            for key, child in node.items():
                attacked_node = dict(node)
                attacked_node.pop(key)
                yield (
                    f"missing {rendered}.{key}",
                    _schema_replace_at(value, path, attacked_node),
                )
                yield (
                    f"wrong type at {rendered}.{key}",
                    _schema_replace_at(value, path + (key,), _schema_wrong_type(child)),
                )
                if type(child) is int:
                    yield (
                        f"bool-as-int at {rendered}.{key}",
                        _schema_replace_at(value, path + (key,), True),
                    )
                yield from walk(child, path + (key,))
        elif isinstance(node, list):
            for index, child in enumerate(node):
                yield (
                    f"wrong type at {rendered}[{index}]",
                    _schema_replace_at(
                        value,
                        path + (index,),
                        _schema_wrong_type(child),
                    ),
                )
                if type(child) is int:
                    yield (
                        f"bool-as-int at {rendered}[{index}]",
                        _schema_replace_at(value, path + (index,), True),
                    )
                yield from walk(child, path + (index,))

    yield from walk(value, ())


def test_029_recursive_schemas_hash_preimages_and_tagged_unions_reject_mutations() -> None:
    missing: list[str] = []
    schema_missing: list[str] = []
    expected_hunk = {
        "path": "app.py",
        "kind": "hunk",
        "preimageSha256": "507be3b6270f1b18d140d3e744d2878c17059d9d6abff6f8a086a227cc54a0e4",
        "postimageSha256": "7e547921f7a2e0f7369bb0d3abf1910ee55c0e3c97663fe46171df3b71c29d46",
        "startByte": 3,
        "endByte": 6,
        "prefixSha256": "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        "suffixSha256": "3608bca1e44ea6c4d268eb6db02260269892c0b42b86bbf1e77a6fa16c3c9282",
        "preimageSpanSha256": "099d90cbee62f89e6478e153eb3240efcbe4ac2231bedc3e84549bbeaaba87e8",
        "postimageSpanSha256": "775653072817f6d0c39da9f29b7747925c12b57a0dd5414463423915c3f07555",
    }
    expected_append = {
        "path": "Makefile",
        "kind": "append",
        "preimageSha256": "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        "postimageSha256": "d2a8fbab0db20adee57d10f25260e3309f108e2b198ad80ee605fdd7e193f2ad",
        "startByte": 3,
        "endByte": 3,
        "prefixSha256": "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        "suffixSha256": EMPTY_SHA256,
        "preimageSpanSha256": EMPTY_SHA256,
        "postimageSpanSha256": "cfc0c0607a3380f7975346b30c14af8284f5493d9781b0ed847f499f01b4768e",
    }
    hunk = _attempt_missing(missing, "_build_hunk_anchor", "app.py", b"abcOLDxyz", b"abcNEW!xyz")
    if hunk is not None:
        assert hunk == expected_hunk
    append = _attempt_missing(missing, "_build_hunk_anchor", "Makefile", b"abc", b"abc++")
    if append is not None:
        assert append == expected_append

    catalog = _attempt_missing(missing, "_schema_contract_catalog")
    if catalog is not None:
        assert catalog == SCHEMA_TOP_KEYS
        assert len(catalog) == 28

    content_pre = {"path": "app.py", "sha256": "1" * 64, "size": 1, "mode": "0644"}
