    attacked["path"] = "app.py"
    target("DesiredLiveContent", attacked, "path must be absent")
    attacked = copy.deepcopy(live_images[3])
    attacked["artifact"]["contentReadable"] = False
    target("UnknownRegularLiveImage", attacked, "false with nonnull hash")
    attacked = copy.deepcopy(live_images[4])
    attacked["artifact"]["contentReadable"] = True
    target("UnknownRegularLiveImage", attacked, "true with null hash")
    attacked = copy.deepcopy(live_images[0])
    attacked["kind"] = "unknown_regular"
    target("LiveImageRecord", attacked, "live image enum/tag mismatch")
    attacked = copy.deepcopy(expected_hunk)
    attacked["startByte"] = 4
    target("HunkAnchor", attacked, "wrong longest prefix")
    attacked = copy.deepcopy(expected_hunk)
    attacked["postimageSpanSha256"] = "0" * 64
    target("HunkAnchor", attacked, "wrong raw slice hash")
    attacked = copy.deepcopy(root_candidate)
    attacked["proposedContractSha256"] = "0" * 64
    target("RootCandidate", attacked, "wrong proposed root preimage")
    attacked = copy.deepcopy(root_candidate)
    attacked["diagnosticPorcelainSha256"] = "0" * 64
    target("RootCandidate", attacked, "removed diagnostic key")
    attacked = copy.deepcopy(root_candidate)
    attacked["proposedContract"] = None
    target("RootCandidate", attacked, "nonnull proposed root")
    attacked = copy.deepcopy(token_plan)
    attacked["kind"] = "outer_pgid"
    target("TokenProcessFamilyPlan", attacked, "tagged plan arm")
    attacked = copy.deepcopy(process_receipt)
    attacked["samples"] = list(reversed(attacked["samples"]))
    target("ProcessFamilyReceipt", attacked, "phase order")
    attacked = copy.deepcopy(process_receipt)
    attacked["observationSha256"] = "0" * 64
    target("ProcessFamilyReceipt", attacked, "observation digest")
    attacked = copy.deepcopy(process["commandResults"][5])
    attacked["outcome"] = "timed_out"
    target("CommandResult", attacked, "command outcome nullability")
    attacked = copy.deepcopy(process["commandResults"][3])
    attacked["stdoutSha256"] = "1" * 64
    target("CommandResult", attacked, "not-run stream must be empty")
