    attacked["passed"] = 55
    target("SnapshotSubsetReceipt", attacked, "not exact 56")
    attacked = copy.deepcopy(candidate_manifest)
    attacked["root"]["path"] = "relative"
    target("CandidateWorkspaceManifest", attacked, "candidate root not absolute")
    attacked = copy.deepcopy(candidate_manifest)
    attacked["digest"] = "0" * 64
    target("CandidateWorkspaceManifest", attacked, "candidate manifest digest")
    attacked = copy.deepcopy(candidate["workspace"])
