    attacked = copy.deepcopy(candidate["probeOutcomeCases"][2])
    attacked["returnCode"] = None
    target("ProbeOutcome", attacked, "denied child-form return-code arm")
    attacked = copy.deepcopy(candidate["probeOutcomeCases"][3])
    attacked["returnCode"] = 0
    target("ProbeOutcome", attacked, "denied in-process return-code arm")
    attacked = copy.deepcopy(batch["captureRunner"])
    attacked["processFamily"] = None
    target("RunnerReceipt", attacked, "success-only family is nonnull")
    attacked = copy.deepcopy(batch["themeBatchTestReport"])
    attacked["sha256"] = "0" * 64
    target("ThemeBatchTestReport", attacked, "combined report no-domain digest")
    attacked = copy.deepcopy(batch["postApplyPlan"])
    attacked["commands"] = list(reversed(attacked["commands"]))
    target("PostApplyPlan", attacked, "post-apply command order")
    attacked = copy.deepcopy(batch["postApplyPlan"])
    attacked["sha256"] = _sha256(
        b"wrong-domain\0" + _canonical({"commands": attacked["commands"]})
    )
    target("PostApplyPlan", attacked, "post-apply digest domain injection")
    attacked = copy.deepcopy(batch["postApplyReport"])
    attacked["resultsSha256"] = "0" * 64
    target("PostApplyTestReport", attacked, "post-apply results digest")
