def test_037_system_tmp_inherited_group_is_fd_normalized() -> None:
    temp_root = Path(
        "/private/tmp"
    ) / f".quant-radar-ux1b-seq5-{os.getpid()}-{time.time_ns()}"
    assert not temp_root.exists() and not temp_root.is_symlink()
    retained_fd: int | None = None
    inherited_groups: list[int] = []
    real_fchown = os.fchown

    def observe_fchown(
        fd: int,
        uid: int,
        gid: int,
    ) -> None:
        inherited_groups.append(os.fstat(fd).st_gid)
        real_fchown(fd, uid, gid)

    try:
        with patch.object(
            os,
            "fchown",
            side_effect=observe_fchown,
        ):
            retained_fd, identity = _call(
                "_task9_open_temp_root",
                temp_root,
            )
        observed = os.fstat(retained_fd)
        assert inherited_groups == [0]
        assert (observed.st_dev, observed.st_ino) == identity
        assert observed.st_uid == os.getuid()
        assert observed.st_gid == os.getgid()
        assert stat.S_IMODE(observed.st_mode) == 0o700
        assert os.listdir(retained_fd) == []
    finally:
        if retained_fd is not None:
            os.close(retained_fd)
        if temp_root.exists() and not temp_root.is_symlink():
            os.rmdir(temp_root)


def test_038_system_gid_normalization_is_closed() -> None:
    with tempfile.TemporaryDirectory(
        prefix="surge-ux1b-seq5-parent-"
    ) as raw:
        ordinary_parent = Path(raw)
        temp_root = ordinary_parent / "runtime-root"
        with patch.object(
            os,
            "fchown",
            side_effect=AssertionError(
                "ordinary parent attempted group normalization"
            ),
        ):
            retained_fd, _ = _call(
                "_task9_open_temp_root",
                temp_root,
            )
        os.close(retained_fd)

    system_root = Path(
        "/private/tmp"
    ) / f".quant-radar-ux1b-seq5-nonempty-{os.getpid()}-{time.time_ns()}"
    child = system_root / "collision"
    os.mkdir(system_root, 0o700)
    _write_owned(child, b"x", 0o600)
    try:
        with patch.object(
            os,
            "fchown",
            side_effect=AssertionError(
                "nonempty root attempted group normalization"
            ),
        ):
            try:
                _call(
                    "_task9_open_temp_root",
                    system_root,
                )
            except handoff._Task9RunnerFailure as exc:
                assert exc.exit_code == handoff.EXIT_COLLISION
            else:
                raise AssertionError(
                    "nonempty system temporary root was accepted"
                )
    finally:
        child.unlink()
        os.rmdir(system_root)


def test_039_existing_system_root_normalizes_before_new_epoch() -> None:
    temp_root = Path(
        "/private/tmp"
    ) / f".quant-radar-ux1b-seq5-existing-{os.getpid()}-{time.time_ns()}"
    os.mkdir(temp_root, 0o700)
    initial = os.lstat(temp_root)
    assert initial.st_uid == os.getuid()
    assert initial.st_gid == 0
    assert stat.S_IMODE(initial.st_mode) == 0o700
    temp_root_fd: int | None = None
    epoch_fd: int | None = None
    active_root_fd: int | None = None
    try:
        temp_root_fd, identity = _call(
            "_task9_open_temp_root",
            temp_root,
        )
        normalized = os.fstat(temp_root_fd)
        assert (normalized.st_dev, normalized.st_ino) == identity
        assert normalized.st_uid == os.getuid()
        assert normalized.st_gid == os.getgid()
        assert stat.S_IMODE(normalized.st_mode) == 0o700
        epoch_fd, _ = _call(
            "_task9_create_directory_at",
            temp_root_fd,
            RECOVERY_ID,
        )
        active_root_fd, active_identity = _call(
            "_task9_open_temp_root",
            temp_root,
            root_policy="active",
        )
        assert active_identity == identity
        os.mkdir("foreign", 0o700, dir_fd=temp_root_fd)
        try:
            _call(
                "_task9_open_temp_root",
                temp_root,
                root_policy="active",
            )
        except handoff._Task9RunnerFailure as exc:
            assert exc.exit_code == handoff.EXIT_COLLISION
        else:
            raise AssertionError(
                "active root accepted an unrelated entry"
            )
    finally:
        if active_root_fd is not None:
            os.close(active_root_fd)
        if epoch_fd is not None:
            os.close(epoch_fd)
        if temp_root_fd is not None:
            os.close(temp_root_fd)
        foreign_path = temp_root / "foreign"
        if foreign_path.exists() and not foreign_path.is_symlink():
            os.rmdir(foreign_path)
        epoch_path = temp_root / RECOVERY_ID
        if epoch_path.exists() and not epoch_path.is_symlink():
            os.rmdir(epoch_path)
        if temp_root.exists() and not temp_root.is_symlink():
            os.rmdir(temp_root)


def test_040_postcontrol_runner_failure_publishes_revoked_terminal() -> None:
    with _owned_workspace() as (root, workspace_fd):
        context = _task9_prerequisites(root)
        driver = _Task9FailingRunnerDriver(
            root,
            context,
            fail_stage="postcontrol",
            exit_code=handoff.EXIT_UNAVAILABLE,
        )
        result = _call(
            "_task9_transition",
            workspace_fd,
            RECOVERY_ID,
            "capture",
            driver=driver,
        )
        assert result == {
            "exitCode": handoff.EXIT_UNAVAILABLE,
            "status": "revoked",
            "launched": True,
            "published": True,
        }
        chain = _reopen_task9_chain(
            root,
            context["plans"],
            driver=driver,
        )
        assert tuple(value is not None for value in chain) == (
            True,
            False,
            False,
            False,
            True,
        )
        terminal = chain[4]
        assert terminal is not None
        assert terminal["status"] == "revoked"
        assert terminal["reason"] == (
            "control_nested_quiescence_unverified"
        )
        assert terminal["controlCheckpoint"] is None
        assert terminal["prethemeGate"] is None
        assert terminal["prethemeCheckpoint"] is None
        assert [call["stage"] for call in driver.calls] == ["postcontrol"]
        terminal_before = _path_fingerprint(
            root / TASK9_LIFECYCLE[4][0]
        )
        replay = _call(
            "_task9_transition",
            workspace_fd,
            RECOVERY_ID,
            "capture",
            driver=driver,
        )
        assert replay["exitCode"] == handoff.EXIT_EXHAUSTED
        assert replay["freshGrant"] is False
        assert replay["launched"] is False
        assert [call["stage"] for call in driver.calls] == ["postcontrol"]
        assert _path_fingerprint(
            root / TASK9_LIFECYCLE[4][0]
        ) == terminal_before


