def test_042_sequence8_chromium_path_budget_is_exact_and_preflight_bound() -> None:
    model = getattr(
        handoff,
        "_task9_chromium_path_budget_model",
        None,
    )
    validate = getattr(
        handoff,
        "_validate_task9_chromium_path_budget",
        None,
    )
    if not callable(model) or not callable(validate):
        raise handoff.ThemeHandoffNotImplemented(
            "TEST-042",
            "Sequence 8 Chromium path-budget oracle is absent",
        )

    sequence6_rows = model(
        Path("/private/tmp/quant-radar-ux1b-runtime-sequence6"),
        "20260724T110000Z",
    )
    assert tuple(row["stage"] for row in sequence6_rows) == (
        "postcontrol",
        "pretheme",
    )
    assert tuple(row["pathBytes"] for row in sequence6_rows) == (
        255,
        252,
    )
    assert tuple(row["marginBytes"] for row in sequence6_rows) == (
        -2,
        1,
    )
    assert tuple(row["passed"] for row in sequence6_rows) == (
        False,
        False,
    )

    sequence7_rows = model(
        Path("/private/tmp/qr-ux1b-s7"),
        "20260725T010000Z",
    )
    assert tuple(row["pathBytes"] for row in sequence7_rows) == (
        231,
        228,
    )
    assert tuple(row["marginBytes"] for row in sequence7_rows) == (
        22,
        25,
    )
    assert all(row["passed"] is True for row in sequence7_rows)
    sequence8_rows = model(
        Path("/private/tmp/qr-ux1b-s8"),
        "20260725T080000Z",
    )
    assert tuple(row["pathBytes"] for row in sequence8_rows) == (
        231,
        228,
    )
    assert tuple(row["marginBytes"] for row in sequence8_rows) == (
        22,
        25,
    )
    assert all(row["passed"] is True for row in sequence8_rows)
    assert validate(
        Path("/private/tmp/qr-ux1b-s8"),
        "20260725T080000Z",
    ) == sequence8_rows

    for runtime_root, recovery_id in (
        (
            Path("/private/tmp/quant-radar-ux1b-runtime-sequence6"),
            "20260724T110000Z",
        ),
        (
            Path("/private/tmp/qr-ux1b-s8"),
            "20260725T080001Z",
        ),
        (
            Path("relative-runtime"),
            "20260725T080000Z",
        ),
    ):
        _assert_rejected(
            lambda runtime_root=runtime_root, recovery_id=recovery_id: validate(
                runtime_root,
                recovery_id,
            ),
            f"path budget accepted {runtime_root} {recovery_id}",
        )

    class _PathBudgetReached(RuntimeError):
        pass

    with (
        _source_root_descriptor() as source_root_fd,
        patch.object(
            handoff,
            "_validate_task9_chromium_path_budget",
            side_effect=_PathBudgetReached,
        ) as path_budget,
    ):
        capture_stack = copy.deepcopy(
            _call(
                "_read_sequence8_preflight_history",
                source_root_fd,
            )["captureStack"]
        )
        try:
            _call(
                "_build_runtime_receipt",
                source_root_fd,
                capture_stack=capture_stack,
            )
        except _PathBudgetReached:
            pass
        else:
            raise AssertionError(
                "runtime receipt did not invoke path-budget validation"
            )
    path_budget.assert_called_once_with(
        Path("/private/tmp/qr-ux1b-s8"),
        "20260725T080000Z",
    )


def test_043_sequence8_imports_exact_sequence6_revoked_failure() -> None:
    retained = (
        SEQUENCE6_PLAN_PATH,
        SEQUENCE6_LEDGER_PATH,
        SEQUENCE6_PREFLIGHT_PATH,
        SEQUENCE6_INTENT_PATH,
        SEQUENCE6_TERMINAL_PATH,
        SEQUENCE6_FAILED_MANIFEST_PATH,
    )
    before = {
        path: (
            _sha256(path.read_bytes()),
            path.stat().st_size,
            path.stat().st_ino,
            path.stat().st_mtime_ns,
        )
        for path in retained
    }
    with _source_root_descriptor() as source_root_fd:
        package = _call(
            "_reauthenticate_authorization_package",
            source_root_fd,
        )
    required = {
        "sequence6ReplacementPlan": SEQUENCE6_PLAN_REF,
        "sequence6Traceability": SEQUENCE6_LEDGER_REF,
        "sequence6Preflight": SEQUENCE6_PREFLIGHT_REF,
        "sequence6Intent": SEQUENCE6_INTENT_REF,
        "sequence6Terminal": SEQUENCE6_TERMINAL_REF,
        "sequence6FailedPostcontrolManifest": (
            SEQUENCE6_FAILED_MANIFEST_REF
        ),
        "sequence6ControlCheckpointAbsent": True,
        "sequence6PrethemeGateAbsent": True,
        "sequence6PrethemeCheckpointAbsent": True,
        "sequence6CanonicalPrethemeManifestAbsent": True,
    }
    missing = sorted(set(required) - set(package))
    if missing:
        raise handoff.ThemeHandoffNotImplemented(
            "TEST-043",
            "Sequence 8 predecessor import is absent: "
            + ", ".join(missing),
        )
    for key, value in required.items():
        assert package[key] == value
    assert len(package["authorityRecords"]) == 33
    for path in (
        SEQUENCE6_CONTROL_PATH,
        SEQUENCE6_GATE_PATH,
        SEQUENCE6_CHECKPOINT_PATH,
        SEQUENCE6_CANONICAL_MANIFEST_PATH,
    ):
        assert not path.exists()
        assert not path.is_symlink()
    terminal = json.loads(
        SEQUENCE6_TERMINAL_PATH.read_text(encoding="utf-8")
    )
    assert terminal["status"] == "revoked"
    assert terminal["reason"] == (
        "control_nested_quiescence_unverified"
    )
    assert terminal["controlCheckpoint"] is None
    assert terminal["prethemeGate"] is None
    assert terminal["prethemeCheckpoint"] is None
    failed = json.loads(
        SEQUENCE6_FAILED_MANIFEST_PATH.read_text(encoding="utf-8")
    )
    assert failed["status"] == "failed"
    assert failed["error"] == {
        "message": (
            "UX-1B isolation contract: browser Chromium singleton "
            "path is too long"
        ),
        "type": "IsolationContractError",
    }
    assert {
        path: (
            _sha256(path.read_bytes()),
            path.stat().st_size,
            path.stat().st_ino,
            path.stat().st_mtime_ns,
        )
        for path in retained
    } == before


