@contextmanager
def _authenticated_sequence10_migration_inputs() -> Iterator[dict[str, Any]]:
    """Open the immutable migration inputs through production contracts."""

    from scripts import ui_ux_evidence as evidence

    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    workspace_fd = os.open(ROOT, flags)
    source_root_fd = os.open(ROOT, flags)
    retained_directories: list[int] = []
    try:
        expected_by_path = {
            item["path"]: item
            for item in handoff.CONTINUATION_PREDECESSOR_REFS
        }
        authenticated: dict[str, Any] = {}
        for key, relative in handoff.CONTROL_MIGRATION_INPUTS.items():
            parent, name = relative.rsplit("/", 1)
            parent_fd = os.open(
                parent,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=workspace_fd,
            )
            retained_directories.append(parent_fd)
            contract = evidence.freeze_manifest_bundle_contract(
                parent_fd,
                name,
                expected_owner=os.getuid(),
                expected_manifest_sha256=expected_by_path[relative][
                    "sha256"
                ],
            )
            authenticated[key] = evidence.reauthenticate_manifest_bundle(
                parent_fd,
                contract,
            )

        _, stack_bytes = handoff._expected_continuation_ref(
            workspace_fd,
            handoff.CONTINUATION_PREDECESSOR_REFS[-1],
        )
        stack = handoff._strict_json_bytes(stack_bytes)
        assert isinstance(stack, dict)
        catalog_value = stack["controlCatalog"]
        catalog_bytes = handoff._canonical_json_bytes(catalog_value)
        with tempfile.TemporaryDirectory(
            prefix="ux1b-sequence10-test-catalog-"
        ) as temporary:
            temporary_path = Path(temporary)
            os.chmod(temporary_path, 0o700)
            catalog_path = temporary_path / "control-catalog.json"
            _write_owned(catalog_path, catalog_bytes, 0o600)
            temporary_fd = os.open(temporary_path, flags | os.O_NOFOLLOW)
            try:
                catalog = evidence.authenticate_control_catalog(
                    temporary_fd,
                    "control-catalog.json",
                    expected_owner=os.getuid(),
                    expected_base_capture_stack_digest=stack[
                        "baseCaptureStackDigest"
                    ],
                    expected_capture_stack_digest=stack[
                        "captureStackDigest"
                    ],
                    expected_catalog_sha256=_sha256(catalog_bytes),
                )
                specifications = (
                    (
                        "beforePages",
                        "scripts/ui_ux_fixture_app.py",
                        "ux1b-full-pages",
                        "precontrol",
                    ),
                    (
                        "afterPages",
                        "scripts/ui_ux_fixture_app.py",
                        "ux1b-full-pages",
                        "pretheme",
                    ),
                    (
                        "beforeControls",
                        "scripts/ui_ux_selection_fixture_app.py",
                        "ux1b-selection-controls",
                        "precontrol",
                    ),
                    (
                        "afterControls",
                        "scripts/ui_ux_selection_fixture_app.py",
                        "ux1b-selection-controls",
                        "postcontrol",
                    ),
                )
                captures: dict[str, dict[str, dict[str, Any]]] = {}
                for label, entrypoint, mode, phase in specifications:
                    document = (
                        evidence._migration_document_from_authenticated_bundle(
                            authenticated[label],
                            fixture_entrypoint=entrypoint,
                            expected_mode=mode,
                            expected_phase=phase,
                            label=label,
                        )
                    )
                    _, parsed = evidence._migration_manifest(
                        document,
                        expected_mode=mode,
                        label=label,
                    )
                    evidence._validate_migration_profile(
                        parsed,
                        fixture_entrypoint=entrypoint,
                        label=label,
                    )
                    captures[label] = parsed
                yield {
                    "authenticated": authenticated,
                    "captures": captures,
                    "catalog": catalog,
                    "catalogValue": catalog_value,
                    "evidence": evidence,
                    "workspaceFd": workspace_fd,
                    "sourceRootFd": source_root_fd,
                }
            finally:
                os.close(temporary_fd)
    finally:
        for descriptor in retained_directories:
            os.close(descriptor)
        os.close(source_root_fd)
        os.close(workspace_fd)


def _sequence10_semantic_plane(
    fixture: Mapping[str, Any],
) -> tuple[
    list[dict[str, Any]],
    list[tuple[dict[str, Any], dict[str, Any], Sequence[dict[str, str]]]],
]:
    evidence = fixture["evidence"]
    captures = fixture["captures"]
    catalog = fixture["catalogValue"]
    rows: list[dict[str, Any]] = []
    pairs: list[
        tuple[
            dict[str, Any],
            dict[str, Any],
            Sequence[dict[str, str]],
        ]
    ] = []
    for before_label, after_label, section_name in (
        ("beforePages", "afterPages", "fullPageCases"),
        ("beforeControls", "afterControls", "focusedCases"),
    ):
        section = catalog[section_name]
        for capture_id in sorted(captures[before_label]):
            before = captures[before_label][capture_id]
            after = captures[after_label][capture_id]
            if before["case"] not in section:
                continue
            roots = evidence._catalog_roots_for_case(
                section,
                before["case"],
                label=section_name,
            )
            (
                canonical_before,
                canonical_after,
                _,
                _,
                semantic_rows,
            ) = handoff._canonicalize_migration_geometry(
                evidence,
                before,
                after,
                roots,
                section_name=section_name,
                capture_id=capture_id,
            )
            rows.extend(semantic_rows)
            pairs.append((canonical_before, canonical_after, roots))
    return rows, pairs


