def test_081_stored_descriptor_budget_is_context_independent() -> None:
    _require_sequence10(
        "TEST-081",
        "_validate_stored_descriptor_budget",
        "_import_sequence9_historical_preflight",
    )
    stored_path = ROOT / handoff.CONTINUATION_PREFLIGHT_PATH
    stored = json.loads(stored_path.read_bytes())["descriptorBudget"]
    assert stored == {
        "baselineMaxFd": 6,
        "baselineOpenCount": 7,
        "hardLimit": resource.getrlimit(resource.RLIMIT_NOFILE)[1],
        "peakOpenCount": 259,
        "protocolAdditional": 252,
        "requiredSoft": 259,
        "reserve": 64,
        "softApplied": 259,
    }
    retained: list[int] = []
    try:
        for count in (0, 2, 8):
            while len(retained) < count:
                read_fd, write_fd = os.pipe()
                retained.extend((read_fd, write_fd))
            assert handoff._validate_stored_descriptor_budget(stored) == stored
            with _source_root_descriptor() as source_root_fd:
                workspace_fd = os.dup(source_root_fd)
                try:
                    imported = handoff._import_sequence9_historical_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                finally:
                    os.close(workspace_fd)
            assert imported["preflightValue"]["descriptorBudget"] == stored
    finally:
        for descriptor in retained:
            os.close(descriptor)
    for key, value in (
        ("baselineOpenCount", 8),
        ("requiredSoft", 260),
        ("reserve", 63),
    ):
        changed = copy.deepcopy(stored)
        changed[key] = value
        _assert_rejected(
            lambda changed=changed: handoff._validate_stored_descriptor_budget(changed),
            f"stored descriptor budget {key}",
        )


def test_082_runtime_descriptor_budget_restores_limits() -> None:
    _require_sequence10(
        "TEST-082",
        "_build_descriptor_profile",
        "_runtime_descriptor_budget",
    )
    original = resource.getrlimit(resource.RLIMIT_NOFILE)
    profile = handoff._build_descriptor_profile()
    assert profile == {
        "hardLimit": original[1],
        "maxPathDepth": 12,
        "protocolAdditional": 252,
        "raiseCeiling": 1_536,
        "reserve": 64,
        "schemaVersion": "quant-radar-ui-ux-descriptor-profile/v1",
        "worstCaseUniqueRetainedLeaves": 164,
    }
    with handoff._runtime_descriptor_budget(profile) as budget:
        assert budget["softApplied"] >= budget["requiredSoft"]
    assert resource.getrlimit(resource.RLIMIT_NOFILE) == original
    try:
        with handoff._runtime_descriptor_budget(profile):
            raise RuntimeError("sentinel")
    except RuntimeError as exc:
        assert str(exc) == "sentinel"
    assert resource.getrlimit(resource.RLIMIT_NOFILE) == original


