def test_084_comparator_is_correction_bound_in_the_real_registry() -> None:
    _require_sequence10(
        "TEST-084",
        "_validate_correction_public_args",
        "_reauthenticate_correction_preflight",
    )
    parser = handoff._build_public_parser()
    parsed = parser.parse_args(
        (
            "compare-control-migration",
            "--capture-recovery-id", RECOVERY_ID,
            "--continuation-id", handoff.CONTINUATION_ID,
            "--correction-id", handoff.CORRECTION_ID,
            "--json",
        )
    )
    assert parsed.correction_id == handoff.CORRECTION_ID
    registry = handoff._production_public_handlers()
    assert registry["compare-control-migration"] is handoff._handle_compare_control_migration
    try:
        parser.parse_args(
            (
                "compare-control-migration",
                "--capture-recovery-id", RECOVERY_ID,
                "--continuation-id", handoff.CONTINUATION_ID,
                "--correction-id", handoff.CORRECTION_ID,
                "--artifact-path", "/tmp/injected",
                "--json",
            )
        )
    except SystemExit as exc:
        assert exc.code == 2
    else:
        raise AssertionError("comparator accepted a caller artifact path")
    fixture_parent = ROOT / ".claude/ui_snapshots/ux1b"
    with tempfile.TemporaryDirectory(
        prefix=".sequence10-production-canary-",
        dir=fixture_parent,
    ) as raw:
        fixture_root = Path(raw)
        fixture_relative = fixture_root.relative_to(ROOT).as_posix()
        forward_paths = (
            f"{fixture_relative}/control-migration.json",
            f"{fixture_relative}/control-migration-review-packet.json",
            f"{fixture_relative}/review-intake.json",
            f"{fixture_relative}/control-migration-manual-review.json",
            f"{fixture_relative}/theme-handoff-candidate.json",
            f"{fixture_relative}/theme-contract.json",
        )
        lease_relative = f"{fixture_relative}/correction.lease"
        preflight_relative = f"{fixture_relative}/correction-preflight.json"
        lease_path = ROOT / lease_relative
        _write_owned(lease_path, b"", 0o600)
        tier_destinations = (
            handoff.CORRECTION_TIER_DESTINATIONS[0],
            lease_relative,
            *handoff.CORRECTION_TIER_DESTINATIONS[2:8],
            preflight_relative,
        )
        flags = (
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0)
        )
        with (
            patch.object(
                handoff,
                "CONTINUATION_FORWARD_PATHS",
                forward_paths,
            ),
            patch.object(
                handoff,
                "CORRECTION_TIER_DESTINATIONS",
                tier_destinations,
            ),
            patch.object(
                handoff,
                "CORRECTION_PREFLIGHT_PATH",
                preflight_relative,
            ),
            patch.object(
                handoff,
                "_require_frozen_migration_evidence",
                return_value=copy.deepcopy(
                    handoff.MIGRATION_GEOMETRY_EVIDENCE_REF
                ),
            ),
        ):
            workspace_fd = os.open(ROOT, flags)
            source_root_fd = os.open(ROOT, flags)
            try:
                lease_record, lease_bytes = (
                    handoff._relative_regular_record_and_bytes(
                        workspace_fd,
                        lease_relative,
                    )
                )
                assert lease_bytes == b""
                preflight = handoff._build_correction_preflight_value(
                    workspace_fd,
                    source_root_fd,
                    lease_record,
                )
            finally:
                os.close(source_root_fd)
                os.close(workspace_fd)
            _write_owned(
                ROOT / preflight_relative,
                handoff._canonical_json_bytes(preflight),
                0o600,
            )
            result = handoff._execute_public_command(parsed)
            assert result["exitCode"] == handoff.EXIT_SUCCESS
            assert result["kind"] == "compare-control-migration"
            assert result["path"] == forward_paths[0]
            report = json.loads((ROOT / forward_paths[0]).read_bytes())
            assert report["status"] == "passed"
            assert report["comparedCaptures"] == 117


