def test_088_runtime_failures_preserve_public_exit_codes() -> None:
    _require_sequence10("TEST-088", "_run_correction_descriptor_command")
    cases = (
        (BlockingIOError(), handoff.EXIT_BUSY),
        (handoff.NamespaceCollision("collision"), handoff.EXIT_COLLISION),
        (handoff.PrimitiveUnavailable("unavailable"), handoff.EXIT_UNAVAILABLE),
        (OSError(errno.EMFILE, "unavailable"), handoff.EXIT_UNAVAILABLE),
    )
    for error, expected in cases:
        def operation(_: int, __: int, error: BaseException = error) -> dict[str, Any]:
            raise error
        assert handoff._run_correction_descriptor_command(operation) == {
            "exitCode": expected
        }


