def test_091_frozen_migration_evidence_and_primitives_are_authenticated() -> None:
    _require_sequence10(
        "TEST-091",
        "MIGRATION_GEOMETRY_EVIDENCE_REF",
        "_require_sequence12_migration_evidence",
    )
    from scripts import ui_ux_evidence as evidence

    assert handoff.MIGRATION_GEOMETRY_EVIDENCE_REF["sha256"] == (
        "3ae2a02b519a70f4e8ef146c486f0ad4cd306718ad5429ec20dd8ccf951f009a"
    )
    with _source_root_descriptor() as source_root_fd:
        assert handoff._require_sequence12_migration_evidence(
            source_root_fd,
            evidence,
            handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF,
        ) == handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF
        _assert_rejected(
            lambda: handoff._require_sequence12_migration_evidence(
                source_root_fd,
                evidence,
                handoff.SEQUENCE12_MIGRATION_EVIDENCE_REF,
            ),
            "historical Sequence 12 evidence used as live source",
        )
        attacked_ref = {
            **handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF,
            "sha256": "0" * 64,
        }
        _assert_rejected(
            lambda: handoff._require_sequence12_migration_evidence(
                source_root_fd,
                evidence,
                attacked_ref,
            ),
            "mutated Sequence 12 evidence digest",
        )
        with patch.object(
            evidence,
            "_compare_capture_migration",
            lambda *_: None,
        ):
            _assert_rejected(
                lambda: handoff._require_sequence12_migration_evidence(
                    source_root_fd,
                    evidence,
                    handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF,
                ),
                "substituted current migration primitive",
            )


