def test_099_sequence11_reauthentication_separates_initial_and_current_state() -> None:
    _require_sequence11(
        "TEST-099",
        "_reauthenticate_lifecycle_correction_preflight",
        "_validate_current_forward_semantics",
    )
    with _sequence11_workspace_fixture() as fixture:
        _sequence11_bootstrap_and_preflight(fixture)
        preflight_path = ROOT / fixture["tierDestinations"][-1]
        frozen = preflight_path.read_bytes()
        packet = _sequence11_expected_packet(fixture)
        _write_owned(
            ROOT / fixture["forwardPaths"][1],
            handoff._canonical_json_bytes(packet),
            0o600,
        )
        _, value, current = (
            handoff._reauthenticate_lifecycle_correction_preflight(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )
        )
        assert current["state"] == "F1_PACKET"
        assert value["initialForwardState"] == fixture["initialState"]
        assert preflight_path.read_bytes() == frozen
        _assert_rejected(
            lambda: (
                handoff._build_lifecycle_correction_source_projections(
                    fixture["sourceRootFd"]
                )
            ),
            "current Sequence 11 source drift",
        )
        original = handoff._import_later_source_projections_history

        def drifted(
            source_root_fd: int,
            sequence: str,
        ) -> dict[str, Any]:
            result = original(source_root_fd, sequence)
            result["sourceProjection"] = copy.deepcopy(
                result["sourceProjection"]
            )
            result["sourceProjection"]["digest"] = "0" * 64
            return result

        with patch.object(
            handoff,
            "_import_later_source_projections_history",
            drifted,
        ):
            _assert_rejected(
                lambda: handoff._reauthenticate_lifecycle_correction_preflight(
                    fixture["workspaceFd"],
                    fixture["sourceRootFd"],
                ),
                "current Sequence 11 source drift",
            )


def test_100_sequence11_forward_prefix_truth_table_is_closed() -> None:
    _require_sequence11(
        "TEST-100",
        "FORWARD_PREFIX_STATES",
        "_classify_current_forward_prefix",
    )
    with tempfile.TemporaryDirectory(
        prefix="sequence11-prefix-",
        dir=ROOT / ".claude/ui_snapshots/ux1b",
    ) as raw:
        root = Path(raw)
        paths = tuple(f"leaf-{index}.json" for index in range(6))
        workspace_fd = os.open(
            root,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            with patch.object(
                handoff,
                "CONTINUATION_FORWARD_PATHS",
                paths,
            ):
                valid = 0
                for mask in range(64):
                    for item in paths:
                        try:
                            os.unlink(root / item)
                        except FileNotFoundError:
                            pass
                    for index, item in enumerate(paths):
                        if mask & (1 << index):
                            _write_owned(
                                root / item,
                                handoff._canonical_json_bytes(
                                    {"index": index}
                                ),
                                0o600,
                            )
                    expected_count = 0
                    while (
                        expected_count < 6
                        and mask & (1 << expected_count)
                    ):
                        expected_count += 1
                    is_prefix = (
                        expected_count > 0
                        and mask == (1 << expected_count) - 1
                    )
                    if is_prefix:
                        classified = (
                            handoff._classify_current_forward_prefix(
                                workspace_fd
                            )
                        )
                        assert classified["state"] == (
                            handoff.FORWARD_PREFIX_STATES[
                                expected_count - 1
                            ]
                        )
                        valid += 1
                    else:
                        _assert_rejected(
                            lambda: handoff._classify_current_forward_prefix(
                                workspace_fd
                            ),
                            f"non-prefix mask {mask}",
                        )
                assert valid == 6
                for item in paths:
                    try:
                        os.unlink(root / item)
                    except FileNotFoundError:
                        pass
                _write_owned(
                    root / paths[0],
                    b'{ "index":0}',
                    0o600,
                )
                _assert_rejected(
                    lambda: handoff._classify_current_forward_prefix(
                        workspace_fd
                    ),
                    "noncanonical forward JSON",
                )
                os.unlink(root / paths[0])
                _write_owned(
                    root / paths[0],
                    handoff._canonical_json_bytes({"index": 0}),
                    0o644,
                )
                _assert_rejected(
                    lambda: handoff._classify_current_forward_prefix(
                        workspace_fd
                    ),
                    "permissive forward mode",
                )
        finally:
            os.close(workspace_fd)
    with _sequence11_workspace_fixture() as fixture:
        _sequence11_bootstrap_and_preflight(fixture)
        _write_owned(
            ROOT / fixture["forwardPaths"][1],
            handoff._canonical_json_bytes({"semantic": "false"}),
            0o600,
        )
        _assert_rejected(
            lambda: handoff._reauthenticate_lifecycle_correction_preflight(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            ),
            "canonical but semantically false packet",
        )


