def test_102_sequence11_external_review_decision_is_preserved() -> None:
    _require_sequence11(
        "TEST-102",
        "_publish_review_from_external_intake",
        "_handle_publish_review",
    )
    for decision in ("accepted", "rejected"):
        with _sequence11_workspace_fixture() as fixture:
            _sequence11_bootstrap_and_preflight(fixture)
            handoff._prepare_control_migration_review(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )
            packet = json.loads(
                (ROOT / fixture["forwardPaths"][1]).read_bytes()
            )
            review = _sequence11_review(
                packet,
                fixture["forwardPaths"][1],
                decision,
            )
            _write_owned(
                ROOT / fixture["forwardPaths"][2],
                handoff._canonical_json_bytes(review),
                0o600,
            )

            original_review_paths = handoff._review_paths

            def review_paths(
                kind: str,
                root_sha256: str | None,
                lineage_id: str,
            ) -> tuple[str, str, str]:
                if kind == "control-migration":
                    return fixture["forwardPaths"][1:4]
                return original_review_paths(
                    kind,
                    root_sha256,
                    lineage_id,
                )

            parser = handoff._build_public_parser()
            args = parser.parse_args(
                (
                    "publish-review",
                    "--kind", "control-migration",
                    "--recovery-id", RECOVERY_ID,
                    "--continuation-id", handoff.CONTINUATION_ID,
                    "--correction-id", handoff.CORRECTION_ID,
                    "--lifecycle-correction-id",
                    handoff.LIFECYCLE_CORRECTION_ID,
                    "--json",
                )
            )
            with patch.object(
                handoff,
                "_review_paths",
                review_paths,
            ):
                result = handoff._execute_public_command(args)
            assert result["status"] == decision
            assert (
                ROOT / fixture["forwardPaths"][3]
            ).read_bytes() == handoff._canonical_json_bytes(review)
            if decision == "rejected":
                _assert_rejected(
                    lambda: handoff._prepare_handoff_candidate_transition(
                        fixture["workspaceFd"],
                        fixture["sourceRootFd"],
                    ),
                    "rejected review candidate refusal",
                )
                assert not os.path.lexists(
                    ROOT / fixture["forwardPaths"][4]
                )


