def test_105_sequence11_compatibility_and_scope_remain_closed() -> None:
    _require_sequence11(
        "TEST-105",
        "LIFECYCLE_CORRECTION_PLAN_REF",
        "LIFECYCLE_CORRECTION_LEDGER_REF",
    )
    for expected in (
        handoff.LIFECYCLE_CORRECTION_PLAN_REF,
        handoff.LIFECYCLE_CORRECTION_LEDGER_REF,
    ):
        path = ROOT / expected["path"]
        assert _sha256(path.read_bytes()) == expected["sha256"]
        assert path.stat().st_size == expected["size"]
    ledger = json.loads(
        (ROOT / handoff.LIFECYCLE_CORRECTION_LEDGER_REF["path"]).read_bytes()
    )
    assert ledger["coverageBasisPoints"] == 10_000
    assert ledger["gaps"] == [] and ledger["orphans"] == []
    assert len(ledger["requirements"]) == 6
    assert len(ledger["acceptance"]) == 8
    assert len(ledger["implementation"]) == 9
    assert len(ledger["tests"]) == 10
    evidence = ROOT / handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF["path"]
    assert _sha256(evidence.read_bytes()) == (
        handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF["sha256"]
    )
    assert evidence.stat().st_size == (
        handoff.SEQUENCE13_MIGRATION_EVIDENCE_REF["size"]
    )
    for relative in (
        "scripts/ui_ux_theme_handoff.py",
        "scripts/test_ui_ux_theme_handoff.py",
    ):
        source = (ROOT / relative).read_text(encoding="utf-8")
        ast.parse(source, filename=relative, feature_version=(3, 10))


def test_106_sequence12_root_review_packet_is_exact_81_44_125() -> None:
    from scripts import ui_ux_evidence

    items: list[dict[str, Any]] = []
    for index in range(81):
        before = _artifact(
            f"historical/pages/before/{index:03d}.png",
            "a",
            index + 1,
        )
        after = _artifact(
            f"historical/pages/after/{index:03d}.png",
            "b" if index % 5 == 0 else "a",
            index + 1,
        )
        items.append(
            {
                "kind": "page",
                "id": f"page-{index:03d}",
                "before": before,
                "after": after,
                "dimensions": {"width": 1_440, "height": 900},
                "changed": before["sha256"] != after["sha256"],
            }
        )
    historical_by_logical: dict[str, dict[str, Any]] = {}
    for index, row in enumerate(
        ui_ux_evidence.root_capture_expansion_rows()
    ):
        logical_id = row["logicalCaptureId"]
        before = historical_by_logical.setdefault(
            logical_id,
            _artifact(
                f"historical/controls/{logical_id}.png",
                "c",
                index + 100,
            ),
        )
        after = _artifact(
            f"sequence12/controls/{row['rootCaptureId']}.png",
            "d",
            index + 200,
        )
        items.append(
            {
                "kind": "control-root",
                "id": row["rootCaptureId"],
                "logicalCaptureId": logical_id,
                "rootCaptureId": row["rootCaptureId"],
                "rootOrdinal": row["rootOrdinal"],
                "rootSelector": row["rootSelector"],
                "before": copy.deepcopy(before),
                "after": after,
                "afterSidecar": _artifact(
                    (
                        "sequence12/controls/"
                        f"{row['rootCaptureId']}.render.json"
                    ),
                    "e",
                    index + 300,
                ),
                "dimensions": {
                    "width": row["viewport"]["width"],
                    "height": row["viewport"]["height"],
                },
                "changed": before["sha256"] != after["sha256"],
            }
        )
    inputs = [
        _artifact(
            f"sequence12/review-input-{index}.json",
            format(index + 1, "x"),
            index + 1,
        )
        for index in range(5)
    ]
    packet = handoff._build_root_migration_review_packet(
        lineage_id=RECOVERY_ID,
        machine_report=inputs[-1],
        inputs=inputs,
        items=items,
    )
    handoff._validate_review_packet_value(packet)
    assert packet["schemaVersion"] == (
        "quant-radar-ui-ux-review-packet/v2"
    )
    assert len(packet["items"]) == 125
    assert sum(
        item["kind"] == "page" for item in packet["items"]
    ) == 81
    assert sum(
        item["kind"] == "control-root"
        for item in packet["items"]
    ) == 44
    stack_value = json.loads(
        (
            ROOT
            / "docs/ui-ux/"
            "quant-radar-ui-v2-ux1b-capture-stack.json"
        ).read_bytes()
    )
    historical_catalog_value = copy.deepcopy(
        stack_value["controlCatalog"]
    )
    corrected_catalog_value = copy.deepcopy(
        historical_catalog_value
    )
    corrected_catalog_value["baseCaptureStackDigest"] = "f" * 64
    corrected_catalog_value["captureStackDigest"] = (
        ui_ux_evidence.control_catalog_digest(
            corrected_catalog_value
        )
    )
    historical_catalog = ui_ux_evidence._mint_control_catalog(
        historical_catalog_value
    )
    corrected_catalog = ui_ux_evidence._mint_control_catalog(
        corrected_catalog_value
    )
    root_audit_rows = [
        {
            "logicalCaptureId": row["logicalCaptureId"],
            "rootCaptureId": row["rootCaptureId"],
            "rootOrdinal": row["rootOrdinal"],
            "rootSelector": row["rootSelector"],
            "viewport": copy.deepcopy(row["viewport"]),
            "png": {
                "path": f"{row['rootCaptureId']}.png",
                "sha256": "a" * 64,
                "size": index + 1,
                "width": row["viewport"]["width"],
                "height": row["viewport"]["height"],
            },
            "renderSidecar": {
                "path": f"{row['rootCaptureId']}.render.json",
                "sha256": "b" * 64,
                "size": index + 101,
                "schemaVersion": ui_ux_evidence.RENDER_V2_SCHEMA,
            },
            "caseSemanticProjectionSha256": "c" * 64,
            "prePostExact": True,
        }
        for index, row in enumerate(
            ui_ux_evidence.root_capture_expansion_rows()
        )
    ]
    root_audit = {
        "status": "passed",
        "correctedCaptureStackDigest": (
            corrected_catalog_value["captureStackDigest"]
        ),
        "sourceDigest": "d" * 64,
        "logicalCaptureCount": 36,
        "rootCaptureCount": 44,
        "logicalCounterClaims": 36,
        "rootExpansion": {
            "rows": 44,
            "size": ui_ux_evidence.ROOT_CAPTURE_EXPANSION_SIZE,
            "sha256": (
                ui_ux_evidence.ROOT_CAPTURE_EXPANSION_SHA256
            ),
        },
        "passedRootCaptures": 44,
        "unboundRootCaptures": 0,
        "exactPrePostProjections": 88,
        "roots": root_audit_rows,
    }
    legacy_report = {
        "status": "passed",
        "kind": "control-migration",
        "comparedCaptures": 117,
        "captureStackDigest": (
            historical_catalog_value["captureStackDigest"]
        ),
        "allowedBoundaryTranslations": [],
        "migrationGeometryContract": {
            "schemaVersion": (
                "quant-radar-ui-ux-migration-geometry-contract/v1"
            ),
            "actualGeometryAudit": "passed",
        },
    }
    root_report = handoff._build_control_migration_root_report(
        ui_ux_evidence,
        legacy_report=legacy_report,
        root_audit=root_audit,
        historical_catalog=historical_catalog,
        corrected_catalog=corrected_catalog,
        source_transition={
            "historicalBefore": "e" * 64,
            "historicalAcceptedAfter": "e" * 64,
            "corrected": "d" * 64,
        },
        excluded_artifact=_artifact(
            "sequence11/rejected-after-controls/manifest.json",
            "f",
            100,
        ),
    )
    assert set(root_report) == {
        "schemaVersion",
        "status",
        "kind",
        "coveredProfiles",
        "comparedCaptures",
        "pageComparisons",
        "controlRootComparisons",
        "captureStackTransition",
        "sourceTransition",
        "rootExpansion",
        "allowedBoundaryTranslations",
        "migrationGeometryContract",
        "legacySemanticOracle",
        "screenshotBindingAudit",
        "excludedArtifacts",
    }
    assert root_report["comparedCaptures"] == 125
    assert root_report["legacySemanticOracle"][
        "comparedCaptures"
    ] == 117

    attacks: list[
        tuple[str, Callable[[dict[str, Any]], None]]
    ] = [
        (
            "v1 schema with root items",
            lambda value: value.__setitem__(
                "schemaVersion",
                "quant-radar-ui-ux-review-packet/v1",
            ),
        ),
        (
            "wrong root ordinal",
            lambda value: value["items"][81].__setitem__(
                "rootOrdinal",
                9,
            ),
        ),
        (
            "reused corrected PNG",
            lambda value: value["items"][82].__setitem__(
                "after",
                copy.deepcopy(value["items"][81]["after"]),
            ),
        ),
        (
            "missing root item",
            lambda value: value["items"].pop(),
        ),
    ]
    for label, mutate in attacks:
        candidate = copy.deepcopy(packet)
        mutate(candidate)
        _assert_rejected(
            lambda candidate=candidate: (
                handoff._validate_review_packet_value(candidate)
            ),
            label,
        )


def _mint_sequence12_root_adapter_fixture(
    fixture: Mapping[str, Any],
) -> tuple[Any, Any]:
    evidence = fixture["evidence"]
    catalog_value = copy.deepcopy(fixture["catalogValue"])
    catalog_value["baseCaptureStackDigest"] = "0" * 64
    catalog_value["captureStackDigest"] = (
        evidence.control_catalog_digest(catalog_value)
    )
    corrected_catalog = evidence._mint_control_catalog(catalog_value)
    after_payload = evidence._registered_manifest_bundle(
        fixture["authenticated"]["afterControls"]
    )
    old_sidecars = {
        row["id"]: row["renderDocument"]
        for row in after_payload["captures"]
    }
    parsed = fixture["captures"]["afterControls"]
    root_rows: list[dict[str, Any]] = []
    for index, expansion in enumerate(
        evidence.root_capture_expansion_rows()
    ):
        logical_id = expansion["logicalCaptureId"]
        capture = parsed[logical_id]
        old_sidecar = old_sidecars[logical_id]
        selected_control = next(
            copy.deepcopy(control)
            for control in capture["controlEvidence"]["controls"]
            if control["rootSelector"]
            == expansion["rootSelector"]
        )
        viewport = copy.deepcopy(capture["viewport"])
        observed_root_rect = selected_control["layout"]["rootRect"]
        root_x = math.floor(observed_root_rect["x"])
        root_y = math.floor(observed_root_rect["y"])
        root_rect = {
            "x": root_x,
            "y": root_y,
            "width": (
                math.ceil(
                    observed_root_rect["x"]
                    + observed_root_rect["width"]
                )
                - root_x
            ),
            "height": (
                math.ceil(
                    observed_root_rect["y"]
                    + observed_root_rect["height"]
                )
                - root_y
            ),
        }
        selected_control["layout"]["rootRect"] = copy.deepcopy(
            root_rect
        )
        outer_nodes = copy.deepcopy(capture["nodes"])
        for node in outer_nodes:
            if node["rootSelector"] == expansion["rootSelector"]:
                node["bounds"] = copy.deepcopy(root_rect)
        focused_v3 = {
            "schemaVersion": (
                evidence.FOCUSED_CONTROL_EVIDENCE_V3_SCHEMA
            ),
            "case": capture["case"],
            "projection": "accessible-required",
            "controls": [selected_control],
            "screenshotBinding": {
                "schemaVersion": (
                    evidence.FOCUSED_SCREENSHOT_BINDING_SCHEMA
                ),
                "mode": "viewport",
                "viewport": {
                    "width": viewport["width"],
                    "height": viewport["height"],
                },
                "roots": [
                    {
                        "rootSelector": expansion["rootSelector"],
                        "rect": root_rect,
                    }
                ],
                "scrollEntries": [
                    {
                        "rootSelector": expansion["rootSelector"],
                        "chainIndex": 0,
                        "left": 0,
                        "top": 0,
                        "clientWidth": viewport["width"],
                        "clientHeight": viewport["height"],
                        "scrollWidth": viewport["width"],
                        "scrollHeight": viewport["height"],
                    }
                ],
                "prePostExact": True,
            },
        }
        semantic = {
            "schemaVersion": (
                evidence.CASE_SEMANTIC_PROJECTION_SCHEMA
            ),
            "identity": {
                "fixtureEntrypoint": (
                    "scripts/ui_ux_selection_fixture_app.py"
                ),
                "logicalCaptureId": logical_id,
                "case": capture["case"],
                "route": capture["identity"]["route"],
                "callable": capture["identity"]["callable"],
                "viewport": viewport,
            },
            "readiness": copy.deepcopy(old_sidecar["readiness"]),
            "nodes": copy.deepcopy(capture["nodes"]),
            "stableState": copy.deepcopy(capture["stableState"]),
            "providerCounters": copy.deepcopy(
                capture["providerCounters"]
            ),
            "mutatorCounters": copy.deepcopy(
                capture["mutatorCounters"]
            ),
            "runtimeProjection": copy.deepcopy(
                old_sidecar["runtimeProjection"]
            ),
            "counterProvenance": copy.deepcopy(
                old_sidecar["counterProvenance"]
            ),
            "controlEvidence": copy.deepcopy(
                capture["controlEvidence"]
            ),
        }
        render_document = {
            "schemaVersion": evidence.RENDER_V2_SCHEMA,
            "identity": {
                "case": capture["case"],
                "route": capture["identity"]["route"],
                "callable": capture["identity"]["callable"],
            },
            "viewport": viewport,
            "readiness": copy.deepcopy(old_sidecar["readiness"]),
            "nodes": outer_nodes,
            "stableState": copy.deepcopy(capture["stableState"]),
            "providerCounters": copy.deepcopy(
                capture["providerCounters"]
            ),
            "mutatorCounters": copy.deepcopy(
                capture["mutatorCounters"]
            ),
            "runtimeProjection": copy.deepcopy(
                old_sidecar["runtimeProjection"]
            ),
            "counterProvenance": copy.deepcopy(
                old_sidecar["counterProvenance"]
            ),
            "rootCapture": {
                "logicalCaptureId": logical_id,
                "rootCaptureId": expansion["rootCaptureId"],
                "rootOrdinal": expansion["rootOrdinal"],
                "rootSelector": expansion["rootSelector"],
                "rootExpansionSha256": (
                    evidence.ROOT_CAPTURE_EXPANSION_SHA256
                ),
            },
            "controlEvidence": focused_v3,
            "caseSemanticProjection": semantic,
        }
        artifacts = {
            "png": {
                "path": f"captures/{expansion['rootCaptureId']}.png",
                "sha256": hashlib.sha256(
                    f"png-{index}".encode()
                ).hexdigest(),
                "size": index + 1,
                "width": viewport["width"],
                "height": viewport["height"],
            },
            "renderSidecar": {
                "path": (
                    f"captures/{expansion['rootCaptureId']}.render.json"
                ),
                "sha256": hashlib.sha256(
                    f"render-{index}".encode()
                ).hexdigest(),
                "size": index + 101,
                "schemaVersion": evidence.RENDER_V2_SCHEMA,
            },
        }
        root_rows.append(
            {
                "id": expansion["rootCaptureId"],
                "status": "passed",
                "artifacts": artifacts,
                "renderDocument": render_document,
            }
        )
    source_digest = after_payload["manifest"][
        "sourceDigestStart"
    ]
    manifest = {
        "schemaVersion": evidence.EVIDENCE_SCHEMA,
        "status": "passed",
        "mode": "ux1b-selection-controls",
        "phase": "postcontrol",
        "runId": "sequence12-root-adapter-test",
        "fixtureEntrypoint": (
            "scripts/ui_ux_selection_fixture_app.py"
        ),
        "captureStackDigest": catalog_value[
            "captureStackDigest"
        ],
        "sourceDigestStart": source_digest,
        "sourceDigestEnd": source_digest,
        "expectedCaptureCount": 44,
        "plannedLogicalRequests": 36,
        "plannedRootCaptures": 44,
        "completedLogicalRequests": 36,
        "completedRootCaptures": 44,
        "capturedCount": 44,
        "rootExpansionSha256": (
            evidence.ROOT_CAPTURE_EXPANSION_SHA256
        ),
        "captures": [
            {
                "id": row["id"],
                "status": "passed",
                "artifacts": copy.deepcopy(row["artifacts"]),
            }
            for row in root_rows
        ],
    }
    manifest_raw = handoff._canonical_json_bytes(manifest)
    bundle = evidence.AuthenticatedManifestBundle(
        manifest=manifest,
        manifest_sha256=_sha256(manifest_raw),
        captures=root_rows,
        _key=evidence._OPAQUE_KEY,
    )
    payload = {
        "manifest": copy.deepcopy(manifest),
        "manifestSha256": bundle.manifest_sha256,
        "captures": copy.deepcopy(root_rows),
    }
    evidence._AUTHENTICATED_MANIFEST_BUNDLES[id(bundle)] = (
        bundle,
        payload,
        _sha256(handoff._canonical_json_bytes(payload)),
    )
    return bundle, corrected_catalog


def test_107_sequence12_root_comparator_preserves_117_oracle() -> None:
    with _authenticated_sequence10_migration_inputs() as fixture:
        evidence = fixture["evidence"]
        root_bundle, corrected_catalog = (
            _mint_sequence12_root_adapter_fixture(fixture)
        )
        evidence_path = ROOT / "scripts/ui_ux_evidence.py"
        evidence_bytes = evidence_path.read_bytes()
        report = (
            handoff._compare_control_migration_root_geometry_contract(
                evidence,
                source_root_fd=fixture["sourceRootFd"],
                evidence_ref={
                    "path": "scripts/ui_ux_evidence.py",
                    "sha256": _sha256(evidence_bytes),
                    "size": len(evidence_bytes),
                    "mode": (
                        f"{stat.S_IMODE(evidence_path.stat().st_mode):04o}"
                    ),
                },
                before_pages=fixture["authenticated"]["beforePages"],
                after_pages=fixture["authenticated"]["afterPages"],
                before_controls=(
                    fixture["authenticated"]["beforeControls"]
                ),
                after_root_controls=root_bundle,
                historical_catalog=fixture["catalog"],
                corrected_catalog=corrected_catalog,
                excluded_artifact=_artifact(
                    "sequence11/rejected/manifest.json",
                    "f",
                    10,
                ),
            )
        )
        assert report["comparedCaptures"] == 125
        assert report["pageComparisons"] == 81
        assert report["controlRootComparisons"] == 44
        assert report["legacySemanticOracle"] == {
            **report["legacySemanticOracle"],
            "comparedCaptures": 117,
            "pageComparisons": 81,
            "controlComparisons": 36,
        }
        assert report["screenshotBindingAudit"] == {
            "passedRootCaptures": 44,
            "unboundRootCaptures": 0,
            "exactPrePostProjections": 88,
        }


def test_120_sequence12_authority_body_and_cardinalities_are_closed() -> None:
    body = handoff._capture_binding_authorization_body()
    assert body["schemaVersion"] == (
        "quant-radar-ui-ux-formal-handoff-"
        "capture-binding-correction-authorization/v1"
    )
    assert (
        body["correctionId"],
        body["tierId"],
        body["captureId"],
    ) == (
        "20260728T000000Z",
        "20260728T001000Z",
        "20260728T010000Z",
    )
    assert body["parentPlan"] == handoff.CAPTURE_BINDING_PLAN_REF
    assert body["amendment"] == handoff.MULTI_ROOT_AMENDMENT_REF
    assert body["captureStack"] == handoff.SEQUENCE12_CAPTURE_STACK_REF
    assert (
        "scripts/test_ui_accessible_selection_controls.py"
        in handoff.CAPTURE_BINDING_PACKAGE_PATHS
    )
    assert body["rootExpansion"] == {
        "rows": 44,
        "size": 16_576,
        "sha256": (
            "13c0d601a5587cb2e05acda7d40209b4"
            "f3dc8f1d77c7bb619243eeebd241d2ca"
        ),
    }
    assert body["cardinalities"] == {
        "logicalRequests": 36,
        "rootCaptures": 44,
        "artifactLeaves": 88,
        "manifestLeaves": 89,
        "pageComparisons": 81,
        "controlRootComparisons": 44,
        "reviewItems": 125,
        "legacySemanticComparisons": 117,
    }
    assert body["formalPause"] == "R3_PACKET"
    assert body["allowedCommands"] == list(
        handoff.CAPTURE_BINDING_ALLOWED_COMMANDS
    )


def test_121_sequence12_runtime_is_distinct_and_reauthenticated() -> None:
    assert handoff._AUTHORIZED_RUNTIME_TREES[
        str(ROOT / ".venv")
    ] == (
        "d9802d618e8665deac940e1e65520f3d5"
        "aba29b8aff28fadc6f10e7c5a27f0cf"
    )
    _assert_rejected(
        handoff._reauthenticate_sequence12_runtime,
        "Sequence 12 live runtime drift",
    )
    with _source_root_descriptor() as source_root_fd:
        workspace_fd = os.dup(source_root_fd)
        try:
            with patch.object(
                handoff,
                "_reauthenticate_sequence12_runtime",
                side_effect=AssertionError(
                    "historical import read the live runtime"
                ),
            ):
                historical = (
                    handoff._import_sequence12_runtime_history(
                        workspace_fd
                    )
                )
            assert historical == (
                handoff.SEQUENCE12_CURRENT_RUNTIME_PROFILE
            )
            with patch.dict(
                handoff.SEQUENCE12_CURRENT_RUNTIME_PROFILE,
                {"treeSha256": "0" * 64},
            ):
                _assert_rejected(
                    lambda: (
                        handoff._import_sequence12_runtime_history(
                            workspace_fd
                        )
                    ),
                    "Sequence 12 stored runtime digest mutation",
                )
        finally:
            os.close(workspace_fd)
    assert historical["treeSha256"] != handoff._AUTHORIZED_RUNTIME_TREES[
        str(ROOT / ".venv")
    ]


def test_122_sequence12_stack_and_root_expansion_reopen_exactly() -> None:
    with _source_root_descriptor() as source_root_fd:
        stack = handoff._reauthenticate_sequence12_capture_stack(
            source_root_fd
        )
    assert stack["contract"]["sha256"] == (
        handoff.SEQUENCE12_CAPTURE_STACK_REF["sha256"]
    )
    assert stack["digest"] == (
        "5cc960797587028ea31388c6556c569f"
        "fe75455b1d852bbf6d3e733849f5af9d"
    )
    assert len(stack["members"]) == 9
    assert stack["rootExpansion"] == (
        handoff.ROOT_CAPTURE_EXPANSION_REF
    )


def test_123_sequence11_rejected_history_is_imported_not_rebuilt() -> None:
    with _source_root_descriptor() as source_root_fd:
        workspace_fd = os.dup(source_root_fd)
        try:
            history = handoff._import_sequence11_rejected_history(
                workspace_fd,
                source_root_fd,
            )
        finally:
            os.close(workspace_fd)
    assert history["decision"] == "rejected"
    assert history["findingIds"] == [
        "CM-001",
        "CM-002",
        "CM-003",
        "CM-004",
    ]
    assert history["reviewIntake"]["sha256"] == (
        history["manualReview"]["sha256"]
    )
    assert history["reviewIntake"]["path"] != (
        history["manualReview"]["path"]
    )
    assert history["rejectedAfterControls"] == {
        key: handoff.SEQUENCE12_REJECTED_AFTER_CONTROLS_REF[key]
        for key in ("path", "sha256", "size")
    }


def test_124_sequence12_forward_prefix_truth_table_is_exact() -> None:
    fixture_parent = ROOT / ".claude/ui_snapshots/ux1b"
    with tempfile.TemporaryDirectory(
        prefix=".sequence12-prefix-",
        dir=fixture_parent,
    ) as raw:
        fixture_root = Path(raw)
        relative_root = fixture_root.relative_to(ROOT).as_posix()
        paths = tuple(
            f"{relative_root}/leaf-{index}.json"
            for index in range(7)
        )
        flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        workspace_fd = os.open(ROOT, flags)
        try:
            with patch.object(
                handoff,
                "SEQUENCE12_FORWARD_PATHS",
                paths,
            ):
                assert (
                    handoff._classify_capture_binding_forward_prefix(
                        workspace_fd
                    )["state"]
                    == "R0_READY"
                )
                for index, state in enumerate(
                    handoff.CAPTURE_BINDING_FORWARD_STATES[1:]
                ):
                    _write_owned(
                        ROOT / paths[index],
                        handoff._canonical_json_bytes(
                            {"index": index}
                        ),
                        0o600,
                    )
                    assert (
                        handoff._classify_capture_binding_forward_prefix(
                            workspace_fd
                        )["state"]
                        == state
                    )
        finally:
            os.close(workspace_fd)
    with tempfile.TemporaryDirectory(
        prefix=".sequence12-nonprefix-",
        dir=fixture_parent,
    ) as raw:
        fixture_root = Path(raw)
        relative_root = fixture_root.relative_to(ROOT).as_posix()
        paths = tuple(
            f"{relative_root}/leaf-{index}.json"
            for index in range(7)
        )
        _write_owned(
            ROOT / paths[1],
            handoff._canonical_json_bytes({"index": 1}),
            0o600,
        )
        workspace_fd = os.open(
            ROOT,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            with patch.object(
                handoff,
                "SEQUENCE12_FORWARD_PATHS",
                paths,
            ):
                _assert_rejected(
                    lambda: (
                        handoff._classify_capture_binding_forward_prefix(
                            workspace_fd
                        )
                    ),
                    "Sequence 12 non-prefix state",
                )
        finally:
            os.close(workspace_fd)


