def test_128_sequence12_capture_child_contract_is_exact() -> None:
    environment = {
        **os.environ,
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    direct = handoff._run_sequence12_capture_child(
        (
            sys.executable,
            "-B",
            "-c",
            "import sys;sys.stdout.buffer.write(b'bounded')",
        ),
        environment,
        timeout_seconds=5,
        stream_limit_bytes=64,
    )
    assert direct["returnCode"] == 0
    assert direct["stdout"] == b"bounded"
    assert direct["stderr"] == b""
    assert direct["childrenQuiescent"] is True

    terminated_groups: list[int] = []
    real_terminate = handoff._terminate_sequence12_capture_group

    def terminate(process: subprocess.Popen[bytes]) -> None:
        terminated_groups.append(process.pid)
        real_terminate(process)

    descendant_code = (
        "import subprocess,sys,time;"
        "subprocess.Popen([sys.executable,'-B','-c',"
        "'import time;time.sleep(60)']);"
        "time.sleep(60)"
    )
    with patch.object(
        handoff,
        "_terminate_sequence12_capture_group",
        side_effect=terminate,
    ):
        _assert_rejected(
            lambda: handoff._run_sequence12_capture_child(
                (
                    sys.executable,
                    "-B",
                    "-c",
                    descendant_code,
                ),
                environment,
                timeout_seconds=1,
                stream_limit_bytes=64,
            ),
            "Sequence 12 process-group timeout",
        )
    assert len(terminated_groups) == 1
    try:
        os.killpg(terminated_groups[0], 0)
    except ProcessLookupError:
        pass
    else:
        raise AssertionError(
            "Sequence 12 timed-out process group survived"
        )

    completed = {
        "returnCode": 0,
        "stdout": _canonical(
            {
                "status": "passed",
                "captures": {"passed": 44, "total": 44},
            }
        ),
        "stderr": b"",
        "processGroupId": 12345,
        "childrenQuiescent": True,
    }
    with patch.object(
        handoff,
        "_run_sequence12_capture_child",
        return_value=completed,
    ) as runner:
        result = handoff._run_sequence12_capture_process()
    argv = runner.call_args.args[0]
    assert argv[0] == str(ROOT / ".venv/bin/python")
    assert argv[1:4] == (
        "-B",
        "scripts/ui_ux_snapshot_matrix.py",
        "--out-dir",
    )
    assert "--capture-stack" in argv
    assert argv[argv.index("--capture-stack") + 1] == "seq12"
    assert result["returnCode"] == 0
    assert result["processGroupId"] == 12345
    assert result["childrenQuiescent"] is True
    attacked = copy.deepcopy(completed)
    attacked["stdout"] = _canonical(
        {
            "status": "passed",
            "captures": {"passed": 36, "total": 36},
        }
    )
    with patch.object(
        handoff,
        "_run_sequence12_capture_child",
        return_value=attacked,
    ):
        _assert_rejected(
            handoff._run_sequence12_capture_process,
            "Sequence 12 logical/root count confusion",
        )


