def _assert_requirements_lifecycle_records() -> None:
    expected = (
        (
            ROOT / "requirements.txt",
            "1ab5cc81e8e3aab7a3b48b80449087ddf250d22b12b1a8b9b4f5e46b0e790138",
            351,
        ),
        (
            ROOT / ".claude/ui_snapshots/ux1b/rollback-source/requirements.txt",
            "123fd3ee1559a93cf1e30efcf327dd93f6e8604cfa1a6a13487d6de6f3da7d16",
            426,
        ),
    )
    for path, expected_sha256, expected_size in expected:
        observed = os.lstat(path)
        raw = path.read_bytes()
        reopened = os.lstat(path)
        assert stat.S_ISREG(observed.st_mode)
        assert observed.st_nlink == 1
        assert stat.S_IMODE(observed.st_mode) == 0o644
        assert observed.st_size == expected_size == len(raw)
        assert _sha256(raw) == expected_sha256
        assert (
            observed.st_dev,
            observed.st_ino,
            observed.st_mode,
            observed.st_uid,
            observed.st_gid,
            observed.st_nlink,
            observed.st_size,
            observed.st_mtime_ns,
        ) == (
            reopened.st_dev,
            reopened.st_ino,
            reopened.st_mode,
            reopened.st_uid,
            reopened.st_gid,
            reopened.st_nlink,
            reopened.st_size,
            reopened.st_mtime_ns,
        )
def _with_migrated_requirements_fixture(
    test: Callable[[], None],
) -> Callable[[], None]:
    """Bind migrated live requirements only while replaying legacy Sequence 8."""

    def wrapped() -> None:
        original = copy.deepcopy(handoff.THEME_BATCH_PREIMAGE_SHA256)
        _assert_requirements_lifecycle_records()
        assert (
            original["requirements.txt"]
            == "123fd3ee1559a93cf1e30efcf327dd93f6e8604cfa1a6a13487d6de6f3da7d16"
        )
        try:
            with patch.dict(
                handoff.THEME_BATCH_PREIMAGE_SHA256,
                {
                    "requirements.txt": (
                        "1ab5cc81e8e3aab7a3b48b80449087dd"
                        "f250d22b12b1a8b9b4f5e46b0e790138"
                    )
                },
                clear=False,
            ):
                test()
        finally:
            assert handoff.THEME_BATCH_PREIMAGE_SHA256 == original
            assert (
                handoff.THEME_BATCH_PREIMAGE_SHA256["requirements.txt"]
                == "123fd3ee1559a93cf1e30efcf327dd93f6e8604cfa1a6a13487d6de6f3da7d16"
            )
            _assert_requirements_lifecycle_records()

    wrapped.__name__ = test.__name__
    return wrapped


