def test_133_sequence13_manifest_envelope_and_kind_matrix() -> None:
    value = {
        "schemaVersion": "quant-radar-ui-ux-evidence/v1",
        "status": "passed",
    }
    valid = handoff._canonical_json_bytes(value) + b"\n"
    assert handoff._strict_manifest_json_line(valid) == value
    assert handoff._sequence13_forward_value(
        handoff.SEQUENCE13_FORWARD_PATHS[0],
        valid,
    ) == value
    mutants = (
        valid[:-1],
        valid + b"\n",
        valid[:-1] + b"\r\n",
        b"\xef\xbb\xbf" + valid,
        b" " + valid,
        b'{"schemaVersion":"quant-radar-ui-ux-evidence/v1",'
        b'"schemaVersion":"quant-radar-ui-ux-evidence/v1",'
        b'"status":"passed"}\n',
        b'{"schemaVersion":"quant-radar-ui-ux-evidence/v1",'
        b'"status":"passed","x":NaN}\n',
    )
    for raw in mutants:
        _expect_sequence13_violation(
            lambda raw=raw: handoff._strict_manifest_json_line(
                raw
            )
        )
    _expect_sequence13_violation(
        lambda: handoff._sequence13_forward_value(
            handoff.SEQUENCE13_FORWARD_PATHS[1],
            valid,
        )
    )
    for field, replacement in (
        ("schemaVersion", "wrong/v1"),
        ("status", "failed"),
    ):
        candidate = copy.deepcopy(value)
        candidate[field] = replacement
        raw = handoff._canonical_json_bytes(candidate) + b"\n"
        _expect_sequence13_violation(
            lambda raw=raw: handoff._sequence13_forward_value(
                handoff.SEQUENCE13_FORWARD_PATHS[0],
                raw,
            )
        )


def test_134_sequence13_terminal_import_is_exact_and_mutation_closed() -> None:
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | os.O_DIRECTORY,
    )
    try:
        imported = handoff._import_sequence12_terminal_failed(
            workspace_fd
        )
    finally:
        os.close(workspace_fd)
    assert imported["classification"] == "S12_TERMINAL_FAILED"
    assert imported["excludedFromForwardInputs"] is True
    assert len(imported["tier"]) == 7
    assert len(imported["partialArtifacts"]) == 2

    with tempfile.TemporaryDirectory() as temp:
        root = Path(temp)
        for reference in handoff.SEQUENCE12_TERMINAL_REFS:
            source = ROOT / reference["path"]
            destination = root / reference["path"]
            destination.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            shutil.copy2(source, destination)
        for relative in handoff.SEQUENCE12_TERMINAL_DIRECTORIES:
            os.chmod(root / relative, stat.S_IMODE(
                os.stat(ROOT / relative).st_mode
            ))
        manifest = (
            root / handoff.SEQUENCE12_FORWARD_PATHS[0]
        )
        manifest.write_bytes(manifest.read_bytes()[:-1])
        fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY)
        try:
            _expect_sequence13_violation(
                lambda: handoff._import_sequence12_terminal_failed(
                    fd
                )
            )
        finally:
            os.close(fd)


