def test_136_sequence13_stack_is_current_and_seq12_is_historical() -> None:
    from scripts import ui_ux_evidence

    with _source_root_descriptor() as source_root_fd:
        workspace_fd = os.dup(source_root_fd)
        try:
            _assert_rejected(
                lambda: (
                    handoff._reauthenticate_sequence13_capture_stack(
                        workspace_fd
                    )
                ),
                "Sequence 13 live capture-stack drift",
            )
            with patch.object(
                ui_ux_evidence,
                "_capture_stack_records",
                side_effect=AssertionError(
                    "historical import read live stack members"
                ),
            ):
                stack = (
                    handoff._import_sequence13_capture_stack_history(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )
                )
        finally:
            os.close(workspace_fd)
    assert stack["digest"] == handoff.SEQUENCE13_CAPTURE_STACK_REF[
        "captureStackDigest"
    ]
    assert len(stack["members"]) == 9
    assert stack["rootExpansion"] == handoff.ROOT_CAPTURE_EXPANSION_REF
    assert (
        handoff.SEQUENCE12_CAPTURE_STACK_REF["sha256"]
        != handoff.SEQUENCE13_CAPTURE_STACK_REF["sha256"]
    )
    with tempfile.TemporaryDirectory(
        prefix="sequence13-stack-mutation-",
    ) as temporary:
        temporary_root = Path(temporary)
        relative = Path(
            handoff.SEQUENCE13_CAPTURE_STACK_REF["path"]
        )
        target = temporary_root / relative
        target.parent.mkdir(parents=True)
        payload = (
            ROOT / relative
        ).read_bytes()
        target.write_bytes(payload[:-1] + b" ")
        target.chmod(0o600)
        workspace_fd = os.open(
            temporary_root,
            os.O_RDONLY | os.O_DIRECTORY,
        )
        source_root_fd = os.open(
            ROOT,
            os.O_RDONLY | os.O_DIRECTORY,
        )
        try:
            _assert_rejected(
                lambda: (
                    handoff._import_sequence13_capture_stack_history(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )
                ),
                "Sequence 13 stored capture-stack mutation",
            )
        finally:
            os.close(source_root_fd)
            os.close(workspace_fd)


