def test_143_sequence14_historical_stack_is_zero_read_and_mutation_closed() -> None:
    _require_sequence14(
        "TEST-143",
        "_reauthenticate_legacy_capture_stack_history",
        "LEGACY_HISTORICAL_STACK_REF",
    )
    reference = handoff.LEGACY_HISTORICAL_STACK_REF
    source_path = ROOT / reference["path"]
    with tempfile.TemporaryDirectory(
        prefix="sequence14-legacy-stack-",
    ) as raw:
        fixture_root = Path(raw)
        destination = fixture_root / reference["path"]
        destination.parent.mkdir(parents=True)
        shutil.copy2(source_path, destination)
        os.chmod(destination, 0o600)
        workspace_fd = os.open(
            fixture_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        source_root_fd = os.open(
            ROOT,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            historical = (
                handoff._reauthenticate_legacy_capture_stack_history(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                )
            )
            assert historical["contract"]["sha256"] == (
                reference["sha256"]
            )
            document = json.loads(destination.read_bytes())
            document["workerCatalog"]["totalRows"] += 1
            destination.write_bytes(
                handoff._canonical_json_bytes(document)
            )
            os.chmod(destination, 0o600)
            _expect_sequence14_violation(
                lambda: (
                    handoff._reauthenticate_legacy_capture_stack_history(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )
                )
            )
        finally:
            os.close(source_root_fd)
            os.close(workspace_fd)


