def test_147_sequence14_pax_package_is_deterministic() -> None:
    _require_sequence14(
        "TEST-147",
        "_historical_stack_archive_bytes",
        "HISTORICAL_STACK_PACKAGE_PATHS",
    )
    source_root_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    try:
        first, first_records = handoff._historical_stack_archive_bytes(
            source_root_fd
        )
        second, second_records = handoff._historical_stack_archive_bytes(
            source_root_fd
        )
    finally:
        os.close(source_root_fd)
    assert first == second
    assert first_records == second_records
    with tarfile.open(
        fileobj=io.BytesIO(first),
        mode="r:*",
    ) as archive:
        members = archive.getmembers()
        assert [member.name for member in members] == list(
            handoff.HISTORICAL_STACK_PACKAGE_PATHS
        )
        assert all(
            member.isfile()
            and member.uid == 0
            and member.gid == 0
            and member.uname == ""
            and member.gname == ""
            and member.mtime == 0
            for member in members
        )
    output = io.BytesIO()
    try:
        with tarfile.open(
            fileobj=output,
            mode="w",
            format=tarfile.USTAR_FORMAT,
        ) as archive:
            path = (
                handoff.HISTORICAL_STACK_PLAN_REF["path"]
                + "/"
                + ("sequence14-" * 20)
                + "authority.json"
            )
            member = tarfile.TarInfo(path)
            member.size = 0
            archive.addfile(member, io.BytesIO())
    except ValueError:
        pass
    else:
        raise AssertionError("USTAR accepted the long Sequence 14 path")


def test_148_sequence14_production_comparator_preserves_81_44_125() -> None:
    _require_sequence14(
        "TEST-148",
        "_reauthenticate_legacy_capture_stack_history",
        "_compare_historical_stack_migration",
    )
    with _sequence14_disposable_authority() as fixture:
        bootstrap = handoff._bootstrap_historical_stack_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        preflight = handoff._historical_stack_preflight_lifecycle(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
            verify_only=False,
        )
        compared = handoff._compare_historical_stack_migration(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        reopened = handoff._compare_historical_stack_migration(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        record, payload = (
            handoff._relative_regular_record_and_bytes(
                fixture["workspaceFd"],
                fixture["forward"][0],
            )
        )
        report = handoff._strict_json_bytes(
            payload,
            allow_float=True,
        )
        assert bootstrap["exitCode"] == handoff.EXIT_SUCCESS
        assert preflight["state"] == "H0_READY"
        assert compared["state"] == "H1_REPORT"
        assert compared["created"] is True
        assert reopened["state"] == "H1_REPORT"
        assert reopened["created"] is False
        assert reopened["report"] == handoff._artifact_ref(record)
        assert report["migrationGeometryContract"]["legacy"][
            "sha256"
        ] == handoff.SEQUENCE13_M1_MIGRATION_GEOMETRY_PROFILE[
            "sha256"
        ]
        assert report["migrationGeometryContract"]["legacy"][
            "semanticVolatility"
        ] == handoff.SEQUENCE13_M1_SEMANTIC_VOLATILITY_PROFILE
        attacked_report = copy.deepcopy(report)
        attacked_report["sourceTransition"]["corrected"] = "0" * 64
        _rewrite_owned(
            ROOT / fixture["forward"][0],
            handoff._canonical_json_bytes(attacked_report),
        )
        _expect_sequence14_violation(
            lambda: handoff._compare_historical_stack_migration(
                fixture["workspaceFd"],
                source_root_fd=fixture["sourceRootFd"],
            )
        )
    assert (
        report["pageComparisons"],
        report["controlRootComparisons"],
        report["comparedCaptures"],
        report["legacySemanticOracle"]["comparedCaptures"],
    ) == (81, 44, 125, 117)


def test_149_sequence14_packet_is_five_input_125_and_h2_paused() -> None:
    _require_sequence14(
        "TEST-149",
        "_prepare_historical_stack_review",
        "HISTORICAL_STACK_FORWARD_STATES",
    )
    with _sequence14_disposable_authority() as fixture:
        handoff._bootstrap_historical_stack_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        handoff._historical_stack_preflight_lifecycle(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
            verify_only=False,
        )
        compared = handoff._compare_historical_stack_migration(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        prepared = handoff._prepare_historical_stack_review(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        reopened = handoff._prepare_historical_stack_review(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        packet_record, packet_payload = (
            handoff._relative_regular_record_and_bytes(
                fixture["workspaceFd"],
                fixture["forward"][1],
            )
        )
        packet = handoff._strict_json_bytes(
            packet_payload,
            allow_float=True,
        )
        assert compared["state"] == "H1_REPORT"
        assert prepared["state"] == "H2_PACKET"
        assert prepared["created"] is True
        assert reopened["state"] == "H2_PACKET"
        assert reopened["created"] is False
        assert reopened["packet"] == handoff._artifact_ref(
            packet_record
        )
        assert all(
            not (ROOT / relative).exists()
            for relative in fixture["forward"][2:]
        )
        attacked_packet = copy.deepcopy(packet)
        attacked_packet["inputs"] = list(
            reversed(attacked_packet["inputs"])
        )
        _rewrite_owned(
            ROOT / fixture["forward"][1],
            handoff._canonical_json_bytes(attacked_packet),
        )
        _expect_sequence14_violation(
            lambda: handoff._prepare_historical_stack_review(
                fixture["workspaceFd"],
                source_root_fd=fixture["sourceRootFd"],
            )
        )
    assert len(packet["inputs"]) == 5
    assert len(packet["items"]) == 125
    assert len({item["id"] for item in packet["items"]}) == 125
    assert handoff.HISTORICAL_STACK_FORWARD_STATES[2] == "H2_PACKET"


