def test_151_sequence14_scope_candidate_and_formal_absence_are_exact() -> None:
    _require_sequence14(
        "TEST-151",
        "_parse_historical_stack_authorization_record",
        "HISTORICAL_STACK_TIER_DESTINATIONS",
    )
    ast.parse(
        (ROOT / "scripts/ui_ux_theme_handoff.py").read_text(
            encoding="utf-8"
        )
    )
    source_root_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    workspace_fd = os.dup(source_root_fd)
    try:
        parsed = handoff._parse_historical_stack_authorization_record(
            source_root_fd
        )
        tier_present = [
            handoff._relative_leaf_lstat(workspace_fd, path) is not None
            for path in handoff.HISTORICAL_STACK_TIER_DESTINATIONS[1:]
        ]
        current = handoff._classify_historical_stack_forward_prefix(
            workspace_fd
        )
        if not any(tier_present):
            assert current["state"] == "H0_READY"
        else:
            assert all(tier_present[:-1])
            sequence15_active = hasattr(
                handoff,
                "_import_sequence14_h2_packet",
            )
            if sequence15_active:
                _expect_sequence14_violation(
                    lambda: (
                        handoff._validate_historical_stack_tier_complete(
                            workspace_fd,
                            source_root_fd,
                        )
                    )
                )
                assert (
                    handoff._import_sequence14_h2_packet(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )["classification"]
                    == "S14_H2_PACKET"
                )
            else:
                handoff._validate_historical_stack_tier_complete(
                    workspace_fd,
                    source_root_fd,
                )
            if tier_present[-1]:
                if sequence15_active:
                    _expect_sequence14_violation(
                        lambda: (
                            handoff._reauthenticate_historical_stack_preflight(
                                workspace_fd,
                                source_root_fd,
                            )
                        )
                    )
                else:
                    _, preflight, current = (
                        handoff._reauthenticate_historical_stack_preflight(
                            workspace_fd,
                            source_root_fd,
                        )
                    )
                    assert (
                        handoff._validate_historical_stack_forward_semantics(
                            workspace_fd,
                            source_root_fd,
                            preflight=preflight,
                        )["state"]
                        == current["state"]
                    )
            else:
                assert current["state"] == "H0_READY"
    finally:
        os.close(workspace_fd)
        os.close(source_root_fd)
    assert parsed["sequence"] == 14
    assert parsed["formalPause"] == "H2_PACKET"
    assert parsed["noCaptureAuthority"] is True


def _require_sequence15(test_id: str, *names: str) -> None:
    missing = [name for name in names if not hasattr(handoff, name)]
    if missing:
        raise handoff.ThemeHandoffNotImplemented(
            test_id,
            "Sequence 15 external-review seams: "
            + ", ".join(missing),
        )


def _expect_sequence15_violation(
    callback: Callable[[], object],
) -> None:
    try:
        callback()
    except handoff.ContractViolation:
        return
    raise AssertionError("Sequence 15 mutation was accepted")


def _sequence15_review_value(
    packet: Mapping[str, Any],
    *,
    decision: str = "accepted",
    rejected_item: bool = False,
    blocking_finding: bool = False,
    reviewed_at: str = "2026-07-29T08:00:00Z",
) -> dict[str, Any]:
    items = [
        {
            "id": item["id"],
            "verdict": (
                "rejected"
                if rejected_item and index == 0
                else "accepted"
            ),
            "explanation": f"Independent visual decision {index + 1}.",
        }
        for index, item in enumerate(packet["items"])
    ]
    findings = (
        [
            {
                "id": "SEQ15-FINDING-001",
                "severity": "High",
                "status": "unresolved",
                "summary": "One blocking visual discrepancy remains.",
            }
        ]
        if blocking_finding
        else []
    )
    packet_bytes = handoff._canonical_json_bytes(dict(packet))
    return {
        "schemaVersion": "quant-radar-ui-ux-manual-review/v2",
        "kind": "control-migration",
        "status": decision,
        "reviewedAt": reviewed_at,
        "reviewer": {
            "type": "independent-code-reviewer",
            "id": handoff.EXTERNAL_REVIEW_REVIEWER_ID,
        },
        "packet": {
            "path": handoff.EXTERNAL_REVIEW_FORWARD_PATHS[1],
            "sha256": hashlib.sha256(packet_bytes).hexdigest(),
            "size": len(packet_bytes),
        },
        "promptSha256": packet["promptSha256"],
        "inputs": copy.deepcopy(packet["inputs"]),
        "inputsSha256": packet["inputsSha256"],
        "itemSetSha256": packet["itemSetSha256"],
        "decision": decision,
        "items": items,
        "findings": findings,
    }


