def test_153_sequence15_authority_cli_make_and_budget_are_closed() -> None:
    _require_sequence15(
        "TEST-153",
        "_external_review_authorization_body",
        "_external_review_make_contract",
        "EXTERNAL_REVIEW_ALLOWED_COMMANDS",
    )
    assert (
        handoff.EXTERNAL_REVIEW_CAPTURE_ID,
        handoff.EXTERNAL_REVIEW_PARENT_CONTINUATION_ID,
        handoff.EXTERNAL_REVIEW_CORRECTION_ID,
        handoff.EXTERNAL_REVIEW_TIER_ID,
    ) == (
        "20260729T040000Z",
        "20260729T060000Z",
        "20260729T070000Z",
        "20260729T071000Z",
    )
    body = handoff._external_review_authorization_body()
    assert body["sequence"] == 15
    assert body["formalPause"] == "E2_REVIEW"
    assert body["noCaptureAuthority"] is True
    assert body["noCandidateAuthority"] is True
    assert body["noRootAuthority"] is True
    assert body["reviewerAppointment"]["reviewerId"] == (
        handoff.EXTERNAL_REVIEW_REVIEWER_ID
    )
    assert body["reviewerSubmissionCapability"]["maxBytes"] == 16_777_216
    assert len(handoff.EXTERNAL_REVIEW_ALLOWED_COMMANDS) == 5
    parser = handoff._build_public_parser()
    registry = handoff._production_public_handlers()
    for command in handoff.EXTERNAL_REVIEW_ALLOWED_COMMANDS:
        argv = [
            command,
            "--capture-id",
            handoff.EXTERNAL_REVIEW_CAPTURE_ID,
            "--parent-continuation-id",
            handoff.EXTERNAL_REVIEW_PARENT_CONTINUATION_ID,
            "--external-review-correction-id",
            handoff.EXTERNAL_REVIEW_CORRECTION_ID,
            "--external-review-tier-id",
            handoff.EXTERNAL_REVIEW_TIER_ID,
        ]
        if command == "submit-historical-stack-review-intake":
            argv.extend(
                [
                    "--intake-stdin",
                    "--accepted-intake-sha256",
                    "1" * 64,
                    "--accepted-intake-size",
                    "1",
                ]
            )
        argv.append("--json")
        args = parser.parse_args(argv)
        handoff._validate_external_review_public_args(args, command)
        assert command in registry
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
