def test_158_sequence15_atomic_publish_reconciles_and_separates_inodes() -> None:
    _require_sequence15(
        "TEST-158",
        "_publish_external_review_payload",
        "_submit_external_review_intake",
        "_publish_external_review",
    )
    with tempfile.TemporaryDirectory(
        prefix=".sequence15-publish-",
        dir=ROOT,
    ) as raw:
        fixture_root = Path(raw)
        relative = fixture_root.relative_to(ROOT).as_posix()
        (fixture_root / "intake").mkdir(mode=0o700)
        (fixture_root / "review").mkdir(mode=0o700)
        workspace_fd = os.open(
            ROOT,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        payload = b'{"decision":"accepted"}'
        try:
            intake = handoff._publish_external_review_payload(
                workspace_fd,
                f"{relative}/intake/value.json",
                payload,
            )
            reopened = handoff._publish_external_review_payload(
                workspace_fd,
                f"{relative}/intake/value.json",
                payload,
            )
            review = handoff._publish_external_review_payload(
                workspace_fd,
                f"{relative}/review/value.json",
                payload,
            )
        finally:
            os.close(workspace_fd)
        assert intake["created"] is True
        assert reopened["created"] is False
        assert reopened["record"]["inode"] == intake["record"]["inode"]
        assert review["record"]["inode"] != intake["record"]["inode"]
        assert (
            (fixture_root / "review/value.json").read_bytes()
            == payload
        )
        workspace_fd = os.open(
            ROOT,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            before_rename = handoff._publish_external_review_payload(
                workspace_fd,
                f"{relative}/intake/before-rename.json",
                payload,
                fault_after="before-rename",
            )
            assert before_rename["exitCode"] == handoff.EXIT_CONTRACT
            assert not (
                fixture_root / "intake/before-rename.json"
            ).exists()
            for boundary in (
                "after-rename",
                "after-parent-fsync",
                "after-reopen",
            ):
                destination = (
                    f"{relative}/intake/{boundary}.json"
                )
                uncertain = (
                    handoff._publish_external_review_payload(
                        workspace_fd,
                        destination,
                        payload,
                        fault_after=boundary,
                    )
                )
                assert uncertain["exitCode"] == handoff.EXIT_UNCERTAIN
                recovered = (
                    handoff._publish_external_review_payload(
                        workspace_fd,
                        destination,
                        payload,
                    )
                )
                assert recovered["exitCode"] == handoff.EXIT_SUCCESS
                assert recovered["created"] is False
            collision = handoff._publish_external_review_payload(
                workspace_fd,
                f"{relative}/intake/value.json",
                b'{"decision":"rejected"}',
            )
            assert collision["exitCode"] == handoff.EXIT_COLLISION
        finally:
            os.close(workspace_fd)
        assert not any(
            child.name.startswith(".tmp.")
            for child in (fixture_root / "intake").iterdir()
        )
        _expect_sequence15_violation(
            lambda: handoff._read_external_review_stdin(
                io.BytesIO(b"")
            )
        )

    packet = json.loads(
        (
            ROOT / handoff.EXTERNAL_REVIEW_FORWARD_PATHS[1]
        ).read_bytes()
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        projections = (
            handoff._import_later_source_projections_history(
                source_root_fd,
                "sequence15",
            )
        )
        runtime_receipt = (
            handoff._import_sequence12_runtime_history(
                workspace_fd
            )
        )
        descriptor_profile = (
            handoff._build_external_review_descriptor_profile()
        )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)

    quadrants = (
        (False, False, "accepted"),
        (True, False, "rejected"),
        (False, True, "rejected"),
        (True, True, "rejected"),
    )
    for rejected_item, blocking_finding, decision in quadrants:
        with tempfile.TemporaryDirectory(
            prefix=".sequence15-flow-",
            dir=ROOT,
        ) as raw:
            fixture_root = Path(raw)
            relative = fixture_root.relative_to(ROOT).as_posix()
            lease = fixture_root / "lease"
            lease.write_bytes(b"")
            os.chmod(lease, 0o600)
            forward = (
                handoff.HISTORICAL_STACK_FORWARD_PATHS[0],
                handoff.HISTORICAL_STACK_FORWARD_PATHS[1],
                f"{relative}/intake.json",
                f"{relative}/review.json",
                f"{relative}/candidate.json",
                f"{relative}/root.json",
            )
            tier = (
                handoff.EXTERNAL_REVIEW_TIER_DESTINATIONS[0],
                f"{relative}/lease",
                *handoff.EXTERNAL_REVIEW_TIER_DESTINATIONS[2:],
            )
            preflight = {
                "createdAt": "2026-07-29T07:00:00Z",
                "reviewDeadline": "2026-07-30T07:00:00Z",
                "reviewerAppointment": copy.deepcopy(
                    handoff._external_review_reviewer_appointment()
                ),
                "sourceProjection": copy.deepcopy(
                    projections["sourceProjection"]
                ),
                "supplementalProjection": copy.deepcopy(
                    projections["supplementalProjection"]
                ),
                "runtimeReceipt": copy.deepcopy(runtime_receipt),
                "descriptorProfile": copy.deepcopy(
                    descriptor_profile
                ),
            }
            workspace_fd = os.open(
                ROOT,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            source_root_fd = os.dup(workspace_fd)
            try:
                with (
                    patch.object(
                        handoff,
                        "EXTERNAL_REVIEW_FORWARD_PATHS",
                        forward,
                    ),
                    patch.object(
                        handoff,
                        "EXTERNAL_REVIEW_TIER_DESTINATIONS",
                        tier,
                    ),
                    patch.object(
                        handoff,
                        "EXTERNAL_REVIEW_PREFLIGHT_PATH",
                        tier[-1],
                    ),
                    patch.object(
                        handoff,
                        "_reauthenticate_external_review_preflight",
                        side_effect=lambda workspace, source: (
                            {"path": tier[-1]},
                            preflight,
                            handoff._classify_external_review_forward(
                                workspace
                            ),
                        ),
                    ),
                ):
                    review = _sequence15_review_value(
                        packet,
                        decision=decision,
                        rejected_item=rejected_item,
                        blocking_finding=blocking_finding,
                    )
                    payload = handoff._canonical_json_bytes(review)
                    digest = hashlib.sha256(payload).hexdigest()
                    submitted = (
                        handoff._submit_external_review_intake(
                            workspace_fd,
                            source_root_fd=source_root_fd,
                            payload=payload,
                            accepted_sha256=digest,
                            accepted_size=len(payload),
                            broker_now="2026-07-29T08:00:00Z",
                        )
                    )
                    reconciled = (
                        handoff._submit_external_review_intake(
                            workspace_fd,
                            source_root_fd=source_root_fd,
                            payload=payload,
                            accepted_sha256=digest,
                            accepted_size=len(payload),
                            broker_now="2026-08-02T08:00:00Z",
                        )
                    )
                    published = handoff._publish_external_review(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )
                    reopened = handoff._publish_external_review(
                        workspace_fd,
                        source_root_fd=source_root_fd,
                    )
            finally:
                os.close(source_root_fd)
                os.close(workspace_fd)
            assert submitted["state"] == "E1_INTAKE"
            assert reconciled["created"] is False
            assert published["state"] == "E2_REVIEW"
            assert reopened["created"] is False
            assert {
                submitted["decision"],
                reconciled["decision"],
                published["decision"],
                reopened["decision"],
            } == {decision}
            assert (
                (fixture_root / "intake.json").read_bytes()
                == (fixture_root / "review.json").read_bytes()
            )
            assert (
                (fixture_root / "intake.json").stat().st_ino
                != (fixture_root / "review.json").stat().st_ino
            )
            assert not (fixture_root / "candidate.json").exists()
            assert not (fixture_root / "root.json").exists()


