def test_161_sequence15_pax_scope_and_formal_pause_are_exact() -> None:
    _require_sequence15(
        "TEST-161",
        "_import_sequence15_e0_preflight",
        "_classify_sequence15_lifecycle_presence",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        tier_presence = tuple(
            (ROOT / path).exists()
            for path in handoff.EXTERNAL_REVIEW_TIER_DESTINATIONS[1:]
        )
        forward_presence = tuple(
            (ROOT / path).exists()
            for path in handoff.EXTERNAL_REVIEW_FORWARD_PATHS
        )
        lifecycle = handoff._classify_sequence15_lifecycle_presence(
            tier_presence,
            forward_presence,
            sequence16_active=(
                ROOT
                / handoff.LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH
            ).exists(),
        )
        if lifecycle == "S15_E0_PACKET":
            imported = handoff._import_sequence15_e0_preflight(
                workspace_fd,
                source_root_fd=source_root_fd,
                require_initial=False,
            )
            assert imported["classification"] == "S15_E0_PACKET"
            assert imported["preflight"]["sha256"] == (
                "21b2ba6fed6e84f820feb1a091348be6"
                "e7be7c048d196fb79ef5d7489264485a"
            )
            assert imported["archive"]["sha256"] == (
                "15a4bee9a1a2df0b0390e03d4d93c335"
                "95f903d6f0b930388e7bdfe4e84e1ce9"
            )
        else:
            assert lifecycle in {
                "S15_IMPLEMENTATION_BOUNDARY",
                "S15_BOOTSTRAP_BOUNDARY",
            }
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)


def _require_sequence16(test_id: str, *names: str) -> None:
    missing = [name for name in names if not hasattr(handoff, name)]
    if missing:
        raise handoff.ThemeHandoffNotImplemented(
            test_id,
            "Sequence 16 lifecycle-test correction seams: "
            + ", ".join(missing),
        )


def _expect_sequence16_violation(
    callback: Callable[[], object],
) -> None:
    try:
        callback()
    except handoff.ContractViolation:
        return
    raise AssertionError("Sequence 16 mutation was accepted")


def _sequence16_review_value(
    packet: Mapping[str, Any],
    *,
    decision: str = "accepted",
    rejected_item: bool = False,
    blocking_finding: bool = False,
    reviewed_at: str = "2026-07-29T09:00:00Z",
) -> dict[str, Any]:
    value = _sequence15_review_value(
        packet,
        decision=decision,
        rejected_item=rejected_item,
        blocking_finding=blocking_finding,
        reviewed_at=reviewed_at,
    )
    value["reviewer"]["id"] = (
        handoff.LIFECYCLE_TEST_CORRECTION_REVIEWER_ID
    )
    value["packet"]["path"] = (
        handoff.LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
    )
    return value


def test_162_sequence16_imports_exact_sequence15_e0_without_live_reads() -> None:
    _require_sequence16(
        "TEST-162",
        "_import_sequence15_e0_preflight",
        "LIFECYCLE_TEST_CORRECTION_PARENT_REFS",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        prohibited = {
            "_build_external_review_source_projections": getattr(
                handoff,
                "_build_external_review_source_projections",
            ),
            "_build_external_review_preflight_value": getattr(
                handoff,
                "_build_external_review_preflight_value",
            ),
            "_validate_external_review_preflight_value": getattr(
                handoff,
                "_validate_external_review_preflight_value",
            ),
            "_reauthenticate_external_review_preflight": getattr(
                handoff,
                "_reauthenticate_external_review_preflight",
            ),
            "_validate_external_review_tier_complete": getattr(
                handoff,
                "_validate_external_review_tier_complete",
            ),
        }
        with (
            patch.object(
                handoff,
                "_build_external_review_source_projections",
                side_effect=AssertionError("live source projection read"),
            ),
            patch.object(
                handoff,
                "_build_external_review_preflight_value",
                side_effect=AssertionError("live preflight rebuild"),
            ),
            patch.object(
                handoff,
                "_validate_external_review_preflight_value",
                side_effect=AssertionError("live preflight validation"),
            ),
            patch.object(
                handoff,
                "_reauthenticate_external_review_preflight",
                side_effect=AssertionError("live preflight reopen"),
            ),
            patch.object(
                handoff,
                "_validate_external_review_tier_complete",
                side_effect=AssertionError("live Tier rebuild"),
            ),
        ):
            imported = handoff._import_sequence15_e0_preflight(
                workspace_fd,
                source_root_fd=source_root_fd,
                require_initial=False,
            )
        assert imported["classification"] == "S15_E0_PACKET"
        assert imported["sourceProjection"]["records"]
        assert len(imported["sourceProjection"]["records"]) == 270
        assert len(imported["supplementalProjection"]["records"]) == 61
        assert prohibited
        mutant = copy.deepcopy(
            handoff.LIFECYCLE_TEST_CORRECTION_PARENT_REFS
        )
        mutant[9]["sha256"] = "0" * 64
        with patch.object(
            handoff,
            "LIFECYCLE_TEST_CORRECTION_PARENT_REFS",
            tuple(mutant),
        ):
            _expect_sequence16_violation(
                lambda: handoff._import_sequence15_e0_preflight(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                    require_initial=False,
                )
            )
        original_exact_record = handoff._external_review_exact_record
        preflight_expected = (
            handoff.LIFECYCLE_TEST_CORRECTION_PARENT_REFS[9]
        )
        preflight_record, preflight_payload = original_exact_record(
            workspace_fd,
            preflight_expected,
            source=False,
        )
        preflight_value = json.loads(preflight_payload)
        preflight_value["runtimeReceipt"]["treeSha256"] = "0" * 64
        mutated_payload = handoff._canonical_json_bytes(
            preflight_value
        )
        mutated_record = copy.deepcopy(preflight_record)
        mutated_record["sha256"] = hashlib.sha256(
            mutated_payload
        ).hexdigest()
        mutated_record["size"] = len(mutated_payload)
        semantic_mutant = copy.deepcopy(
            handoff.LIFECYCLE_TEST_CORRECTION_PARENT_REFS
        )
        semantic_mutant[9]["sha256"] = mutated_record["sha256"]
        semantic_mutant[9]["size"] = mutated_record["size"]

        def _mutated_exact_record(
            root_fd: int,
            expected: Mapping[str, Any],
            *,
            source: bool,
        ) -> tuple[dict[str, Any], bytes]:
            if expected["path"] == preflight_expected["path"]:
                return copy.deepcopy(mutated_record), mutated_payload
            return original_exact_record(
                root_fd,
                expected,
                source=source,
            )

        with (
            patch.object(
                handoff,
                "LIFECYCLE_TEST_CORRECTION_PARENT_REFS",
                tuple(semantic_mutant),
            ),
            patch.object(
                handoff,
                "_external_review_exact_record",
                side_effect=_mutated_exact_record,
            ),
        ):
            _expect_sequence16_violation(
                lambda: handoff._import_sequence15_e0_preflight(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                    require_initial=False,
                )
            )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)


def test_163_sequence16_parent_lifecycle_truth_table_is_closed() -> None:
    _require_sequence16(
        "TEST-163",
        "_classify_sequence15_lifecycle_presence",
    )
    absent_tier = (False,) * 8
    bootstrap_tier = (True,) * 7 + (False,)
    complete_tier = (True,) * 8
    e0 = (True, True, False, False, False, False)
    assert handoff._classify_sequence15_lifecycle_presence(
        absent_tier,
        e0,
        sequence16_active=False,
    ) == "S15_IMPLEMENTATION_BOUNDARY"
    assert handoff._classify_sequence15_lifecycle_presence(
        bootstrap_tier,
        e0,
        sequence16_active=False,
    ) == "S15_BOOTSTRAP_BOUNDARY"
    assert handoff._classify_sequence15_lifecycle_presence(
        complete_tier,
        e0,
        sequence16_active=False,
    ) == "S15_E0_PACKET"
    assert handoff._classify_sequence15_lifecycle_presence(
        complete_tier,
        (True, True, True, False, False, False),
        sequence16_active=True,
    ) == "S15_E0_PACKET"
    for mutant in (
        (True, False, False, False, False, False, False, False),
        (False, False, False, False, False, False, False, True),
        (True, True, True, True, True, True, False, True),
    ):
        _expect_sequence16_violation(
            lambda mutant=mutant: (
                handoff._classify_sequence15_lifecycle_presence(
                    mutant,
                    e0,
                    sequence16_active=False,
                )
            )
        )
    for forward, active in (
        ((True, True, True, False, False, False), False),
        ((True, True, True, True, False, False), False),
        ((True, True, False, False, True, False), True),
        ((True, True, False, False, False, True), True),
    ):
        _expect_sequence16_violation(
            lambda forward=forward, active=active: (
                handoff._classify_sequence15_lifecycle_presence(
                    complete_tier,
                    forward,
                    sequence16_active=active,
                )
            )
        )


