def test_165_sequence16_forward_truth_table_has_only_three_states() -> None:
    _require_sequence16(
        "TEST-165",
        "_classify_lifecycle_test_correction_presence",
    )
    accepted = {
        (True, True, False, False, False, False): "C0_PACKET",
        (True, True, True, False, False, False): "C1_INTAKE",
        (True, True, True, True, False, False): "C2_REVIEW",
    }
    for mask in range(64):
        presence = tuple(
            bool(mask & (1 << index)) for index in range(6)
        )
        if presence in accepted:
            assert (
                handoff._classify_lifecycle_test_correction_presence(
                    presence
                )
                == accepted[presence]
            )
        else:
            _expect_sequence16_violation(
                lambda presence=presence: (
                    handoff._classify_lifecycle_test_correction_presence(
                        presence
                    )
                )
            )


def test_166_sequence16_reviewer_authority_and_decision_truth_are_exact() -> None:
    _require_sequence16(
        "TEST-166",
        "_validate_external_review_manual_review_for_authority",
        "_lifecycle_test_correction_reviewer_appointment",
    )
    packet = json.loads(
        (
            ROOT
            / handoff.LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
        ).read_bytes()
    )
    packet_bytes = handoff._canonical_json_bytes(packet)
    appointment = (
        handoff._lifecycle_test_correction_reviewer_appointment()
    )
    preflight = {
        "createdAt": "2026-07-29T08:00:00Z",
        "reviewDeadline": "2026-07-30T08:00:00Z",
        "reviewerAppointment": copy.deepcopy(appointment),
    }
    for rejected_item, blocking_finding, decision in (
        (False, False, "accepted"),
        (True, False, "rejected"),
        (False, True, "rejected"),
        (True, True, "rejected"),
    ):
        review = _sequence16_review_value(
            packet,
            decision=decision,
            rejected_item=rejected_item,
            blocking_finding=blocking_finding,
        )
        payload = handoff._canonical_json_bytes(review)
        validated = (
            handoff._validate_external_review_manual_review_for_authority(
                review,
                packet,
                packet_path=(
                    handoff.LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
                ),
                packet_bytes=packet_bytes,
                preflight=preflight,
                expected_appointment=appointment,
                accepted_sha256=hashlib.sha256(payload).hexdigest(),
                accepted_size=len(payload),
                broker_now="2026-07-29T09:00:00Z",
                initial_submission=True,
                review_window_seconds=86_400,
                clock_skew_seconds=300,
                max_intake_bytes=16_777_216,
                contract_label="Sequence 16",
            )
        )
        assert validated["decision"] == decision
    wrong = _sequence16_review_value(packet)
    wrong["reviewer"]["id"] = handoff.EXTERNAL_REVIEW_REVIEWER_ID
    wrong_payload = handoff._canonical_json_bytes(wrong)
    _expect_sequence16_violation(
        lambda: (
            handoff._validate_external_review_manual_review_for_authority(
                wrong,
                packet,
                packet_path=(
                    handoff.LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
                ),
                packet_bytes=packet_bytes,
                preflight=preflight,
                expected_appointment=appointment,
                accepted_sha256=(
                    hashlib.sha256(wrong_payload).hexdigest()
                ),
                accepted_size=len(wrong_payload),
                broker_now="2026-07-29T09:00:00Z",
                initial_submission=True,
                review_window_seconds=86_400,
                clock_skew_seconds=300,
                max_intake_bytes=16_777_216,
                contract_label="Sequence 16",
            )
        )
    )


