def _require_sequence17(test_id: str, *names: str) -> None:
    missing = [name for name in names if not hasattr(handoff, name)]
    if missing:
        raise handoff.ThemeHandoffNotImplemented(
            test_id,
            "Sequence 17 formal-state oracle correction seams: "
            + ", ".join(missing),
        )


