def test_180_sequence18_scope_and_lifecycle_state_are_exact() -> None:
    _require_sequence18(
        "TEST-180",
        "_classify_o1_lifecycle_test_correction_workspace",
        "O1_LIFECYCLE_TEST_CORRECTION_FORMAL_PATHS",
    )
    _require_sequence19(
        "TEST-180",
        "_import_sequence18_v1_intake",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        before = _namespace_paths(ROOT)
        classified = handoff._import_sequence18_v1_intake(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=False,
        )
        assert classified["classification"] == "S18_V1_INTAKE"
        assert _namespace_paths(ROOT) == before
        tier_paths = (
            handoff.O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1:]
        )
        original_lstat = handoff._relative_leaf_lstat
        for prefix in range(1, 7):
            present = set(tier_paths[:prefix])

            def partial_lstat(
                descriptor: int,
                relative: str,
                *,
                present: set[str] = present,
            ) -> os.stat_result | None:
                if relative in tier_paths:
                    return (
                        os.fstat(workspace_fd)
                        if relative in present
                        else None
                    )
                return original_lstat(descriptor, relative)

            with patch.object(
                handoff,
                "_relative_leaf_lstat",
                side_effect=partial_lstat,
            ):
                _expect_sequence18_violation(
                    lambda: (
                        handoff._classify_o1_lifecycle_test_correction_workspace(
                            workspace_fd, source_root_fd
                        )
                    )
                )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)
    assert not (
        ROOT / handoff.O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[4]
    ).exists()
    assert not (
        ROOT / handoff.O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[5]
    ).exists()


def test_181_sequence17_traceability_and_formal_pause_are_exact() -> None:
    _require_sequence17(
        "TEST-181",
        "_formal_state_oracle_correction_authorization_body",
        "FORMAL_STATE_ORACLE_CORRECTION_PLAN_REF",
        "FORMAL_STATE_ORACLE_CORRECTION_LEDGER_REF",
    )
    plan = ROOT / handoff.FORMAL_STATE_ORACLE_CORRECTION_PLAN_REF["path"]
    ledger_path = (
        ROOT / handoff.FORMAL_STATE_ORACLE_CORRECTION_LEDGER_REF["path"]
    )
    assert hashlib.sha256(plan.read_bytes()).hexdigest() == (
        handoff.FORMAL_STATE_ORACLE_CORRECTION_PLAN_REF["sha256"]
    )
    assert hashlib.sha256(ledger_path.read_bytes()).hexdigest() == (
        handoff.FORMAL_STATE_ORACLE_CORRECTION_LEDGER_REF["sha256"]
    )
    ledger = json.loads(ledger_path.read_bytes())
    assert ledger["coverageBasisPoints"] == 10_000
    assert ledger["gaps"] == []
    assert ledger["orphans"] == []
    assert {row["id"] for row in ledger["tests"]} == {
        "TEST-170",
        *(f"TEST-{index:03d}" for index in range(172, 182)),
    }
    body = handoff._formal_state_oracle_correction_authorization_body()
    assert body["formalPause"] == "O2_REVIEW"
    assert body["forwardStates"] == [
        "O0_PACKET",
        "O1_INTAKE",
        "O2_REVIEW",
    ]
    assert body["noCandidateAuthority"] is True
    assert body["noRootAuthority"] is True
    assert set(handoff._production_public_handlers()) == set(
        handoff.PUBLIC_COMMANDS
    )


