def test_182_sequence18_imports_exact_sequence17_o1_without_live_reads() -> None:
    _require_sequence18(
        "TEST-182",
        "_import_sequence17_o1_intake",
        "O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        prohibited = (
            "_build_formal_state_oracle_correction_source_projections",
            "_build_formal_state_oracle_correction_preflight_value",
            "_validate_formal_state_oracle_correction_preflight_value",
            "_reauthenticate_formal_state_oracle_correction_preflight",
            "_validate_formal_state_oracle_correction_tier_complete",
        )
        patches = [
            patch.object(
                handoff,
                name,
                side_effect=AssertionError(
                    "Sequence 17 live validation was invoked"
                ),
            )
            for name in prohibited
        ]
        with patches[0], patches[1], patches[2], patches[3], patches[4]:
            imported = handoff._import_sequence17_o1_intake(
                workspace_fd,
                source_root_fd=source_root_fd,
                require_initial=False,
            )
        assert imported["classification"] == "S17_O1_INTAKE"
        assert imported["decision"] == "accepted"
        assert len(imported["sourceProjection"]["records"]) == 270
        assert len(imported["supplementalProjection"]["records"]) == 67
        assert imported["intake"]["sha256"] == (
            "cf95412e50f6dc7b6608752010d9bb791"
            "c77168e3fc913ecb9843d1e1d427081"
        )
        mutant = copy.deepcopy(
            handoff.O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS
        )
        mutant[12]["sha256"] = "0" * 64
        mutant_pins = list(
            handoff.O1_LIFECYCLE_TEST_CORRECTION_PARENT_SHA256
        )
        mutant_pins[12] = "0" * 64
        with (
            patch.object(
                handoff,
                "O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS",
                tuple(mutant),
            ),
            patch.object(
                handoff,
                "O1_LIFECYCLE_TEST_CORRECTION_PARENT_SHA256",
                tuple(mutant_pins),
            ),
        ):
            _expect_sequence18_violation(
                lambda: handoff._import_sequence17_o1_intake(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                    require_initial=False,
                )
            )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)


def test_183_sequence18_parent_v1_and_disposable_lifecycle_are_closed() -> None:
    _require_sequence18(
        "TEST-183",
        "_classify_o1_lifecycle_test_correction_workspace",
        "_classify_o1_lifecycle_test_correction_forward",
    )
    _require_sequence19(
        "TEST-183",
        "_import_sequence18_v1_intake",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        before = _namespace_paths(ROOT)
        initial = handoff._import_sequence18_v1_intake(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=False,
        )
        assert initial["classification"] == "S18_V1_INTAKE"
        assert _namespace_paths(ROOT) == before
        original_lstat = handoff._relative_leaf_lstat

        def later_review(
            descriptor: int,
            relative: str,
        ) -> os.stat_result | None:
            if (
                relative
                == handoff.O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[
                    3
                ]
            ):
                return os.fstat(workspace_fd)
            return original_lstat(descriptor, relative)

        with patch.object(
            handoff,
            "_relative_leaf_lstat",
            side_effect=later_review,
        ):
            _expect_sequence18_violation(
                lambda: handoff._import_sequence17_o1_intake(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                    require_initial=True,
                )
            )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)
    with _sequence18_lifecycle_fixture() as fixture:
        bootstrap = handoff._bootstrap_o1_lifecycle_test_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        assert bootstrap["state"] == "V0_BOOTSTRAPPED"
        assert (
            handoff._classify_o1_lifecycle_test_correction_workspace(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )["state"]
            == "V0_BOOTSTRAPPED"
        )
        preflight = (
            handoff._o1_lifecycle_test_correction_preflight_lifecycle(
                fixture["workspaceFd"],
                source_root_fd=fixture["sourceRootFd"],
                verify_only=False,
            )
        )
        assert preflight["state"] == "V1_INTAKE"


