def test_186_sequence18_material_geometry_and_descriptor_floor_are_exact() -> None:
    with _sequence18_lifecycle_fixture() as fixture:
        handoff._bootstrap_o1_lifecycle_test_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        handoff._o1_lifecycle_test_correction_preflight_lifecycle(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
            verify_only=False,
        )
        preflight_record, preflight, current = (
            handoff._reauthenticate_o1_lifecycle_test_correction_preflight(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )
        )
        materials = handoff._o1_lifecycle_test_correction_material_refs(
            current["values"][1],
            preflight,
            preflight_record,
        )
        assert (
            len(preflight["sourceProjection"]["records"]),
            len(preflight["supplementalProjection"]["records"]),
            materials["contentCount"],
            materials["authorityCount"],
            materials["retainedCount"],
            materials["requiredSoftFloor"],
        ) == (270, 73, 634, 16, 650, 966)
        before_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
        with handoff._historical_external_review_material_transaction(
            fixture["workspaceFd"],
            fixture["sourceRootFd"],
            materials["references"],
            preflight["descriptorProfile"],
            preflight,
            "sequence18",
        ) as retained:
            assert retained["count"] == 650
            retained["reauthenticate"]()
            authority = os.stat(
                ROOT
                / handoff.HISTORICAL_SOURCE_PROJECTION_REFS[
                    "sequence18"
                ]["path"]
            )
            original_fstat = handoff.os.fstat

            def drifted_mode(fd: int) -> os.stat_result:
                observed = original_fstat(fd)
                if (
                    observed.st_dev,
                    observed.st_ino,
                ) == (
                    authority.st_dev,
                    authority.st_ino,
                ):
                    fields = list(observed)
                    fields[0] = (
                        stat.S_IFMT(observed.st_mode) | 0o400
                    )
                    return os.stat_result(fields)
                return observed

            with patch.object(
                handoff.os,
                "fstat",
                side_effect=drifted_mode,
            ):
                _assert_rejected(
                    retained["reauthenticate"],
                    "historical source authority mode drift",
                )
        historical_receipt = (
            handoff._historical_source_material_receipt(
                fixture["sourceRootFd"],
                preflight,
                "sequence18",
            )
        )
        projected_path = "app.py"
        assert (
            historical_receipt["references"].pop(projected_path)[
                "mode"
            ]
            == "0444"
        )
        with handoff._external_review_material_transaction(
            fixture["workspaceFd"],
            materials["references"],
            preflight["descriptorProfile"],
            historical_receipt=historical_receipt,
        ) as retained:
            projected = os.stat(ROOT / projected_path)
            original_fstat = handoff.os.fstat

            def drifted_projected_mode(fd: int) -> os.stat_result:
                observed = original_fstat(fd)
                if (
                    observed.st_dev,
                    observed.st_ino,
                ) == (
                    projected.st_dev,
                    projected.st_ino,
                ):
                    fields = list(observed)
                    fields[0] = (
                        stat.S_IFMT(observed.st_mode) | 0o755
                    )
                    return os.stat_result(fields)
                return observed

            with patch.object(
                handoff.os,
                "fstat",
                side_effect=drifted_projected_mode,
            ):
                _assert_rejected(
                    retained["reauthenticate"],
                    "live material projected mode drift",
                )
        assert resource.getrlimit(resource.RLIMIT_NOFILE) == before_limit


def test_187_sequence18_publication_and_v2_reconcile_are_atomic() -> None:
    with _sequence18_lifecycle_fixture() as fixture:
        handoff._bootstrap_o1_lifecycle_test_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        handoff._o1_lifecycle_test_correction_preflight_lifecycle(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
            verify_only=False,
        )
        interrupted = (
            handoff._publish_o1_lifecycle_test_corrected_review(
                fixture["workspaceFd"],
                source_root_fd=fixture["sourceRootFd"],
                fault_after="after-rename",
            )
        )
        assert interrupted["exitCode"] == handoff.EXIT_UNCERTAIN
        published = handoff._publish_o1_lifecycle_test_corrected_review(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        reconciled = handoff._publish_o1_lifecycle_test_corrected_review(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        assert published["state"] == "V2_REVIEW"
        assert published["created"] is False
        assert reconciled["state"] == "V2_REVIEW"
        assert reconciled["created"] is False
        intake = ROOT / fixture["forward"][2]
        review = ROOT / fixture["forward"][3]
        assert review.read_bytes() == intake.read_bytes()
        assert review.stat().st_ino != intake.stat().st_ino
        assert not any(
            path.name.startswith(".tmp.")
            for path in review.parent.iterdir()
        )


