def test_192_sequence18_component_policy_and_boundaries_are_exact() -> None:
    pattern = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}")
    active_components = [
        Path(relative).name
        for relative in (
            handoff.O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1:]
        )
    ]
    rejected_components = [
        (
            ".external-review-o1-lifecycle-test-correction-"
            "20260730T030000Z.lease"
        ),
        (
            ".quant-radar-theme-handoff-external-review-o1-"
            "lifecycle-test-correction-owner"
        ),
    ]
    assert len(active_components) == 8
    assert all(pattern.fullmatch(name) for name in active_components)
    assert not any(
        pattern.fullmatch(name) for name in rejected_components
    )
    assert pattern.fullmatch("A" * 128)
    assert pattern.fullmatch("A" * 129) is None
    accepted = [
        "A",
        "A.b-c_1",
        "Z" * 128,
        *active_components,
    ]
    rejected: list[object] = [
        "",
        ".",
        "..",
        ".hidden",
        "A/B",
        "Z" * 129,
        1,
        None,
        *rejected_components,
    ]
    assert all(
        handoff._is_normalized_publisher_component(value)
        for value in accepted
    )
    assert not any(
        handoff._is_normalized_publisher_component(value)
        for value in rejected
    )
    with tempfile.TemporaryDirectory(
        prefix=".sequence18-publisher-"
    ) as raw:
        parent_fd = os.open(
            raw,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            for name in active_components:
                result = handoff._publish_regular_exact(
                    parent_fd,
                    name,
                    name.encode("ascii"),
                )
                assert result["exitCode"] == handoff.EXIT_SUCCESS
                assert result["created"] is True
        finally:
            os.close(parent_fd)


