def test_202_sequence19_workspace_has_only_four_states() -> None:
    _require_sequence19(
        "TEST-202",
        "_classify_v1_lifecycle_test_correction_workspace",
        "V1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS",
    )
    workspace_fd = os.open(
        ROOT,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
    )
    source_root_fd = os.dup(workspace_fd)
    try:
        assert (
            handoff._classify_v1_lifecycle_test_correction_workspace(
                workspace_fd,
                source_root_fd,
            )["state"]
            == "IMPLEMENTATION_BOUNDARY"
        )
    finally:
        os.close(source_root_fd)
        os.close(workspace_fd)
    with _sequence19_lifecycle_fixture() as fixture:
        states = ["IMPLEMENTATION_BOUNDARY"]
        handoff._bootstrap_v1_lifecycle_test_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        states.append(
            handoff._classify_v1_lifecycle_test_correction_workspace(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )["state"]
        )
        handoff._v1_lifecycle_test_correction_preflight_lifecycle(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
            verify_only=False,
        )
        states.append(
            handoff._classify_v1_lifecycle_test_correction_workspace(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )["state"]
        )
        handoff._publish_v1_lifecycle_test_corrected_review(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        states.append(
            handoff._classify_v1_lifecycle_test_correction_workspace(
                fixture["workspaceFd"],
                fixture["sourceRootFd"],
            )["state"]
        )
        assert states == [
            "IMPLEMENTATION_BOUNDARY",
            "W0_BOOTSTRAPPED",
            "W1_READY",
            "W2_REVIEW",
        ]


def test_203_sequence19_partial_and_mixed_states_fail_closed() -> None:
    _require_sequence19(
        "TEST-203",
        "_validate_v1_lifecycle_test_correction_prefix",
        "_validate_v1_lifecycle_test_correction_rejected_paths_absent",
    )
    with _sequence19_lifecycle_fixture() as fixture:
        handoff._bootstrap_v1_lifecycle_test_correction(
            fixture["workspaceFd"],
            source_root_fd=fixture["sourceRootFd"],
        )
        original_lstat = handoff._relative_leaf_lstat
        missing = fixture["tier"][2]

        def gap(
            descriptor: int,
            relative: str,
        ) -> os.stat_result | None:
            if relative == missing:
                return None
            return original_lstat(descriptor, relative)

        with patch.object(
            handoff,
            "_relative_leaf_lstat",
            side_effect=gap,
        ):
            _expect_sequence19_violation(
                lambda: (
                    handoff
                    ._classify_v1_lifecycle_test_correction_workspace(
                        fixture["workspaceFd"],
                        fixture["sourceRootFd"],
                    )
                )
            )
        original_lstat = handoff._relative_leaf_lstat
        tier_paths = fixture["tier"][1:]
        for prefix in range(1, 7):
            present = set(tier_paths[:prefix])

            def partial(
                descriptor: int,
                relative: str,
                *,
                present: set[str] = present,
            ) -> os.stat_result | None:
                if relative in tier_paths:
                    return (
                        original_lstat(descriptor, relative)
                        if relative in present
                        else None
                    )
                return original_lstat(descriptor, relative)

            with patch.object(
                handoff,
                "_relative_leaf_lstat",
                side_effect=partial,
            ):
                _expect_sequence19_violation(
                    lambda: (
                        handoff
                        ._classify_v1_lifecycle_test_correction_workspace(
                            fixture["workspaceFd"],
                            fixture["sourceRootFd"],
                        )
                    )
                )


