def test_206_sequence19_bootstrap_and_preflight_are_create_once() -> None:
    _require_sequence19(
        "TEST-206",
        "_bootstrap_v1_lifecycle_test_correction",
        "_v1_lifecycle_test_correction_preflight_lifecycle",
    )
