def main() -> int:
    global _CURRENT_TEST_ID
    expected_ids = tuple(
        [f"TEST-{index:03d}" for index in range(1, 46)]
        + [f"TEST-{index:03d}" for index in range(67, 108)]
        + [f"TEST-{index:03d}" for index in range(120, 210)]
    )
    assert tuple(test_id for test_id, _ in TESTS) == expected_ids
    assert len({id(test) for _, test in TESTS}) == len(expected_ids)
    before = _guard_snapshot()
    passed = 0
    controlled_red = 0
    unexpected = 0
    try:
        for test_id, test in TESTS:
            _CURRENT_TEST_ID = test_id
            try:
                test()
            except handoff.ThemeHandoffNotImplemented as exc:
                if test_id not in exc.test_ids:
                    unexpected += 1
                    print(f"  UNEXPECTED {test_id} {test.__name__}: wrong missing-behavior ids {exc.test_ids}")
                else:
                    controlled_red += 1
                    print(f"  FAIL {test_id} {test.__name__}: {type(exc).__name__}: {exc}")
            except Exception as exc:  # noqa: BLE001 - aggregate all independent contract tests
                unexpected += 1
                print(f"  UNEXPECTED {test_id} {test.__name__}: {type(exc).__name__}: {exc}")
            else:
                passed += 1
                print(f"  PASS {test_id} {test.__name__}")
            finally:
                _CURRENT_TEST_ID = None
    finally:
        after = _guard_snapshot()
    if after != before:
        unexpected += 1
        print("  UNEXPECTED WORKSPACE-GUARD: protected or lifecycle path changed")
    print(
        f"\n{passed}/{len(expected_ids)} passed; "
        f"{controlled_red} controlled missing-behavior failures; "
        f"{unexpected} unexpected failures"
    )
    return 1 if controlled_red or unexpected else 0


if __name__ == "__main__":
    raise SystemExit(main())
